        box-sizing: border-box;
    }}

    @page {{
        size: A4;
        margin: 2cm 1.5cm;
        @bottom-right {{
            content: "Page " counter(page) " of " counter(pages);
            font-family: 'Segoe UI', Arial, sans-serif;
            font-size: 9pt;
            color: #666;
        }}
    }}

    body {{
        font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
        line-height: 1.6;
        color: #333;
        background-color: #fff;
        font-size: 11pt;
        max-width: 900px;
        margin: 5px auto;
        padding: 16px;
    }}

    /* Center images */
    img {{
        display: block;
        margin: auto;
        max-width: 100%;
        height: auto;
    }}

    /* In-flow header for first page */
    .report-header {{
        display: flex;
        flex-direction: column;
        align-items: center;
        margin-bottom: 30pt;
        page-break-after: avoid;
    }}

    .header-logo {{
        height: 30px;
        width: auto;
        margin-bottom: 8px;
    }}

    .header-text {{
        font-size: 9pt;
        color: #6c757d;
    }}

    /* Typography */
    h1 {{
        font-size: 24pt;
        font-weight: 700;
        color: #1a365d;
        margin-bottom: 30pt;
        padding-bottom: 15pt;
        border-bottom: 3px solid {palette['primary']};
        page-break-after: avoid;
        text-align: center;
    }}

    h2 {{
        font-size: 18pt;
        font-weight: 600;
        color: #2d3748;
        margin-top: 30pt;
        margin-bottom: 15pt;
        padding-top: 10pt;
        border-top: 2px solid #e2e8f0;
        page-break-after: avoid;
    }}

    h2:first-of-type {{
        border-top: none;
        margin-top: 0;
    }}

    h3 {{
        font-size: 14pt;
        font-weight: 600;
        color: #4a5568;
        margin-top: 20pt;
        margin-bottom: 10pt;
        page-break-after: avoid;
    }}

    p {{
        margin-bottom: 12pt;
        text-align: justify;
        orphans: 2;
        widows: 2;
    }}

    /* Lists */
    ul, ol {{
        margin-bottom: 12pt;
        padding-left: 20pt;
    }}

    li {{
        margin-bottom: 6pt;
        orphans: 2;
        widows: 2;
    }}

    /* Strong text */
    strong {{
        font-weight: 600;
        color: #2d3748;
    }}

    /* Inline code */
    code {{
        font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
        background-color: #f7fafc;
        color: #e53e3e;
        padding: 2pt 4pt;
        border-radius: 3pt;
        font-size: 10pt;
        border: 1px solid #e2e8f0;
    }}

    /* Code blocks */
    pre {{
        background-color: #f8f9fa;
        border: 1px solid #e9ecef;
        border-radius: 6pt;
        padding: 15pt;
        margin: 15pt 0;
        font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
        font-size: 9pt;
        line-height: 1.4;
        overflow-x: auto;
        page-break-inside: auto; /* Allow code blocks to break to prevent large gaps */
        white-space: pre-wrap;
        word-wrap: break-word;
    }}

    pre code {{
        background-color: transparent;
        border: none;
        padding: 0;
        color: #495057;
        font-size: inherit;
    }}

    /* Tables - Anti-overflow system */
    table {{
        width: 100%;
        border-collapse: collapse;
        margin: 20pt 0;
        page-break-inside: avoid;
        table-layout: fixed;
    }}

    /* Table headers */
    thead {{
        background-color: {palette['primary']};
        color: {palette['text']};
    }}

    th {{
        text-align: left;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.3pt;
        border: 1px solid {palette['primary']};
        hyphens: auto;
        overflow-wrap: break-word; /* Use safer wrapping */
        vertical-align: middle;
    }}

    /* Table body */
    tbody tr:nth-child(even) {{
        background-color: #f8f9fa;
    }}

    td {{
        border: 1px solid #e2e8f0;
        vertical-align: top;
        hyphens: auto;
        overflow-wrap: break-word; /* Allow content in cells to wrap */
    }}

    table th, table td {{
        width: auto;
    }}

    /* Special case for 2-column definition tables */
    .definition-table th:nth-of-type(1), .definition-table td:nth-of-type(1) {{ width: 40%; }}
    .definition-table th:nth-of-type(2), .definition-table td:nth-of-type(2) {{ width: 60%; }}

    /* Responsive font and padding based on column count */
    /* 8+ columns - Very compressed */
    table.very-wide-table th, table.very-wide-table td {{
