def get_custom_request_headers(request: Request):
    """
    FastAPI dependency that extracts forwardable custom headers from the
    incoming request, based on FORWARD_CUSTOM_HEADERS. Lives here (not in
    utils.utils) because the `Request` annotation must be available at
    function-definition time, and we keep fastapi out of utils.utils so
    the sample chatbot's import graph stays fastapi-free.
    """
    return filter_allowed_headers(request.headers)

def add_tokens(token_set1, token_set2):
    return {key: token_set1[key] + token_set2[key] for key in ['input_tokens', 'output_tokens', 'total_tokens']}

def generate_session_id(question):
    question_prefix = ''.join(c for c in question[:20] if c.isalpha() or c.isspace())
    question_prefix = question_prefix.replace(' ', '_')
    return f"{question_prefix}_{random.randint(1000,9999)}"

@contextmanager
def timing_context(name, timings):
    start_time = time()
    yield
    elapsed_time = time() - start_time
    if name in timings:
        timings[name] += elapsed_time
    else:
        timings[name] = elapsed_time

    for key, value in timings.items():
        timings[key] = round(value, 2)

def readable_tables(relevant_tables, column_description_char_limit=None, table_description_char_limit=None):
    return SchemaCatalog.from_vector_search_tables(relevant_tables).render_selector_schema(column_description_char_limit, table_description_char_limit)

def match_nested_parentheses(text):
    def find_closing_paren(s, start):
        count = 0
        for i, c in enumerate(s[start:], start):
            if c == '(':
                count += 1
            elif c == ')':
                count -= 1
                if count == 0:
                    return i
        return -1

    matches = []
    start = 0
    while True:
        start = text.find('(', start)
        if start == -1:
            break
        end = find_closing_paren(text, start)
        if end == -1:
            break
        matches.append(text[start:end+1])
        start = end + 1

    return matches

# Static VQL category codes returned by detect_vql_issues.
VQL_ISSUE_LIMIT_SUBQUERY = 'LIMIT_SUBQUERY'
VQL_ISSUE_LIMIT_OFFSET = 'LIMIT_OFFSET'


def normalize_vql(vql):
    """Cleans an LLM-generated VQL query."""
    # Look for LLM code styling
    if '```' in vql:
        logging.info("Backward ticks detected in VQL, fixing...")
        vql = vql.replace('```vql', '').replace('```sql', '').replace('```', '')

    if '\\_' in vql:
        logging.info("Markdown underscore detected in VQL, fixing...")
        vql = vql.replace('\\_', '_')

    vql_single_line = vql.replace('\n', ' ')

    # Protected words for aliases
    protected_words = (
        'ADD|ALL|ALTER|AND|ANY|AS|ASC|BASE|BOTH|CASE|CONNECT|CONTEXT|CREATE|CROSS|'
        'CURRENT_DATE|CURRENT_TIMESTAMP|CUSTOM|DATABASE|DEFAULT|DESC|DF|DISTINCT|DROP|'
        'EXISTS|FALSE|FETCH|FLATTEN|FROM|FULL|GRANT|GROUP BY|HASH|HAVING|HTML|IF|INNER|'
        'INTERSECT|INTO|IS|JDBC|JOIN|LDAP|LEADING|LEFT|LIMIT|LOCALTIME|LOCALTIMESTAMP|'
        'MERGE|MINUS|MY|NATURAL|NESTED|NOS|NOT|NULL|OBL|ODBC|OF|OFF|OFFSET|ON|ONE|OPT|'
        'OR|ORDER BY|ORDERED|PRIVILEGES|READ|REVERSEORDER|REVOKE|RIGHT|ROW|SELECT|SWAP|'
        'TABLE|TO|TRACE|TRAILING|TRUE|UNION|USER|USING|VIEW|WHEN|WHERE|WITH|WRITE|WS|ZERO'
    )

    # Pattern to match protected words used as aliases
    pattern = fr'\s+AS\s+({protected_words})\s+'
    matches = re.finditer(pattern, vql_single_line, re.IGNORECASE)

    # Track all replacements
    replacements = {}
    for match in matches:
        protected_word = match.group(1)
        new_alias = f"{protected_word}_"
        replacements[protected_word] = new_alias
        logging.info(f"Protected word '{protected_word}' used as alias, appending underscore")

    # Apply replacements
    for old_word, new_word in replacements.items():
        # Pattern to match the exact alias after AS
        replace_pattern = fr'(\s+AS\s+){old_word}(\s+)'
        vql = re.sub(replace_pattern, fr'\1{new_word}\2', vql, flags=re.IGNORECASE)

    return vql.strip()

def detect_vql_issues(vql):
    """Read-only static analysis. Detects usage of LIMIT in subquery (a Denodo VQL restriction) in a given VQL query."""
    categories = []
    vql_single_line = vql.replace('\n', ' ')

    # Look for LIMIT/FETCH in subquery (CTEs count as subqueries)
    for match in match_nested_parentheses(vql_single_line):
        if ' LIMIT ' in match or ' FETCH ' in match:
            categories.append(VQL_ISSUE_LIMIT_SUBQUERY)
            break

    if " OFFSET " in vql_single_line:
        categories.append(VQL_ISSUE_LIMIT_OFFSET)

    return categories

def generate_vql_restrictions(
    prompt_parts,
    vql_rules_prompt,
    dates_vql_prompt,
    arithmetic_vql_prompt,
    spatial_vql_prompt = '',
    llm_vql_prompt = '',
    vector_vql_prompt = '',
    metric_vql_prompt = '',
    json_vql_prompt = '',
    xml_vql_prompt = '',
    text_vql_prompt = '',
    aggregate_vql_prompt = '',
    cast_vql_prompt = '',
    window_vql_prompt = ''
):
    if prompt_parts is None:
        return vql_rules_prompt.replace("{EXTRA_RESTRICTIONS}", "")

    vql_prompt_catalog = {
        "dates": dates_vql_prompt,
        "arithmetic": arithmetic_vql_prompt,
        "spatial": spatial_vql_prompt,
        "llm": llm_vql_prompt,
        "vector": vector_vql_prompt,
        "metric": metric_vql_prompt,
        "json": json_vql_prompt,
        "xml": xml_vql_prompt,
        "text": text_vql_prompt,
        "aggregate": aggregate_vql_prompt,
        "cast": cast_vql_prompt,
        "window": window_vql_prompt,
    }

    selected_prompts = [
        vql_prompt_catalog[key]
        for key, enabled in prompt_parts.items()
        if enabled and vql_prompt_catalog.get(key)
    ]

    extra_restrictions = '\n'.join(selected_prompts)
    return vql_rules_prompt.replace("{EXTRA_RESTRICTIONS}", extra_restrictions)

def get_response_format(markdown_response):
    if markdown_response:
        response_format = """
        - Use bold, italics and tables in markdown when appropiate to better illustrate the response.
        - You cannot use markdown headings, instead use titles in bold to separate sections, if needed.
        """
        response_example = "**Cristiano Ronaldo** was the player who scored the most goals last year, with a total of **23 goals**."
    else:
        response_format = "- Use plain text to answer, don't use markdown or any other formatting."
        response_example = "Cristiano Ronaldo was the player who scored the most goals last year, with a total of 23 goals."
    return response_format, response_example

def check_env_variables(required_vars):
    missing_items = []
    for item in required_vars:
        if isinstance(item, str):
            if not os.getenv(item):
                missing_items.append(item)

        elif isinstance(item, (tuple, list)):
            if not any(os.getenv(var) for var in item):
                missing_items.append(" or ".join(item))

    if missing_items:
        print("ERROR. The following required environment variables are missing:")
        for var_name in missing_items:
            print(f"- {var_name}")
        print("Please set these variables before starting the application.")
        sys.exit(1)

def test_data_catalog_connection(data_catalog_url, verify_ssl):
    try:
        response = requests.get(data_catalog_url, verify=verify_ssl, timeout=10)
        response.raise_for_status()
        return True
    except Exception:
        return False

def filter_non_allowed_associations(view_json, valid_view_ids):
    # If valid_view_ids is None, return the original view_json unchanged
    if valid_view_ids is None:
        return view_json

    if 'associations' not in view_json or view_json['associations'] is None:
        return view_json

    # Create a new view_json with filtered associations
    filtered_view_json = view_json.copy()
    filtered_view_json['associations'] = [
        assoc for assoc in view_json['associations']
        if str(assoc['table_id']) in valid_view_ids
    ]

    return filtered_view_json

def handle_endpoint_error(endpoint_name):
    def decorator(func):
        @functools.wraps(func)
        def sync_wrapper(*args, **kwargs):
            # Set the endpoint context
            current_endpoint.set(endpoint_name)
            try:
                return func(*args, **kwargs)
            except requests.exceptions.HTTPError as he:
                if he.response.status_code == 401:
                    raise HTTPException(status_code=401, detail="Unauthorized") from he
                else:
                    error_details = {
                        'error': str(he),
                        'traceback': traceback.format_exc()
                    }
                    logging.error(f"HTTP Error in {endpoint_name}: {error_details}")
                    raise HTTPException(status_code=he.response.status_code, detail=error_details) from he
            except HTTPException as hex:
                # Log the HTTPException but pass it through
                logging.error(f"HTTPException in {endpoint_name}: {str(hex.detail)}")
                raise
            except Exception as e:
                error_details = {
                    'error': str(e),
                    'traceback': traceback.format_exc()
                }
                logging.error(f"Error in {endpoint_name}: {error_details}")
                raise HTTPException(status_code=500, detail=error_details) from e

        @functools.wraps(func)
        async def async_wrapper(*args, **kwargs):
            # Set the endpoint context
            current_endpoint.set(endpoint_name)
            try:
                return await func(*args, **kwargs)
            except requests.exceptions.HTTPError as he:
                if he.response.status_code == 401:
                    logging.error(f"Authentication error in {endpoint_name}: {str(he)}")
                    raise HTTPException(status_code=401, detail="Unauthorized") from he
                else:
                    error_details = {
                        'error': str(he),
                        'traceback': traceback.format_exc()
                    }
                    logging.error(f"HTTP Error in {endpoint_name}: {error_details}")
                    raise HTTPException(status_code=he.response.status_code, detail=error_details) from he
            except aiohttp.ClientResponseError as he:
                if he.status == 401:
                    logging.error(f"Authentication error in {endpoint_name}: {str(he)}")
                    raise HTTPException(status_code=401, detail="Unauthorized") from he
                else:
                    error_details = {
                        'error': str(he),
                        'traceback': traceback.format_exc()
                    }
                    logging.error(f"HTTP Error in {endpoint_name}: {error_details}")
                    raise HTTPException(status_code=he.status, detail=error_details) from he
            except HTTPException as hex:
                # Log the HTTPException but pass it through
                logging.error(f"HTTPException in {endpoint_name}: {str(hex.detail)}")
                raise
            except Exception as e:
                error_details = {
                    'error': str(e),
                    'traceback': traceback.format_exc()
                }
                logging.error(f"Error in {endpoint_name}: {error_details}")
                raise HTTPException(status_code=500, detail=error_details) from e

        # Choose the appropriate wrapper based on whether the function is a coroutine
        if inspect.iscoroutinefunction(func):
            return async_wrapper
        else:
            return sync_wrapper

    return decorator

async def stats_about_data(data, unique_values_limit = 20):
    # Transform into a flat list of rows
    rows = []
    for _, columns in data.items():
        row = {col["columnName"]: col["value"] for col in columns}
        rows.append(row)

    # Now you have a list of dicts
    column_names = set()
    for row in rows:
        column_names.update(row.keys())
    column_names = list(column_names)

    # Analysis
    info = {
        "num_rows": len(rows),
        "num_columns": len(column_names),
        "columns": {}
    }

    for col in column_names:
        values = [row.get(col) for row in rows]
        non_null_values = [v for v in values if v is not None]
        unique_values = list(set(non_null_values))
        num_unique = len(unique_values)

        # Try to infer type
        try:
            floats = [float(v) for v in non_null_values]
            inferred_type = "float"
            min_val = min(floats)
            max_val = max(floats)
        except (ValueError, TypeError):
            inferred_type = "string"
            min_val = None
            max_val = None

        info["columns"][col] = {
            "inferred_type": inferred_type,
            "num_unique": num_unique,
            "min": min_val,
            "max": max_val,
            "num_missing": values.count(None),
        }

        # Only add all unique_values if num_unique <= unique_values_limit
        if num_unique <= unique_values_limit:
            info["columns"][col]["unique_values"] = unique_values

    return str(info)

def dataframe_stats(df, unique_values_limit=20):
    import pandas as pd

    info = {
        "num_rows": len(df),
        "num_columns": len(df.columns),
        "columns": {}
    }

    for col in df.columns:
        values = df[col]
        non_null_values = values.dropna()
        unique_values = non_null_values.unique()
        num_unique = len(unique_values)

        # Determine type and min/max values
        if pd.api.types.is_numeric_dtype(df[col]):
            dtype = str(df[col].dtype)
            min_val = float(non_null_values.min()) if len(non_null_values) > 0 else None
            max_val = float(non_null_values.max()) if len(non_null_values) > 0 else None
        else:
            dtype = str(df[col].dtype)

        info["columns"][col] = {
            "dtype": dtype,
            "num_unique_values": num_unique,
            "num_missing": int(values.isna().sum()),
        }

        if pd.api.types.is_numeric_dtype(df[col]):
            info["columns"][col]["min"] = min_val
            info["columns"][col]["max"] = max_val

        # Only add unique values if number is below the limit
        if num_unique <= unique_values_limit:
            # Convert values to Python native types for serialization
            if pd.api.types.is_numeric_dtype(unique_values):
                info["columns"][col]["unique_values"] = unique_values.tolist()
            else:
                info["columns"][col]["unique_values"] = [str(v) for v in unique_values]

    return str(info)

def authenticate(
        basic_credentials: Annotated[HTTPBasicCredentials | None, Depends(security_basic)],
        bearer_credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(security_bearer)]
        ):
    if bearer_credentials is not None:
        return bearer_credentials.credentials
    elif basic_credentials is not None:
        return (basic_credentials.username, basic_credentials.password)
    else:
        raise HTTPException(status_code=401, detail="Authentication required")

def check_feature_permission(auth, permissions_data, users_env_var, roles_env_var):
    """
    Check if the authenticated user is allowed to use a specific feature.
    - If DM >= 9.4.1: Checks against allowed roles and allowed users.
      Supports both Basic Auth and OAuth.
    - If DM <= 9.4.1: Fallbacks to previous behavior, checking
      only allowed users and requiring Basic Auth.
    - If neither property is set, all authenticated users are allowed.
    """
    allowed_users_raw = os.getenv(users_env_var)
    allowed_roles_raw = os.getenv(roles_env_var)

    if not allowed_users_raw and not allowed_roles_raw:
        return True

    if not permissions_data:
        if not allowed_users_raw or not isinstance(auth, tuple):
            return False
        allowed_users = [u.strip() for u in allowed_users_raw.split(",") if u.strip()]
        return auth[0] in allowed_users

    if permissions_data.get("isAdmin", False):
        return True

    username = permissions_data.get("username", "")
    legacy_endpoint = permissions_data.get("legacyEndpoint", False)

    if allowed_roles_raw:
        if not legacy_endpoint:
            allowed_roles = [r.strip() for r in allowed_roles_raw.split(",") if r.strip()]

            if any(has_role(permissions_data, role) for role in allowed_roles):
                return True

    if allowed_users_raw:
        allowed_users = [u.strip() for u in allowed_users_raw.split(",") if u.strip()]
        current_username = username if username != "unknown" else (auth[0] if isinstance(auth, tuple) else None)

        if current_username and current_username in allowed_users:
            return True

    return False


def check_metadata_user_permission(auth, permissions_data=None):
    """
    Check if the authenticated user is allowed to use metadata endpoints.
    """
    return check_feature_permission(
        auth,
        permissions_data,
        users_env_var="AI_SDK_ALLOWED_METADATA_USERS",
        roles_env_var="AI_SDK_ALLOWED_METADATA_ROLES"
    )


def check_deepquery_user_permission(auth, permissions_data=None):
    """
    Check if the authenticated user is allowed to use the DeepQuery endpoint.
    """
    return check_feature_permission(
        auth,
        permissions_data,
        users_env_var="AI_SDK_ALLOWED_DEEPQUERY_USERS",
        roles_env_var="AI_SDK_ALLOWED_DEEPQUERY_ROLES"
    )

async def process_metadata_source(
    source_type,
    source_name,
    request,
    auth,
    vector_store,
    sample_data_vector_store,
    tagged_views=None,
    incremental=False,
    tags_to_ignore=None,
    custom_headers=None
):
    """
    Process metadata from a source (tag or database).

    Args:
        source_type: 'TAG' or 'DATABASE'
        source_name: Name of the tag or database
        request: Request object with processing parameters
        auth: Authentication credentials
        vector_store: Vector store for metadata
        sample_data_vector_store: Vector store for sample data
        tagged_views: List of views with the requested tag
        incremental: Whether to do incremental sync
        tags_to_ignore: List of tags to exclude from vectorization
        custom_headers: Custom headers to forward to the Data Marketplace

    Returns:
        Tuple of (db_schema, db_schema_text, data_usage_errors, timings)
        where timings is a dict of the detailed timing breakdown per step
    """

    start_total = perf_counter()
    timings = {}

    if vector_store and request.incremental:
        last_update = vector_store.get_last_update(source_type=source_type, source_name=source_name)
    else:
        last_update = None

    kwargs = {
        "auth": auth,
        "examples_per_table": request.examples_per_table,
        "table_descriptions": request.view_descriptions,
        "table_associations": request.associations,
        "table_column_descriptions": request.column_descriptions,
        "last_update_timestamp_ms": last_update,
        "view_prefix_filter": request.view_prefix_filter,
        "view_suffix_filter": request.view_suffix_filter,
        "incremental": incremental,
        "views_per_request": request.views_per_request,
        "custom_headers": custom_headers
    }

    if tags_to_ignore:
        kwargs["tags_to_ignore"] = tags_to_ignore

    if source_type == "TAG":
        kwargs["tag_name"] = source_name
        if tagged_views is not None:
            kwargs["tagged_views"] = tagged_views
    elif source_type == "DATABASE":
        kwargs["database_name"] = source_name
    else:
        raise ValueError(f"Invalid source type: {source_type}")

    start_metadata = perf_counter()
    result, delete_view_ids, detagged_view_ids, data_usage_errors = await get_views_metadata_documents(**kwargs)
    timings['metadata_retrieval'] = perf_counter() - start_metadata

    start_deletions = perf_counter()
    if delete_view_ids and vector_store:
        await asyncio.to_thread(vector_store.delete_by_view_id, view_ids=delete_view_ids)
        if sample_data_vector_store:
            await asyncio.to_thread(sample_data_vector_store.delete_by_view_id, view_ids=delete_view_ids)

    if detagged_view_ids and source_type == 'TAG' and vector_store:
        await handle_detagged_views(
            detagged_view_ids=detagged_view_ids,
            tag_name=source_name,
            vector_store=vector_store,
            sample_data_vector_store=sample_data_vector_store,
            incremental=incremental
        )
    timings['vector_store_deletion'] = perf_counter() - start_deletions

    # Validate response
    if not result:
        logging.info(f"Empty response from the Denodo Data Marketplace for {source_type.lower()} {source_name}")
        timings['total_execution_time'] = perf_counter() - start_total
        return {}, [], data_usage_errors, timings

    # Process schema
    if isinstance(result, dict):
        db_schema = result
        logging.info(f"{source_type} schema for {source_name} has {calculate_tokens(str(db_schema))} tokens.")

        db_schema_text = []
        found_tags_by_db = {} # For each synced DB -> [Partial Tags]
        found_dbs_by_tag = {} # For each synced Tag -> [Partial DBs]
        found_tags_by_tag = {} # For each synced Tag -> [Partial Tags]

        if 'views' in db_schema:
            for view in db_schema['views']:
                db_schema_text.append(schema_summary(view))

                if vector_store:
                    tags = view.get('tagDetails', [])
                    # Get partial tags
                    if tags:
                        for tag in tags:
                            if 'name' in tag:
                                if source_type == "DATABASE":
                                    found_tags_by_db.setdefault(source_name, set()).add(tag['name'])
                                elif source_type == "TAG":
                                    found_tags_by_tag.setdefault(source_name, set()).add(tag['name'])

                    # Get partial DBs
                    if source_type == "TAG":
                        table_name = view.get('tableName', '')
                        if '.' in table_name:
                            db_name = table_name.split('.')[0]
                            if db_name:
                                found_dbs_by_tag.setdefault(source_name, set()).add(db_name)

        if vector_store:
            views = flatten_list(prepare_schema(db_schema, request.embeddings_token_limit))

        start_embedding = perf_counter()
        if vector_store:
            await asyncio.to_thread(
                vector_store.add_views,
                views=views,
                parallel=request.parallel,
                source_type=source_type,
                source_name=source_name,
                tags_by_db=found_tags_by_db,
                dbs_by_tag=found_dbs_by_tag,
                tags_by_tag=found_tags_by_tag
            )
        timings['vector_store_embedding'] = perf_counter() - start_embedding

        start_sample_data = perf_counter()
        if sample_data_vector_store:
            views = flatten_list(prepare_sample_data_schema(db_schema))
            await asyncio.to_thread(
                sample_data_vector_store.add_views,
                views=views,
                parallel=request.parallel,
                source_type=source_type,
                sample_data=True
            )
        timings['sample_data_processing'] = perf_counter() - start_sample_data

        timings['total_execution_time'] = perf_counter() - start_total
        return db_schema, db_schema_text, data_usage_errors, timings

    timings['total_execution_time'] = perf_counter() - start_total
    timings = {k: v for k, v in timings.items() if v > 0}
    return {}, [], data_usage_errors, timings

def format_metadata_response(
    all_db_schemas,
    all_db_schema_texts,
    vdb_database_names,
    vdb_tag_names,
    all_data_usage_errors,
    all_timings
):
    return {
        'db_schema_json': all_db_schemas,
        'db_schema_text': all_db_schema_texts,
        'vdb_list': vdb_database_names,
        'tag_list': vdb_tag_names,
        'data_usage_errors': all_data_usage_errors,
        'timings': all_timings
    }

def is_non_conflicting_doc(doc, databases_to_delete, tags_to_delete, last_update_dict):
        """
        Determines whether a document can be safely deleted without conflicting metadata.

        A document is considered non-conflicting if both of these are true:
        - Its 'database_name' is either:
            - in the databases_to_delete list, or
            - not present in last_update_dict["DATABASE"].
        - For each of its active tags ('tag_' fields with value '1'):
            - If the tag is NOT in tags_to_delete, it must also NOT be in last_update_dict["TAG"].

        This ensures that we don't delete documents whose metadata partially overlaps
        with deletion criteria, unless they're fully safe to remove.
        """
        metadata = doc.metadata or {}

        db_name = metadata.get("database_name")
        last_updated_dbs = set(last_update_dict.get("DATABASE", []))
        last_updated_tags = set(last_update_dict.get("TAG", []))

        db_match = (
            db_name in databases_to_delete or
            db_name not in last_updated_dbs
        )

        tags_to_delete_full = {f"tag_{tag}" for tag in tags_to_delete}
        last_updated_tags_full = {f"tag_{tag}" for tag in last_updated_tags}

        for k, v in metadata.items():
            if k.startswith("tag_") and v == "1":
                if k not in tags_to_delete_full and k in last_updated_tags_full:
                    return False

        return db_match

async def delete_by_db_or_tag(vector_store, sample_data_vector_store, vdp_database_names, vdp_tag_names, delete_conflicting, allowed_view_ids=None):

    """
    Deletes views based on database/tag names.
    """
    K_BATCH_SIZE = 1000
    total_deleted_ids = 0
    more_results_left = True

    while more_results_left:
        results = await asyncio.to_thread(
            vector_store.search_batched,
            vector=vector_store.search_vector,
            k=K_BATCH_SIZE,
            database_names=vdp_database_names,
            tag_names=vdp_tag_names,
            view_ids=allowed_view_ids
        )

        if not results:
            break

        view_ids_to_delete = set()
        document_ids_to_delete = set()

        last_update_dict = vector_store.get_last_update_dict() or {}
        for doc in results:
            if not delete_conflicting:
                if not is_non_conflicting_doc(doc, vdp_database_names, vdp_tag_names, last_update_dict):
                    continue

            view_id = doc.metadata.get('view_id')
            doc_id = doc.metadata.get('document_id')

            if view_id:
                view_ids_to_delete.add(view_id)
            if doc_id:
                document_ids_to_delete.add(doc_id)

        if document_ids_to_delete:
            await asyncio.to_thread(vector_store.delete, ids=list(document_ids_to_delete))

        if view_ids_to_delete:
            total_deleted_ids += len(view_ids_to_delete)
            if sample_data_vector_store:
                await asyncio.to_thread(sample_data_vector_store.delete_by_view_id, view_ids=list(view_ids_to_delete))

        more_results_left = len(results) == K_BATCH_SIZE

    if total_deleted_ids > 0:
        await asyncio.to_thread(
            vector_store.remove_from_last_update,
            database_names=vdp_database_names,
            tag_names=vdp_tag_names
        )

    return total_deleted_ids

async def get_by_db_or_tag(
    vector_store,
    vdp_database_names,
    vdp_tag_names,
    initial_k=1000,
    increment_factor=2,
    max_results_limit=1000000
):
    """
    Retrieves all distinct view_ids associated with a list of databases or tags
    using an exponentially increasing 'k' strategy.

    Args:
        vector_store: The vector store instance.
        vdp_database_names: List of database names to search for.
        vdp_tag_names: List of tag names to search for.
        initial_k: The initial size for 'k'.
        increment_factor: The factor by which to multiply 'k' in each
                          iteration (e.g., 2 for doubling).
        max_results_limit: A safety limit to stop the search.

    Returns:
        A list of unique view_ids that match the criteria.
    """
    current_k = initial_k
    all_results = []

    while True:
        if current_k > max_results_limit:
            logging.warning(f"K limit ({max_results_limit}) reached. Returning partial results.")
            all_results = await asyncio.to_thread(
                vector_store.search_by_vector,
                vector=vector_store.search_vector,
                k=max_results_limit,
                database_names=vdp_database_names,
                tag_names=vdp_tag_names
            )
            break

        results = await asyncio.to_thread(
            vector_store.search_by_vector,
            vector=vector_store.search_vector,
            k=current_k,
            database_names=vdp_database_names,
            tag_names=vdp_tag_names
        )

        if len(results) < current_k:
            all_results = results
            break

        current_k = int(current_k * increment_factor)

    unique_view_ids = set()
    for doc in all_results:
        view_id_str = doc.metadata.get('view_id')
        if view_id_str:
            try:
                view_id_int = int(view_id_str)
                unique_view_ids.add(view_id_int)
            except (ValueError, TypeError):
                continue

    return list(unique_view_ids)

def execution_result_to_dataframe(data):
    import pandas as pd

    # Initialize an empty list to store row data
    rows = []

    # Sort the keys to preserve order (e.g., "Row 1", "Row 2", etc.)
    sorted_keys = sorted(data.keys(), key=lambda k: int(re.search(r'\d+', k).group()) if re.search(r'\d+', k) else float('inf'))

    # Process each row in the JSON data in order
    for row_key in sorted_keys:
        columns = data[row_key]

        # Create a dictionary for the current row
        row_dict = {}

        # Extract column name and value for each item in the row
        for item in columns:
            column_name = item["columnName"]
            value = item["value"]

            # Try to convert numeric values
            try:
                value = float(value)
            except (ValueError, TypeError):
                pass

            row_dict[column_name] = value

        # Add the row dictionary to our list
        rows.append(row_dict)

    # Create DataFrame from the list of dictionaries
    df = pd.DataFrame(rows)

    return df

async def handle_detagged_views(
    detagged_view_ids,
    tag_name,
    vector_store,
    sample_data_vector_store,
    incremental=False
):
    """
    Processes a list of detagged view IDs for a specific tag.

    - If a view is not conflicting, it gets deleted.
    - If a view is conflicting, all of its associated documents have their
      metadata updated to remove the current tag and are then re-indexed.
    """
    view_ids_to_delete = []
    conflicting_docs_to_update = []
    last_update_dict = vector_store.get_last_update_dict() or {}

    for view_id in detagged_view_ids:
        # Fetch all documents/chunks associated with this view_id
        docs = await asyncio.to_thread(
            vector_store.search_by_vector,
            vector=vector_store.search_vector,
            k=100,
            view_ids=[view_id]
        )
        if not docs:
            continue

        if not incremental:
            conflicting_docs_to_update.extend(docs)
            continue

        first_doc = docs[0]

        is_safe_to_delete = is_non_conflicting_doc(
            doc=first_doc,
            databases_to_delete=[],
            tags_to_delete=[tag_name],
            last_update_dict=last_update_dict
        )

        if is_safe_to_delete:
            view_ids_to_delete.append(view_id)
        else:
            conflicting_docs_to_update.extend(docs)

    if view_ids_to_delete:
        await asyncio.to_thread(vector_store.delete_by_view_id, view_ids=view_ids_to_delete)
        if sample_data_vector_store:
            await asyncio.to_thread(sample_data_vector_store.delete_by_view_id, view_ids=view_ids_to_delete)

    if conflicting_docs_to_update:
        documents_to_reindex = []
        for doc in conflicting_docs_to_update:
            updated_metadata = doc.metadata.copy()
            tag_key = f"tag_{tag_name}"
            if tag_key in updated_metadata:
                del updated_metadata[tag_key]

            updated_document = Document(
                id=doc.id,
                page_content=doc.page_content,
                metadata=updated_metadata
            )
            documents_to_reindex.append(updated_document)

        if documents_to_reindex:
            ids_for_upsert = [doc.id for doc in documents_to_reindex]
            await asyncio.to_thread(
                vector_store.client.add_documents,
                documents=documents_to_reindex,
                ids=ids_for_upsert
            )

def get_user_synced_resources(vector_store, allowed_view_ids_str):
    """
    Gets the synced resources (last_update and partial_resources),
    filtered based on user's allowed_view_ids.
    """
    full_last_update, full_partial_resources = vector_store.get_sync_metadata()

    if full_last_update is None: full_last_update = {}
    if full_partial_resources is None: full_partial_resources = {}

    if not full_last_update and not full_partial_resources:
        logging.info("getVectorDBInfo: No sync info found in vector store.")
        return {}, {}

    filtered_last_update = {}
    filtered_partial_resources = {
        "partial_tags_by_db": {},
        "partial_dbs_by_tag": {},
        "partial_tags_by_tag": {}
    }

    # Filter Databases
    if "DATABASE" in full_last_update:
        filtered_last_update["DATABASE"] = {}
        for db_name, timestamp in full_last_update["DATABASE"].items():
            # Check if at least 1 view exists in this DB AND in the user's permissions
            if vector_store.check_existence(allowed_view_ids_str, database_names=[db_name]):
                filtered_last_update["DATABASE"][db_name] = timestamp

    # Filter Tags
    if "TAG" in full_last_update:
        filtered_last_update["TAG"] = {}
        for tag_name, timestamp in full_last_update["TAG"].items():
            # Check if at least 1 view exists with this Tag AND in the user's permissions
            if vector_store.check_existence(allowed_view_ids_str, tag_names=[tag_name]):
                filtered_last_update["TAG"][tag_name] = timestamp

    # Filter partial_tags_by_db
    p_tags_by_db = full_partial_resources.get("partial_tags_by_db", {})
    for db_name, tags_list in p_tags_by_db.items():
        valid_tags = []
        if tags_list:
            for tag in tags_list:
                # Has the user access to (DB + TAG)?
                if vector_store.check_existence(allowed_view_ids_str, database_names=[db_name], tag_names=[tag]):
                    valid_tags.append(tag)

        if valid_tags:
            filtered_partial_resources["partial_tags_by_db"][db_name] = valid_tags

    # Filter partial_dbs_by_tag
    p_dbs_by_tag = full_partial_resources.get("partial_dbs_by_tag", {})
    for tag_name, db_list in p_dbs_by_tag.items():
        valid_dbs = []
        if db_list:
            for db_name in db_list:
                # Has the user access to (TAG + DB)?
                if vector_store.check_existence(allowed_view_ids_str, database_names=[db_name], tag_names=[tag_name]):
                    valid_dbs.append(db_name)

        if valid_dbs:
            filtered_partial_resources["partial_dbs_by_tag"][tag_name] = valid_dbs

    # Filter partial_tags_by_tag
    p_tags_by_tag = full_partial_resources.get("partial_tags_by_tag", {})
    for tag_name, tags_list in p_tags_by_tag.items():
        valid_tags = []
        if tags_list:
            for other_tag in tags_list:
                # Has the user access to views that have BOTH the source TAG and the found TAG?
                if vector_store.check_existence(allowed_view_ids_str, tag_names=[tag_name, other_tag]):
                    valid_tags.append(other_tag)

        if valid_tags:
            filtered_partial_resources["partial_tags_by_tag"][tag_name] = valid_tags

    return filtered_last_update, filtered_partial_resources

def has_role(permissions_data, target_role):
    if not permissions_data:
        return False

    is_admin = permissions_data.get("isAdmin", False)
    user_roles = permissions_data.get("roles", [])

    return is_admin or target_role in user_roles

def check_llm_permission(permissions_data):
    if not permissions_data:
        return False

    if permissions_data.get("legacyEndpoint", False):
        return True

    return has_role(permissions_data, "use_large_language_model")

def filter_restricted_view_data(view_json, security_info):
    if not security_info:
        return view_json

    filtered_json = view_json.copy()

    if security_info.get("hasRowRestrictions", False):
        if 'schema' in filtered_json:
            for col in filtered_json['schema']:
                col.pop('sample_data', None)

    restricted_columns = security_info.get("restrictedColumns", [])
    if restricted_columns:
        restricted_set = set([col.lower() for col in restricted_columns])
        if 'schema' in filtered_json:
            filtered_json['schema'] = [
                col for col in filtered_json['schema']
                if col.get('columnName', '').lower() not in restricted_set
            ]

    return filtered_json

def parse_view_document(doc, filter_associations=False, valid_view_ids=None, security_info=None):
    view_json = json.loads(doc.metadata['view_json'])
    view_text = doc.page_content
    warnings = []

    if filter_associations:
        view_json = filter_non_allowed_associations(view_json, valid_view_ids or [])

    if security_info:
        view_json = filter_restricted_view_data(view_json, security_info)

        has_row_restrictions = security_info.get("hasRowRestrictions", False)
        has_col_restrictions = bool(security_info.get("restrictedColumns"))

        if has_row_restrictions:
            warnings.append("Sample data removed from schema due to user row restrictions.")

        if has_col_restrictions:
            view_text = None
            warnings.append("Original 'view_text' hidden and schema filtered due to user column restrictions.")

    return {
        "view_text": view_text,
        "view_name": doc.metadata['view_name'],
        "view_json": view_json,
        "view_id": doc.metadata.get('view_id', ''),
        "warnings": warnings
    }

"""
Contains LangChain tool definitions that the chatbot agent can use
to query data, metadata, and knowledge bases.
"""

import logging
import traceback

from utils import denodo_tools
from langchain.tools import ToolRuntime, tool
from sample_chatbot.engine import skills
from sample_chatbot.engine.context import UserContext
from utils.denodo_tools import create_basic_auth_header, format_data_agent_output, format_metadata_search_output

# =============================================================================
# Knowledge Query Implementation
# =============================================================================

def _knowledge_query_impl(search_query, vector_store, collection, k=5, document_size_limit_chars=10000):
    """
    Search a single collection inside the knowledge base.

    Returns a dict carrying the rendered answer plus collection metadata so the
    UI can show provenance.
    """
    try:
        result = vector_store.search(
            query=search_query,
            k=k,
            scores=False,
            database_names=[collection],
        )

        blocks = [
            f"<result_{i + 1}>\n{doc.page_content[:document_size_limit_chars]}\n</result_{i + 1}>"
            for i, doc in enumerate(result)
        ]
        return {"answer": "\n\n".join(blocks)}
    except Exception as e:
        return {
            "error": f"Knowledge query failed: {e}",
            "traceback": traceback.format_exc(),
        }

# =============================================================================
# LangChain Tool Definitions
# Response format must always be content_and_artifact
# =============================================================================

@tool(response_format="content_and_artifact")
def data_agent(
    runtime: ToolRuntime[UserContext],
    request: str,
    limit: int = 0,
    plot: int = 0,
    plot_details: str = "",
):
    """Communicates with the data agent to generate and execute a single VQL query.
    The data agent does not have memory of previous requests or conversations. Every individual request to the data_agent must be self-contained, meaning it must not rely on the agent having recollection of previous requests.

    Args:
        request: Request to generate a single VQL query from and return the VQL query, its explanation and the execution result. For example, 'count the number of unique customers in the organization.customers view'.
        limit: Maximum number of rows to return. If omitted, it defaults to the data_agent's limit configured for this session.
        plot: Whether to generate and also return a plot of the data. 1 for yes, 0 for no.
        plot_details: Any extra details of the graph to generate. For example, 'bar chart of the number of customers by country in organization.customers view'.
    """

    # UI-level filters coming from the QuestionForm (set in ai_sdk_params)
    if runtime.context.vdp_database_names:
        logging.info(f"Received UI filters: vdp_database_names={runtime.context.vdp_database_names}")
    if runtime.context.vdp_tag_names:
        logging.info(f"Received UI filters: vdp_tag_names={runtime.context.vdp_tag_names}")

    auth = create_basic_auth_header(runtime.context.username, runtime.context.password)
    default_limit = (runtime.context.ai_sdk_params or {}).get("vql_execute_rows_limit")
    effective_limit = default_limit if limit in (None, 0) else limit

    response = denodo_tools.data_agent(
        natural_language_query=request,
        api_host=runtime.context.api_host,
        auth=auth,
        vdp_database_names=runtime.context.vdp_database_names,
        vdp_tag_names=runtime.context.vdp_tag_names,
        plot=plot,
        plot_details=plot_details,
        limit=effective_limit,
        custom_instructions=runtime.context.ai_sdk_custom_instructions,
        verify_ssl=runtime.context.verify_ssl,
        timeout=runtime.context.timeout,
        **(runtime.context.ai_sdk_params or {}),
    )

    return format_data_agent_output(response)

@tool(response_format="content_and_artifact")
def deep_query(
    runtime: ToolRuntime[UserContext],
    analysis_request: str,
):
    """Request an advanced analysis request over the user's data to the DeepQuery agent.

    Args:
        analysis_request: Detailed analysis request to perform.
    """

    auth = create_basic_auth_header(runtime.context.username, runtime.context.password)

    response = denodo_tools.deep_query(
        analysis_request=analysis_request,
        api_host=runtime.context.api_host,
        auth=auth,
        verify_ssl=runtime.context.verify_ssl,
        timeout=runtime.context.timeout,
        **(runtime.context.ai_sdk_params or {}),
    )

    if "answer" in response:
        content = response["answer"]
    else:
        error_detail = response.get("detail") or response.get("error")
        content = str(error_detail) if error_detail else "DeepQuery analysis failed, please check the additional information modal."

    return (content, response)

@tool(response_format="content_and_artifact")
def metadata_search(
    runtime: ToolRuntime[UserContext],
    search_query: str,
    n_results: int = 5,
):
    """This tool can perform a similarity search in the database and return the schema of the n_results (stick to the default of 5 if not specified) most similar views.
        For example, it can be helpful to answer questions like:
        - What views do we have related to X topic.
        - What is the primary key of this table.
        - What associations does this view have.

    Args:
        search_query: Natural language query to search for the metadata of the views in the user's Denodo instance. For example, 'views related to loans'.
        n_results: Maximum number of results to return.
    """

    auth = create_basic_auth_header(runtime.context.username, runtime.context.password)

    response = denodo_tools.metadata_search(
        search_query=search_query,
        api_host=runtime.context.api_host,
        auth=auth,
        vdp_database_names=runtime.context.vdp_database_names,
        vdp_tag_names=runtime.context.vdp_tag_names,
        n_results=n_results,
        verify_ssl=runtime.context.verify_ssl,
        timeout=runtime.context.timeout,
    )

    return format_metadata_search_output(response)

@tool(response_format="content_and_artifact")
def knowledge_query(runtime: ToolRuntime[UserContext], search_query: str, collection: str, k: int = 5):
    """Search a single collection in the user's knowledge base with similarity search.

    Args:
        search_query: Natural language query to search for in the collection.
        collection: REQUIRED. The exact name of the collection to search, taken from the
            list shown in extra_tools_guidance. To cover several collections, call this
            tool once per collection.
        k: Maximum number of results to return (default 5).
    """
    if not runtime.context.vector_store:
        return (
            "Knowledge base is not configured.",
            {"error": "knowledge_base_not_configured"},
        )

    active = runtime.context.active_csv_sources or []
    requested = (collection or "").strip()

    if not requested:
        return (
            "The `collection` argument is required. Pick one of the active collections: "
            f"{', '.join(active) if active else '(none active)'}.",
            {"error": "collection_required", "active_collections": active},
        )

    if not active:
        # No subscribed collections means the user has nothing to search. We
        # MUST refuse — otherwise the LLM could be coaxed into naming someone
        # else's private collection and reading it through the shared store.
        return (
            "You have no collections active for this chatbot. Open the Knowledge "
            "Base Manager to activate one before asking a knowledge-base question.",
            {"error": "no_collections_active", "active_collections": []},
        )

    if requested not in active:
        return (
            f"Collection '{requested}' is not in your active set. "
            f"Active collections: {', '.join(active)}.",
            {"error": "collection_not_active", "active_collections": active},
        )

    collection_description = (runtime.context.kb_collections or {}).get(requested, "")

    response = _knowledge_query_impl(
        search_query=search_query,
        vector_store=runtime.context.vector_store,
        collection=requested,
        k=k,
    )
    response["collection_name"] = requested
    response["collection_description"] = collection_description

    if 'error' in response:
        return (f"Knowledge query failed: {response.get('error', 'Unknown error')}", response)

    content = response.get("answer", "Knowledge query failed, please check the additional information modal.")
    return (content, response)

# =============================================================================
# Skill Tools
# Skills are reusable guidance the agent reads on demand. System skills live
# on disk and are shared by everyone; personal skills live in the database and
# belong to a single user. Reading and personal skill management are open to
# all users; managing SYSTEM skills requires can_manage_skills.
# =============================================================================

_SKILL_MANAGEMENT_DENIED = (
    "You are not authorized to edit system skills. Only administrators "
    "(or explicitly allowed users/roles) can manage system skills."
)

@tool(response_format="content_and_artifact")
def read_skill(runtime: ToolRuntime[UserContext], skill_name: str):
    """Read the full instructions (SKILL.md) of a skill, so you can follow its guidance.

    Read the relevant skill BEFORE acting on a task it covers. The system prompt lists
    the available skill names and descriptions.

    Args:
        skill_name: The name of the skill to read. For example, 'deepquery'.
    """
    try:
        content = skills.read_skill_for_user(runtime.context.username, skill_name)
        return (content, {"skill": skill_name})
    except skills.SkillError as e:
        return (str(e), {"error": str(e), "skill": skill_name})

@tool(response_format="content_and_artifact")
def read_skill_reference(runtime: ToolRuntime[UserContext], skill_name: str, reference_name: str):
    """Read one of a skill's reference documents for deeper detail on a sub-topic.

    The available reference names for each skill are listed next to the skill in the
    system prompt.

    Args:
        skill_name: The name of the skill. For example, 'deepquery'.
        reference_name: The name of the reference document (without extension). For example, 'interpret_results'.
    """
    try:
        content = skills.read_skill_reference(skill_name, reference_name)
        return (content, {"skill": skill_name, "reference": reference_name})
    except skills.SkillError as e:
        return (str(e), {"error": str(e), "skill": skill_name, "reference": reference_name})

@tool(response_format="content_and_artifact")
def edit_skill(runtime: ToolRuntime[UserContext], skill_name: str, text_to_search: str, text_to_replace: str):
    """Edit a skill by replacing text. Personal skills are always editable by their
    owner; editing shared SYSTEM skills requires skill-management permission.

    IMPORTANT: This replaces ALL occurrences of text_to_search with text_to_replace.
    Make text_to_search specific enough to match exactly what you intend to change
    (including whitespace).

    Args:
        skill_name: The name of the skill to edit. For example, 'deepquery'.
        text_to_search: The exact text to find. All occurrences are replaced.
        text_to_replace: The text to replace it with.
    """
    username = runtime.context.username
    try:
        try:
            count = skills.edit_personal_skill(username, skill_name, text_to_search, text_to_replace)
            scope = "personal"
        except skills.SkillError as personal_error:
            if "was not found" not in str(personal_error):
                raise
            # Not one of the user's personal skills: fall back to system skills.
            if not runtime.context.can_manage_skills:
                return (_SKILL_MANAGEMENT_DENIED, {"error": "unauthorized", "skill": skill_name})
            count = skills.edit_skill(skill_name, text_to_search, text_to_replace)
            scope = "system"
        return (
            f"Replaced {count} occurrence(s) in {scope} skill '{skill_name}'.",
            {"skill": skill_name, "scope": scope, "replacements": count},
        )
    except skills.SkillError as e:
        return (str(e), {"error": str(e), "skill": skill_name})

@tool(response_format="content_and_artifact")
def edit_skill_reference(runtime: ToolRuntime[UserContext], skill_name: str, reference_name: str, text_to_search: str, text_to_replace: str):
    """Edit a skill reference document by replacing text. Requires skill-management permission.

    IMPORTANT: This replaces ALL occurrences of text_to_search with text_to_replace.
    Make text_to_search specific enough to match exactly what you intend to change
    (including whitespace).

    Args:
        skill_name: The name of the skill. For example, 'deepquery'.
        reference_name: The name of the reference document (without extension). For example, 'interpret_results'.
        text_to_search: The exact text to find. All occurrences are replaced.
        text_to_replace: The text to replace it with.
    """
    if not runtime.context.can_manage_skills:
        return (_SKILL_MANAGEMENT_DENIED, {"error": "unauthorized", "skill": skill_name})
    try:
        count = skills.edit_skill_reference(skill_name, reference_name, text_to_search, text_to_replace)
        return (
            f"Replaced {count} occurrence(s) in reference '{reference_name}' of skill '{skill_name}'.",
            {"skill": skill_name, "reference": reference_name, "replacements": count},
        )
    except skills.SkillError as e:
        return (str(e), {"error": str(e), "skill": skill_name, "reference": reference_name})

@tool(response_format="content_and_artifact")
def create_skill(runtime: ToolRuntime[UserContext], skill_name: str, content: str):
    """Create a brand new PERSONAL skill for this user, only visible to them.

    The content should be the full markdown body of the skill, ideally starting with a
    YAML frontmatter block containing a 'name' and a one-line 'description'.

    Args:
        skill_name: The name of the new skill (letters, digits, hyphens, underscores only). For example, 'deepquery_usage_2'.
        content: The full SKILL.md content for the new skill.
    """
    try:
        skills.create_personal_skill(runtime.context.username, skill_name, content)
        return (
            f"Created personal skill '{skill_name}'.",
            {"skill": skill_name, "scope": "personal", "created": True},
        )
    except skills.SkillError as e:
        return (str(e), {"error": str(e), "skill": skill_name})

@tool(response_format="content_and_artifact")
def create_skill_reference(runtime: ToolRuntime[UserContext], skill_name: str, reference_name: str, content: str):
    """Create a new reference document inside an existing skill. Requires skill-management permission.

    Args:
        skill_name: The name of the existing skill the reference belongs to. For example, 'deepquery'.
        reference_name: The name of the new reference document (without extension). For example, 'interpret_results'.
        content: The full markdown content for the new reference document.
    """
    if not runtime.context.can_manage_skills:
        return (_SKILL_MANAGEMENT_DENIED, {"error": "unauthorized", "skill": skill_name})
    try:
        skills.create_skill_reference(skill_name, reference_name, content)
        return (
            f"Created reference '{reference_name}' in skill '{skill_name}'.",
            {"skill": skill_name, "reference": reference_name, "created": True},
        )
    except skills.SkillError as e:
        return (str(e), {"error": str(e), "skill": skill_name, "reference": reference_name})

html, body, #root {
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.app-layout-container {
  display: flex;
  flex-direction: row;
  height: 100vh;
  width: 100vw;
  background-color: #ffffff;
  overflow: hidden;
}

.main-content-area {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  height: 100%;
  position: relative;
  min-width: 0;
  background-color: #ffffff;
  overflow: hidden;
}

.chat-scroll-area {
  flex-grow: 1;
  overflow-y: auto;
  overflow-x: hidden;
  display: flex;          
  flex-direction: column;
  scroll-behavior: smooth;
  scrollbar-width: thin;
  padding: 20px;
  transition: flex-grow 0.6s cubic-bezier(0.25, 1, 0.5, 1);
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: transparent; 
}
::-webkit-scrollbar-thumb {
  background: #c1c1c1; 
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #a8a8a8; 
}

.dm-bg-container {
  background-color: #ffffff; 
  position: relative;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  overflow: hidden;
}

.dm-bg-container::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; height: 250px;
  pointer-events: none;
  z-index: 0;
  background-image: radial-gradient(ellipse 110% 150px at 50% 0%, #f4f6f8 99.5%, transparent 100%);
  background-repeat: no-repeat;
}

.dm-bg-container::after {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  pointer-events: none;
  z-index: 0;
  opacity: 0.6;
  background-image: url("data:image/svg+xml,%3Csvg width='38' height='38' xmlns='http://www.w3.org/2000/svg'%3E%3Crect width='4' height='4' fill='%23d4dadd'/%3E%3C/svg%3E");
  -webkit-mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 0%, rgba(0,0,0,1) 80px, rgba(0,0,0,0) 350px);
  mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 0%, rgba(0,0,0,1) 80px, rgba(0,0,0,0) 350px);
}

.dm-content {
  position: relative;
  z-index: 10;
  display: flex;
  flex-direction: column;
  height: 100%;
  flex-grow: 1;
  overflow: hidden;
  box-shadow: inset 0px 0px 15px rgba(0, 0, 0, 0.03);
}

@keyframes fadeInSmooth {
  from {
    opacity: 0;
    transform: translateY(15px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in-smooth {
  animation: fadeInSmooth 0.4s ease-out forwards;
}

.animate-fade-in-up {
  animation: fadeInUp 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both; 
}

.delay-1 {
  animation-delay: 0.1s;
}
.delay-2 {
  animation-delay: 0.4s;
}
.delay-3 {
  animation-delay: 0.7s;
}
.delay-4 {
  animation-delay: 1.0s; 
}

@keyframes fadeInUp {
  0% {
    opacity: 0;
    transform: translateY(20px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.text-shine {
  background: linear-gradient(
    to right,
    #112533 20%,
    #ed342a 40%,
    #ed342a 60%,
    #112533 80%
  );
  background-size: 200% auto;
  color: transparent;
  -webkit-background-clip: text;
  background-clip: text;
  animation: shine 4s linear infinite;
  text-shadow: 0px 4px 20px rgba(237, 52, 42, 0.15);
}

@keyframes shine {
  to {
    background-position: 200% center;
  }
}

import React, { useState, useReducer, useEffect } from "react";
import "./App.css";
import "./Modal.css";

import Header from "./components/Header/Header";
import Chat from "./components/Chat/Chat";
import QuestionForm from "./components/QuestionForm/QuestionForm";
import ReportManagementModal from "./components/Header/ReportManagementModal";
import Sidebar from "./components/Sidebar/Sidebar";
import LoginPage from "./components/LoginPage/LoginPage";
import { Spinner } from "react-bootstrap";

import { chatReducer, actionTypes } from "./reducers/chatReducer";
import { useConfig } from "./contexts/ConfigContext";
import api from "./api/client";
import useSDK from "./hooks/useSDK";

// Abstracted Hooks & Feature-based Components
import { useAgentManager } from "./hooks/useAgentManager";
import { useChatHistory } from "./hooks/useChatHistory";
import { useChatLimits } from "./hooks/useChatLimits";
import DeleteChatModal from "./components/Sidebar/DeleteChatModal";
import RenameChatModal from "./components/Sidebar/RenameChatModal";
import LimitWarningModal from "./components/Chat/LimitWarningModal";
import WelcomeScreen from "./components/WelcomeScreen/WelcomeScreen";

const assetBaseUrl = import.meta.env.BASE_URL;

const App = () => {
  const [results, dispatch] = useReducer(chatReducer, []);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showCSVManager, setShowCSVManager] = useState(false);
  const [currentQuestion, setCurrentQuestion] = useState("");
  const [completedRequestId, setCompletedRequestId] = useState(null);
  const [customLogoState, setCustomLogoState] = useState("checking");
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [username, setUsername] = useState("");

  const { updateConfig } = useConfig();

  // Business logic Custom Hooks
  const agentManager = useAgentManager(updateConfig);
  const limits = useChatLimits(dispatch);
  const history = useChatHistory(
    dispatch,
    agentManager.chatbots,
    agentManager.switchAgentInBackend,
    agentManager.setSelectedChatbot,
    limits.setAutoOverwriteAccepted,
    limits.handleLimitReached 
  );

  // SDK Initialization
  const sdk = useSDK(
    dispatch,
    (id) => {
      setCompletedRequestId(id);
      history.handleRequestCompletion(id);
    },
    history.currentThreadId,
    history.setCurrentThreadId,
    limits.handleLimitReached,
    limits.autoOverwriteAccepted,
  );

  useEffect(() => {
    const img = new Image();
    img.onload = () => setCustomLogoState("present");
    img.onerror = () => setCustomLogoState("absent");
    img.src = `${assetBaseUrl}logo.png`;
  }, []);

  useEffect(() => {
    if (!isAuthenticated) return;
    const delayDebounceFn = setTimeout(() => {
      history.fetchChatHistoryList(false, history.searchQuery);
    }, 400);
    return () => clearTimeout(delayDebounceFn);
  }, [history.searchQuery, isAuthenticated]);

  useEffect(() => {
    if (!agentManager.selectedChatbot && results.length > 0) {
      agentManager.setSelectedChatbot(agentManager.activeChatbot);
    }
  }, [
    results.length,
    agentManager.selectedChatbot,
    agentManager.activeChatbot,
  ]);

  useEffect(() => {
    if (isAuthenticated) {
      const storedUser = localStorage.getItem("current_user");
      if (storedUser) setUsername(storedUser);
    }
  }, [isAuthenticated]);

  const renderLogo = () => {
    if (customLogoState === "present")
      return (
        <img
          alt="Company logo"
          src={`${assetBaseUrl}logo.png`}
          height="30"
          className="d-inline-block align-top"
        />
      );
    return (
      <img
        alt="Denodo company logo"
        src={`${assetBaseUrl}denodo_logo.png`}
        height="30"
        className="d-inline-block align-top"
      />
    );
  };

  const handleSignIn = async (userInformation) => {
    try {
      const response = await api.post("login", userInformation);
      if (response.data.success) {
        setIsAuthenticated(true);
        agentManager.setSyncedResources(response.data.syncedResources || {});
        agentManager.setPartialResources(response.data.partialResources || {});
        agentManager.setGlobalEnabled(response.data.globalEnabled || false);
        agentManager.setChatbots(response.data.agents || []);
        agentManager.setSelectedChatbot(null);
        agentManager.setUserSyncPermissions(
          response.data.userSyncPermissions !== false,
        );

        if (response.data.config) updateConfig(response.data.config);

        const dictString = localStorage.getItem(
          `${userInformation.username}_custom_instructions_dict`,
        );
        if (dictString) {
          try {
            const dict = JSON.parse(dictString);
            const validKeys = response.data.agents
              ? response.data.agents.map((a) => a.id)
              : [];
            if (response.data.globalEnabled) validKeys.push("global");

            const cleanDict = {};
            for (const key of Object.keys(dict)) {
              if (validKeys.includes(key)) cleanDict[key] = dict[key];
            }
            localStorage.setItem(
              `${userInformation.username}_custom_instructions_dict`,
              JSON.stringify(cleanDict),
            );
          } catch (e) {}
        }
      } else {
        alert(response.data.message || "Invalid credentials.");
      }
    } catch (error) {
      alert(
        error.response?.data?.message || "An error occurred during sign-in.",
      );
    }
  };

  const executeSwitchChatbot = async (bot) => {
    agentManager.setIsSwitchingAgent(true);
    try {
      limits.setAutoOverwriteAccepted(false);
      await agentManager.switchAgentInBackend(bot);
      agentManager.setSelectedChatbot(bot);
      history.setCurrentThreadId(null);
      dispatch({ type: actionTypes.CLEAR_CHAT });
    } catch (error) {
      alert("Error connecting to the selected chatbot.");
    } finally {
      agentManager.setIsSwitchingAgent(false);
    }
  };

  const handleSettingsApplied = async (bot) => {
    try {
      await agentManager.switchAgentInBackend(bot);
    } catch (error) {
      console.error("Error applying new settings to backend:", error);
    }
  };

  const handleNewChat = () => {
    limits.setAutoOverwriteAccepted(false);
    history.setCurrentThreadId(null);
    dispatch({ type: actionTypes.CLEAR_CHAT });
    const globalBot = agentManager.chatbots.find((bot) => bot.isGlobal);
    if (globalBot && agentManager.selectedChatbot?.id !== globalBot.id) {
      executeSwitchChatbot(globalBot);
    }
  };

  const handleResetWorkspace = () => {
    limits.setAutoOverwriteAccepted(false);
    history.setCurrentThreadId(null);
    dispatch({ type: actionTypes.CLEAR_CHAT });
    history.resetHistoryState();
  };

  const handleAcceptLimit = () => {
    const { pendingData, type } = limits.limitModal;
    limits.setLimitModal({
      show: false,
      type: null,
      pendingData: null,
      limit: 0,
      current: 0,
      targetsToDelete: [],
    });

    if (pendingData) {
      if (pendingData.type === "import") {
        history.handleImportChat(pendingData.file, true);
      } else if (typeof sdk.processQuestion === "function") {
        let newResultIndex = pendingData.resultIndex;

        if (type === "messages") {
          limits.setAutoOverwriteAccepted(true);
        } else if (type === "chats") {
          history.fetchChatHistoryList(false);
        }

        sdk.processQuestion(
          pendingData.query,
          pendingData.toolName,
          newResultIndex,
          { ...pendingData.options, force_overwrite: true },
        );
      }
    }
  };

  if (!isAuthenticated) {
    return (
      <LoginPage
        onSignIn={handleSignIn}
        renderLogo={renderLogo}
        showBrandAsk={customLogoState === "absent"}
        isCheckingLogo={customLogoState === "checking"} 
      />
    );
  }

  return (
    <div className="app-layout-container">
      <Sidebar
        isOpen={isSidebarOpen}
        toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        chatbots={agentManager.chatbots}
        selectedChatbot={agentManager.selectedChatbot}
        onSelectChatbot={(bot) => {
          if (agentManager.selectedChatbot?.id !== bot.id)
            executeSwitchChatbot(bot);
        }}
        showDenodoSidebarHeaderIcon={customLogoState === "absent"}
        onNewChat={handleNewChat}
        chatHistoryList={history.chatHistoryList}
        currentThreadId={history.currentThreadId}
        onLoadOldChat={history.handleLoadOldChat}
        onDeleteChat={(id) => history.setChatToDelete(id)}
        onRenameChat={(chat) => {
          history.setChatToRename(chat);
          history.setNewChatName(chat.title);
        }}
        onExportChat={history.handleExportChat}
        onImportChat={history.handleImportChat}
        onLoadMoreChats={() => history.fetchChatHistoryList(true)}
        hasMoreChats={history.hasMoreChats}
        isLoadingList={history.isLoadingList}
        isLoadingHistory={history.isLoadingHistory}
        onPinChat={history.handlePinChat}
        searchQuery={history.searchQuery}
        onSearchChange={history.setSearchQuery}
      />

      <div className="main-content-area">
        <Header
          isAuthenticated={isAuthenticated}
          setIsAuthenticated={setIsAuthenticated}
          handleClearResults={handleResetWorkspace}
          showClearButton={results.length > 0}
          onOpenCSVManager={() => setShowCSVManager(true)}
          showCSVManager={showCSVManager}
          setShowCSVManager={setShowCSVManager}
          renderLogo={renderLogo}
          showBrandAsk={customLogoState === "absent"}
          syncedResources={agentManager.syncedResources}
          partialResources={agentManager.partialResources}
          userSyncPermissions={agentManager.userSyncPermissions}
          onResourcesUpdate={(data) => {
            if (data.syncedResources)
              agentManager.setSyncedResources(data.syncedResources);
            if (data.partialResources)
              agentManager.setPartialResources(data.partialResources);
          }}
          hasActiveConversation={results.length > 0}
          toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
          isSidebarOpen={isSidebarOpen}
          selectedChatbot={agentManager.selectedChatbot}
          globalEnabled={agentManager.globalEnabled}
          onSettingsApplied={handleSettingsApplied}
          isSwitchingAgent={agentManager.isSwitchingAgent}
        />

        {agentManager.isSwitchingAgent || history.isLoadingHistory ? (
          <div className="dm-bg-container flex-grow-1 d-flex flex-column align-items-center justify-content-center">
            <Spinner
              animation="border"
              style={{
                color: "#143142",
                width: "3.5rem",
                height: "3.5rem",
                borderWidth: "0.25em",
              }}
            />
            <h5
              className="mt-4 text-secondary"
              style={{ fontWeight: 500, letterSpacing: "0.5px" }}
            >
              {history.isLoadingHistory
                ? "Loading conversation..."
                : "Setting up your chat..."}
            </h5>
          </div>
        ) : (
          <div className="dm-bg-container flex-grow-1">
            <div className="dm-content d-flex flex-column h-100">
              <div
                style={{
                  flexGrow: results.length === 0 ? 1 : 0,
                  transition: "flex-grow 0.6s cubic-bezier(0.25, 1, 0.5, 1)",
                  minHeight: 0,
                }}
              />

              <div
                className="chat-scroll-area d-flex flex-column"
                style={{
                  flexGrow: results.length > 0 ? 1 : 0,
                  overflowY: "auto",
                  flexShrink: 1,
                  minHeight: 0,
                }}
              >
                {results.length === 0 ? (
                  <div className="w-100 pb-2">
                    <WelcomeScreen
                      selectedChatbot={agentManager.selectedChatbot}
                      customLogoState={customLogoState}
                      username={username}
                      globalEnabled={agentManager.globalEnabled}
                    />
                  </div>
                ) : (
                  <Chat
                    results={results}
                    dispatch={dispatch}
                    setCurrentQuestion={setCurrentQuestion}
                  />
                )}
              </div>

              <div
                className={`pb-3 pt-2 position-relative ${!agentManager.selectedChatbot && results.length === 0 ? "animate-fade-in-up delay-4" : results.length === 0 ? "fade-in-smooth" : ""}`}
                style={{ zIndex: 10, flexShrink: 0 }}
              >
                <QuestionForm
                  results={results}
                  dispatch={dispatch}
                  isAuthenticated={isAuthenticated}
                  currentQuestion={currentQuestion}
                  setCurrentQuestion={setCurrentQuestion}
                  sdk={sdk}
                  completedRequestId={completedRequestId}
                  syncedResources={agentManager.syncedResources}
                  partialResources={agentManager.partialResources}
                  selectedChatbot={agentManager.activeChatbot}
                />
              </div>
              <div
                style={{
                  flexGrow: results.length === 0 ? 1 : 0,
                  transition: "flex-grow 0.6s cubic-bezier(0.25, 1, 0.5, 1)",
                  minHeight: 0,
                }}
              />
            </div>
          </div>
        )}
      </div>

      <ReportManagementModal />
      <DeleteChatModal
        show={!!history.chatToDelete}
        onHide={() => history.setChatToDelete(null)}
        onConfirm={() => history.confirmDeleteChat(handleNewChat)}
      />
      <RenameChatModal
        show={!!history.chatToRename}
        onHide={() => history.setChatToRename(null)}
        newChatName={history.newChatName}
        setNewChatName={history.setNewChatName}
        onConfirm={history.handleRenameSubmit}
      />
      <LimitWarningModal
        modalState={limits.limitModal}
        onClose={limits.closeLimitModal}
        onAccept={handleAcceptLimit}
      />
    </div>
  );
};

export default App;

