import React, { useEffect, useRef, useState } from "react";
import "./Chat.css";
import { useReport } from "../../contexts/ReportContext";
import ChatItem from "./ChatItem";
import NotificationToast from "../NotificationToast/NotificationToast";
import { actionTypes } from "../../reducers/chatReducer";

const Chat = ({
  results,
  dispatch,
  setCurrentQuestion,
  setQuestionType,
}) => {
  const resultsEndRef = useRef(null);
  const resultsContainerRef = useRef(null);
  const { generateReport } = useReport();
  const [reportGenerationStatus, setReportGenerationStatus] = useState({});

  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: "",
    variant: "light",
    title: "",
  });

  const scrollToBottom = () => {
    resultsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (results.length > 0) {
      scrollToBottom();
    }
  }, [results]);

  useEffect(() => {
    if (results.some(r => r.isExiting)) {
      const timer = setTimeout(() => {
        dispatch({ type: actionTypes.PURGE_EXITING_ITEMS });
      }, 400);
      return () => clearTimeout(timer);
    }
  }, [results, dispatch]);

  const handleToastClose = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  const handleReportGeneration = async (result, colorPalette = "red") => {
    // Support for deep_query_metadata from toolCalls or top-level
    let metadata = result.deepquery_metadata;
    if (!metadata && result.toolCalls) {
        const dqCall = result.toolCalls.find(t => t.toolName === 'deep_query' && t.artifact && t.artifact.deepquery_metadata);
        if (dqCall) metadata = dqCall.artifact.deepquery_metadata;
    }

    if (!metadata) {
      console.error("No deepquery_metadata available for report generation");
      return;
    }

    if (reportGenerationStatus[result.uuid]) {
      console.log(
        "Report generation is already in progress for this result. Ignoring repeated request."
      );
      return;
    }

    setReportGenerationStatus((prevStatus) => ({
      ...prevStatus,
      [result.uuid]: true,
    }));

    setToastConfig({
      show: true,
      message: "Generating report... please wait.",
      variant: "info",
      title: "Processing",
    });

    try {
      await generateReport(metadata, result.question, colorPalette);

      setToastConfig({
        show: true,
        message: "Report generation finished successfully.",
        variant: "success",
        title: "Completed",
      });
    } catch (error) {
      console.error("Error generating report:", error);

      setToastConfig({
        show: true,
        message: "Error generating report.",
        variant: "danger",
        title: "Error",
      });
    } finally {
      setTimeout(() => {
        setReportGenerationStatus((prevStatus) => {
          const newStatus = { ...prevStatus };
          delete newStatus[result.uuid];
          return newStatus;
        });
      }, 3000);
    }
  };

  if (results.length === 0) {
    return null;
  }

  return (
    <div
      className="d-flex flex-column align-items-center w-100 text-light"
      ref={resultsContainerRef}
    >
      {results.map((result, index) => (
        <div
          key={result.uuid || `temp-${index}`}
          className={`w-100 ${result.isExiting ? 'chat-item-exit' : ''}`}
        >
          <ChatItem
            result={result}
            index={index}
            dispatch={dispatch}
            setCurrentQuestion={setCurrentQuestion}
            setQuestionType={setQuestionType}
            onGenerateReport={handleReportGeneration}
            isGeneratingReport={!!reportGenerationStatus[result.uuid]}
            resultsContainerRef={resultsContainerRef}
          />
        </div>
      ))}
      <div ref={resultsEndRef} />

      <NotificationToast
        show={toastConfig.show}
        message={toastConfig.message}
        variant={toastConfig.variant}
        title={toastConfig.title}
        onClose={handleToastClose}
      />
    </div>
  );
};

export default Chat;

import React, { useState } from "react";
import PropTypes from "prop-types";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import Card from "react-bootstrap/Card";
import Spinner from "react-bootstrap/Spinner";
import TableModal from "./TableModal";
import { useConfig } from "../../contexts/ConfigContext";
import AdditionalInformationModal from "./AdditionalInformationModal";
import GraphModal from "./GraphModal";
import ContextTablesModal from "./ContextTablesModal";
import FeedbackModal from "./FeedbackModal";
import RelatedQuestions from "./RelatedQuestions";
import ContextTablesAction from "./ContextTablesAction";
import ChatItemActions from "./ChatItemActions";
import ToolBlocks from "./ToolBlocks";
import NotificationToast from "../NotificationToast/NotificationToast";

const ChatItem = ({
  result,
  index,
  dispatch,
  setCurrentQuestion,
  setQuestionType,
  onGenerateReport,
  isGeneratingReport,
  resultsContainerRef,
}) => {
  const { config } = useConfig();

  const [showInfoModal, setShowInfoModal] = useState(false);
  const [showGraphModal, setShowGraphModal] = useState(false);
  const [graph, setGraph] = useState(null);
  const [showTableModal, setShowTableModal] = useState(false);
  const [tableData, setTableData] = useState(null);
  const [showContextModal, setShowContextModal] = useState(false);
  const [contextTables, setContextTables] = useState({
    tables: [],
    vql: "",
  });

  const [showFeedbackModal, setShowFeedbackModal] = useState(false);

  const [modalOverride, setModalOverride] = useState(null);

  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: "",
    variant: "info",
    title: "",
  });

  const handleAskRelated = (question) => {
    setCurrentQuestion(question);
    setQuestionType(result?.toolName || null);
  };

  const handleAskDeepQuery = (question) => {
    setCurrentQuestion(question);
    setQuestionType("deep_query");
  };

  const handleOpenInfo = () => {
      setModalOverride(null);
      setShowInfoModal(true);
  };

  const handleCloseInfo = () => {
      setShowInfoModal(false);
      setModalOverride(null);
  };

  const handleToolIconClick = (toolResult) => {
      setModalOverride({
          ...result,
          ...toolResult, 
          toolName: toolResult.modalTool || null
      });
      setShowInfoModal(true);
  };

  const handleOpenGraph = (graphData) => {
    const g = graphData || result.graph;
    if (!g) return;
    setGraph(g);
    setShowGraphModal(true);
  };

  const handleCloseGraph = () => {
    setShowGraphModal(false);
    setGraph(null);
  };

  const handleOpenTable = (data) => {
    const d = data || result.execution_result?.full;
    if (!d) return;
    setTableData(d);
    setShowTableModal(true);
  };

  const handleCloseTable = () => {
    setShowTableModal(false);
  };

  const handleResetTableData = () => {
    setTableData(null);
  };

  const handleOpenContext = (tables, vql) => {
    if (!tables || tables.length === 0) return;
    setContextTables({ tables, vql });
    setShowContextModal(true);
  };

  const handleCloseContext = () => {
    setShowContextModal(false);
    setContextTables({ tables: [], vql: "" });
  };

  const handleOpenFeedback = () => {
    if (!config.chatbot_feedback || result.disableFeedback) return;
    setShowFeedbackModal(true);
  };

  const handleCloseFeedback = () => {
    setShowFeedbackModal(false);
  };

  const renderContent = () => {
    // Fallback for empty or loading initial state
    if (!result.blocks || result.blocks.length === 0) {
        if (result.isLoading) {
             return (
                <Card.Text className="query-loading-text">
                  <div className="d-flex align-items-start">
                    <Spinner
                      size="sm"
                      animation="border"
                      className="me-2 mt-1"
                    />
                    <span>Processing...</span>
                  </div>
                </Card.Text>
              );
        }
        // If finished but empty (rare, but possible on error)
        if (result.result) {
             return (
                <Card.Text>
                    <div className="markdown-container">
                        <ReactMarkdown
                            remarkPlugins={[remarkGfm]}
                            components={{
                                a: ({node, ...props}) => (
                                    <a {...props} target="_blank" rel="noopener noreferrer" />
                                )
                            }}
                        >
                            {result.result}
                        </ReactMarkdown>
                    </div>
                </Card.Text>
             );
        }
        return <div style={{ minHeight: "20px" }} />;
    }

    return (
        <>
            {result.feedback && (
              <div className="mb-2">
                <span className={`badge bg-${result.feedback === "positive" ? "success" : "danger"} ms-2`}>
                  {result.feedback === "positive" ? "Positive feedback" : "Negative feedback"}
                </span>
              </div>
            )}

            <ToolBlocks
              blocks={result.blocks}
              result={result}
              isGeneratingReport={isGeneratingReport}
              onGenerateReport={onGenerateReport}
              resultsContainerRef={resultsContainerRef}
              onOpenGraph={handleOpenGraph}
              onOpenTable={handleOpenTable}
              onToolIconClick={handleToolIconClick}
            />

            {result.isError && result.errorMessage && (
              <div
                className="mt-2"
                style={{
                  borderRadius: "0.25rem",
                  padding: "0.5rem 0.75rem",
                  backgroundColor: "rgba(220,53,69,0.08)",
                  color: "#842029",
                  fontSize: "0.9rem",
                }}
              >
                {result.errorMessage}
              </div>
            )}

            <RelatedQuestions
                relatedQuestions={result.relatedQuestions}
                relatedQuestionsDeepQuery={result.relatedQuestionsDeepQuery}
                onAskRelated={handleAskRelated}
                onAskDeepQuery={handleAskDeepQuery}
            />

            {result.combinedTablesUsed && result.combinedTablesUsed.length > 0 && (
                <ContextTablesAction
                    tables={result.combinedTablesUsed}
                    vql={result.combinedVqls}
                    dataCatalogUrl={config.data_marketplace_url}
                    icons={
                        <ChatItemActions
                            result={result}
                            config={{ ...config, chatbot_feedback: config.chatbot_feedback && !result.disableFeedback }}
                            onOpenInfo={handleOpenInfo}
                            onFeedback={handleOpenFeedback}
                            resultsContainerRef={resultsContainerRef}
                        />
                    }
                    onOpenContext={handleOpenContext}
                />
            )}

            {(!result.combinedTablesUsed || result.combinedTablesUsed.length === 0) && (
               <div
                  style={{
                    backgroundColor: "transparent",
                    padding: "1rem 0",
                    marginBottom: "0",
                  }}
                >
              <div className="mb-2 d-flex justify-content-end align-items-center">
                    <div
                      className="d-flex flex-row align-items-center"
                      style={{ gap: "8px" }}
                    >
                      <ChatItemActions
                        result={result}
                        config={{ ...config, chatbot_feedback: config.chatbot_feedback && !result.disableFeedback }}
                        onOpenInfo={handleOpenInfo}
                        onFeedback={handleOpenFeedback}
                        resultsContainerRef={resultsContainerRef}
                      />
                    </div>
                  </div>
                </div>
            )}
        </>
    );
  };

  return (
    <>
      <div className="w-100 d-flex justify-content-center mb-3">
        <div className="w-70 d-flex justify-content-end">
          <Card
            style={{
              backgroundColor: "#ffffff",
              borderRadius: "1.25em",
              color: "#112533",
              boxShadow: "0 4px 12px rgba(0, 0, 0, 0.1)",
              maxWidth: "80%",
              width: "fit-content",
            }}
          >
            <Card.Body>
              <Card.Text>{result.question}</Card.Text>
            </Card.Body>
          </Card>
        </div>
      </div>

      <div className="w-100 d-flex justify-content-center mb-3">
        <div className="w-60 d-flex justify-content-start">
          <Card
            className={`w-100 ${
              result.isLoading ? "card-loading-pulse" : ""
            }`}
            style={{
              backgroundColor: "#ffffff",
              color: "#112533",
              borderRadius: "1.25em",
              boxShadow: "0 4px 12px rgba(0, 0, 0, 0.1)",
              borderColor: result.isError ? "#dc3545" : undefined,
              borderWidth: result.isError ? "2px" : undefined
            }}
            data-result-index={index}
          >
            <Card.Body className="position-relative">
              <div className="card-content-area">{renderContent()}</div>
            </Card.Body>
          </Card>
        </div>
      </div>

      <AdditionalInformationModal
        show={showInfoModal}
        onClose={handleCloseInfo}
        result={modalOverride || result}
      />
      <GraphModal
        show={showGraphModal}
        graph={graph}
        onClose={handleCloseGraph}
      />
      <TableModal
        show={showTableModal}
        handleClose={handleCloseTable}
        handleResetData={handleResetTableData}
        executionResult={tableData}
      />
      <ContextTablesModal
        show={showContextModal}
        onClose={handleCloseContext}
        tables={contextTables.tables}
        vql={contextTables.vql}
        dataCatalogUrl={config.data_marketplace_url}
      />
      <FeedbackModal
        show={showFeedbackModal}
        onClose={handleCloseFeedback}
        result={result}
        dispatch={dispatch}
        resultIndex={index}
        feedbackEnabled={config.chatbot_feedback}
        onShowToast={setToastConfig}
      />
      <NotificationToast
        show={toastConfig.show}
        message={toastConfig.message}
        variant={toastConfig.variant}
        title={toastConfig.title}
        onClose={() => setToastConfig((prev) => ({ ...prev, show: false }))}
      />
    </>
  );
};

export default ChatItem;

ChatItem.propTypes = {
  result: PropTypes.shape({
    execution_result: PropTypes.shape({
      full: PropTypes.object,
    }),
  }).isRequired,
  index: PropTypes.number,
  dispatch: PropTypes.func,
  setCurrentQuestion: PropTypes.func,
  setQuestionType: PropTypes.func,
  onGenerateReport: PropTypes.func,
  isGeneratingReport: PropTypes.bool,
  resultsContainerRef: PropTypes.object,
};

import React from "react";
import OverlayTrigger from "react-bootstrap/OverlayTrigger";
import Tooltip from "react-bootstrap/Tooltip";

const assetBaseUrl = import.meta.env.BASE_URL;

const renderTooltip = (content) => (
  <Tooltip id="chat-item-action-tooltip">{content}</Tooltip>
);

const ChatItemActions = ({
  result,
  config,
  onOpenInfo,
  onFeedback,
  resultsContainerRef,
}) => {
  const tooltipText = result && result.isError ? "View error details" : "AI";

  const feedbackIcon = config.chatbot_feedback ? (
    <OverlayTrigger
      placement="left"
      delay={{ show: 250, hide: 400 }}
      overlay={renderTooltip("Provide feedback")}
      container={resultsContainerRef && resultsContainerRef.current}
    >
      <img
        src={`${assetBaseUrl}feedback.svg`}
        alt="Feedback"
        width="20"
        height="20"
        className="ms-2 cursor-pointer"
        onClick={onFeedback}
      />
    </OverlayTrigger>
  ) : null;

  const renderBaseIcon = () => {
    // Always show AI icon as requested for the parent result object
    return (
      <OverlayTrigger
        placement="left"
        delay={{ show: 250, hide: 400 }}
        overlay={renderTooltip(tooltipText)}
        container={resultsContainerRef && resultsContainerRef.current}
      >
        <img
          src={`${assetBaseUrl}ai.png`}
          alt="AI Icon"
          width="20"
          height="20"
          className="cursor-pointer"
          onClick={onOpenInfo}
        />
      </OverlayTrigger>
    );
  };

  return (
    <div className="d-flex flex-row align-items-center position-relative">
      {renderBaseIcon()}
      {feedbackIcon}
    </div>
  );
};

export default ChatItemActions;

import React from "react";
import Button from "react-bootstrap/Button";
import OverlayTrigger from "react-bootstrap/OverlayTrigger";
import Tooltip from "react-bootstrap/Tooltip";

const assetBaseUrl = import.meta.env.BASE_URL;

const renderTooltip = (content) => (
  <Tooltip id="context-tooltip">{content}</Tooltip>
);

const ContextTablesAction = ({ tables, vql, dataCatalogUrl, icons, onOpenContext }) => {
  if (!tables || tables.length === 0) {
    return icons || null;
  }

  let cleanVql = "";
  if (Array.isArray(vql)) {
    cleanVql = vql
      .filter(Boolean)
      .map((x) => String(x).replace(/"/g, "").toLowerCase())
      .join(" ");
  } else if (vql) {
    cleanVql = String(vql).replace(/"/g, "").toLowerCase();
  }

  const usedTables = [];
  const unusedTables = [];

  tables.forEach((table) => {
    const cleanTable = table.replace(/"/g, "").toLowerCase();
    const isUsedInVql = cleanVql.includes(cleanTable);

    if (isUsedInVql) {
      usedTables.push(table);
    } else {
      unusedTables.push(table);
    }
  });

  const renderTableButton = (table, index, isUsed = true) => {
    const cleanTable = table.replace(/"/g, "").toLowerCase();
    const tableParts = cleanTable.split(".");
    const schema = tableParts[0];
    const tableName = tableParts[1] || schema;

    const catalogUrl = dataCatalogUrl
      ? `${dataCatalogUrl}/#/view/${schema}/${tableName}`
      : null;

    if (catalogUrl) {
      return (
        <a
          key={index}
          href={catalogUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="text-decoration-none"
        >
          <Button
            variant={isUsed ? "success" : "secondary"}
            size="sm"
            bsPrefix="btn"
            className="me-1 mb-1 d-inline-flex align-items-center"
          >
            <img
              src={`${assetBaseUrl}denodo_view.svg`}
              alt="View"
              width="16"
              height="16"
              className="me-1"
            />
            {table.replace(/"/g, "")}
          </Button>
        </a>
      );
    }

    return (
      <Button
        key={index}
        variant={isUsed ? "success" : "secondary"}
        size="sm"
        bsPrefix="btn"
        className="me-1 mb-1 d-inline-flex align-items-center"
        style={isUsed ? { backgroundColor: "#143142", borderColor: "#143142" } : {}}
      >
        {table.replace(/"/g, "")}
      </Button>
    );
  };

  const hasTableButtons = usedTables.length > 0 || unusedTables.length > 0;

  return (
    <div
      style={{
        backgroundColor: "transparent",
        padding: "1rem 0",
        marginBottom: "0",
      }}
    >
      <div
        className={`mb-2 d-flex ${
          hasTableButtons ? "justify-content-between" : "justify-content-end"
        } align-items-center`}
      >
        {hasTableButtons && (
          <div className="context-badges-container">
            {usedTables.map((table, index) =>
              renderTableButton(table, index, true)
            )}
            {unusedTables.length > 0 && (
              <OverlayTrigger
                placement="top"
                delay={{ show: 250, hide: 400 }}
                overlay={renderTooltip("View all searched tables")}
              >
                <Button
                  variant="outline-info"
                  size="sm"
                  className="me-1 mb-1 d-inline-flex align-items-center context-more-btn"
                  onClick={() => onOpenContext(tables, vql)}
                >
                  +{unusedTables.length} more
                </Button>
              </OverlayTrigger>
            )}
          </div>
        )}
        {icons && (
          <div
            className="d-flex flex-row align-items-center"
            style={{ gap: "8px" }}
          >
            {icons}
          </div>
        )}
      </div>
    </div>
  );
};

export default ContextTablesAction;

import React, { useMemo } from "react";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";

const assetBaseUrl = import.meta.env.BASE_URL;

const ContextTablesModal = ({ show, onClose, tables, vql, dataCatalogUrl }) => {
  const { usedTables, unusedTables } = useMemo(() => {
    if (!tables || tables.length === 0) {
      return { usedTables: [], unusedTables: [] };
    }

    let cleanVql = "";
    if (Array.isArray(vql)) {
      cleanVql = vql
        .filter(Boolean)
        .map((x) => String(x).replace(/"/g, "").toLowerCase())
        .join(" ");
    } else if (vql) {
      cleanVql = String(vql).replace(/"/g, "").toLowerCase();
    }
    const used = [];
    const unused = [];

    tables.forEach((table) => {
      const cleanTable = table.replace(/"/g, "").toLowerCase();
      const isUsedInVql = cleanVql.includes(cleanTable);
      if (isUsedInVql) {
        used.push(table);
      } else {
        unused.push(table);
      }
    });

    return { usedTables: used, unusedTables: unused };
  }, [tables, vql]);

  const renderTableButton = (table, index, variant) => {
    const cleanTable = table.replace(/"/g, "").toLowerCase();
    const tableParts = cleanTable.split(".");
    const schema = tableParts[0];
    const tableName = tableParts[1] || schema;
    const catalogUrl = dataCatalogUrl
      ? `${dataCatalogUrl}/#/view/${schema}/${tableName}`
      : null;

    if (catalogUrl) {
      return (
        <a
          key={index}
          href={catalogUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="text-decoration-none"
        >
          <Button
            variant={variant}
            size="sm"
            className="me-2 mb-2 d-inline-flex align-items-center"
          >
            <img
              src={`${assetBaseUrl}denodo_view.svg`}
              alt="View"
              width="16"
              height="16"
              className="me-1"
            />
            {table.replace(/"/g, "")}
          </Button>
        </a>
      );
    }

    return (
      <Button
        key={index}
        variant={variant}
        size="sm"
        className="me-2 mb-2 d-inline-flex align-items-center"
      >
        {table.replace(/"/g, "")}
      </Button>
    );
  };

  return (
    <Modal show={show} onHide={onClose} size="lg" centered>
      <Modal.Header closeButton data-bs-theme="light">
        <Modal.Title>Context Tables</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        {usedTables.length > 0 && (
          <div className="mb-4">
            <h6 className="mb-3">
              <strong>Used in Query ({usedTables.length})</strong>
            </h6>
            <div className="context-badges-container">
              {usedTables.map((table, index) =>
                renderTableButton(table, index, "success")
              )}
            </div>
          </div>
        )}

        {unusedTables.length > 0 && (
          <div className="mb-3">
            <h6 className="mb-3">
              <strong>
                Searched but Not Used ({unusedTables.length})
              </strong>
            </h6>
            <div className="context-badges-container">
              {unusedTables.map((table, index) =>
                renderTableButton(table, index, "secondary")
              )}
            </div>
          </div>
        )}

        <div className="mt-4 pt-3 border-top border-secondary">
          <small>
            <strong>Note:</strong> Views in green were used to find the answer,
            while grey tables were found in the database but found not relevant
            to the question.
          </small>
        </div>
      </Modal.Body>
      <Modal.Footer>
        <Button variant="light" onClick={onClose}>
          Close
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default ContextTablesModal;

import React, { useState } from "react";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import Form from "react-bootstrap/Form";
import { actionTypes } from "../../reducers/chatReducer";
import { buildApiUrl } from "../../api/client";
import CustomTooltip from "../CustomTooltip/CustomTooltip";

const FeedbackModal = ({ 
  show, 
  onClose, 
  result, 
  dispatch, 
  resultIndex, 
  feedbackEnabled,
  onShowToast
}) => {
  const [feedbackValue, setFeedbackValue] = useState("");
  const [feedbackDetails, setFeedbackDetails] = useState("");
  const [submitting, setSubmitting] = useState(false);

  if (!feedbackEnabled || !result) return null;

  const handleSubmit = async () => {
    if (!result.uuid) return;

    setSubmitting(true);

    try {
      const response = await fetch(buildApiUrl("submit_feedback"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          uuid: result.uuid,
          feedback_value: feedbackValue,
          feedback_details: feedbackDetails,
        }),
      });

      let data = {};
      try {
        data = await response.json();
      } catch {
        data = {
          message: `The server returned an invalid response (HTTP ${response.status}).`,
        };
      }

      if (response.ok) {
        dispatch({
            type: actionTypes.SET_CHAT_ITEM_FEEDBACK,
            payload: { resultIndex, feedback: feedbackValue, feedbackDetails }
        });

        if (onShowToast) {
          onShowToast({
            show: true,
            title: "Feedback Submitted",
            message: "Thank you for your feedback.",
            variant: "success"
          });
        }

        onClose();
      } else {
        if (data.error === "uuid_not_found") {
          if (onShowToast) {
            onShowToast({
              show: true,
              title: "Feedback Not Saved",
              message: "This conversation is too old and its original record has been deleted to save space. Your feedback could not be saved.",
              variant: "warning"
            });
          }
          onClose();
        } else {
          const detail = data.message || `Feedback could not be saved (HTTP ${response.status}).`;
          if (onShowToast) {
            onShowToast({
              show: true,
              title: "Error",
              message: detail,
              variant: "danger"
            });
          } else {
            alert(detail);
          }
        }
      }
    } catch (error) {
      console.error("Error submitting feedback:", error);
      const detail =
        error?.message ||
        "Unable to reach the server. Check your connection and try again.";

      if (onShowToast) {
        onShowToast({
          show: true,
          title: "Connection Error",
          message: `Error submitting feedback: ${detail}`,
          variant: "danger"
        });
      } else {
        alert(`Error submitting feedback: ${detail}`);
      }
    } finally {
      setSubmitting(false);
    }
  };

  const handleHide = () => {
    if (submitting) return;
    setFeedbackValue("");
    setFeedbackDetails("");
    onClose();
  };

  return (
    <Modal show={show} onHide={handleHide} centered>
      <Modal.Header closeButton data-bs-theme="light">
        <Modal.Title>Provide Feedback</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <div className="mb-3">
          <p className="mb-1">
            <strong>Question:</strong>
          </p>
          <p>{result.question}</p>
        </div>
        <Form>
          <Form.Group className="mb-3">
            <Form.Label className="d-flex align-items-center">
              Was this answer helpful?
              <CustomTooltip 
                id="tooltip-feedback-info" 
                content="The feedback submitted in this form is saved in the reports/ folder at the root level of the AI SDK."
              >
                <i 
                  className="bi bi-info-circle ms-2" 
                  style={{ cursor: 'help', fontSize: '0.85rem', color: '#adb5bd', transition: 'color 0.2s' }}
                  onMouseEnter={(e) => e.target.style.color = '#112533'}
                  onMouseLeave={(e) => e.target.style.color = '#adb5bd'}
                ></i>
              </CustomTooltip>
            </Form.Label>
            <div>
              <Form.Check
                inline
                type="radio"
                id="positive-feedback"
                label="Yes"
                name="feedback"
                value="positive"
                checked={feedbackValue === "positive"}
                onChange={() => setFeedbackValue("positive")}
              />
              <Form.Check
                inline
                type="radio"
                id="negative-feedback"
                label="No"
                name="feedback"
                value="negative"
                checked={feedbackValue === "negative"}
                onChange={() => setFeedbackValue("negative")}
              />
            </div>
          </Form.Group>
          <Form.Group className="mb-3">
            <Form.Label>Additional details (optional)</Form.Label>
            <Form.Control
              as="textarea"
              rows={3}
              value={feedbackDetails}
              onChange={(e) => setFeedbackDetails(e.target.value)}
              placeholder="Please provide any additional comments..."
            />
          </Form.Group>
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button variant="light" onClick={handleHide} disabled={submitting}>
          Cancel
        </Button>
        <Button
          variant="dark"
          onClick={handleSubmit}
          disabled={!feedbackValue || submitting}
        >
          {submitting ? "Submitting..." : "Submit Feedback"}
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default FeedbackModal;

import React from "react";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";

const GraphModal = ({ show, graph, onClose }) => {
  return (
    <Modal show={show} onHide={onClose} size="lg" centered>
      <Modal.Header closeButton data-bs-theme="light">
        <Modal.Title>Graph View</Modal.Title>
      </Modal.Header>
      <Modal.Body className="text-center">
        {graph && <img src={graph} alt="Graph" className="img-fluid" />}
      </Modal.Body>
      <Modal.Footer>
        <Button variant="light" onClick={onClose}>
          Close
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default GraphModal;

import React, { useState } from "react";
import Button from "react-bootstrap/Button";
import Badge from "react-bootstrap/Badge";

const RelatedQuestions = ({
  relatedQuestions,
  relatedQuestionsDeepQuery,
  onAskRelated,
  onAskDeepQuery,
}) => {
  const hasRegularQuestions =
    relatedQuestions && relatedQuestions.length > 0;
  const hasDeepQueryQuestions =
    relatedQuestionsDeepQuery && relatedQuestionsDeepQuery.length > 0;

  const [currentIndex, setCurrentIndex] = useState(0);
  const [animationClass, setAnimationClass] = useState("");

  if (!hasRegularQuestions && !hasDeepQueryQuestions) return null;

  const showCarouselArrows =
    hasRegularQuestions && relatedQuestions.length > 1;

  const navigate = (direction) => {
    if (!hasRegularQuestions || relatedQuestions.length <= 1) return;

    const total = relatedQuestions.length;
    let nextIndex;

    if (direction === "next") {
      nextIndex = (currentIndex + 1) % total;
      setAnimationClass("slide-in-right");
    } else {
      nextIndex = currentIndex === 0 ? total - 1 : currentIndex - 1;
      setAnimationClass("slide-in-left");
    }

    setCurrentIndex(nextIndex);

    setTimeout(() => {
      setAnimationClass("");
    }, 400);
  };

  const currentQuestion =
    hasRegularQuestions && relatedQuestions[currentIndex];

  return (
    <div className="d-flex flex-column align-items-start mt-3">
      {hasRegularQuestions && (
        <div className="w-100 mb-2">
          <Button
            variant="outline-light"
            size="sm"
            className="text-start w-100 related-question-btn"
            onClick={() => currentQuestion && onAskRelated(currentQuestion)}
          >
            <div className="d-flex align-items-center justify-content-between w-100">
              {showCarouselArrows && (
                <i
                  className="bi bi-chevron-left carousel-arrow-inner"
                  onClick={(e) => {
                    e.stopPropagation();
                    navigate("prev");
                  }}
                />
              )}
              <span
                className={`related-question-text flex-grow-1 text-center ${animationClass}`}
              >
                {currentQuestion}
              </span>
              {showCarouselArrows && (
                <i
                  className="bi bi-chevron-right carousel-arrow-inner"
                  onClick={(e) => {
                    e.stopPropagation();
                    navigate("next");
                  }}
                />
              )}
            </div>
          </Button>
        </div>
      )}

      {hasDeepQueryQuestions &&
        relatedQuestionsDeepQuery.map((q, index) => (
          <Button
            key={`deep_query-${index}`}
            variant="outline-warning"
            size="sm"
            className="mb-2 text-start w-100 analyst-question-btn"
            onClick={() => onAskDeepQuery(q)}
          >
            <div className="d-flex align-items-center justify-content-between w-100">
              <span
                className="text-white flex-grow-1"
                style={{ fontWeight: "500" }}
              >
                {q}
              </span>
              <Badge className="analyst-mode-badge">DeepQuery</Badge>
            </div>
          </Button>
        ))}
    </div>
  );
};

export default RelatedQuestions;

import React, { useState, useMemo } from "react";
import PropTypes from "prop-types";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import Table from "react-bootstrap/Table";
import Pagination from "react-bootstrap/Pagination";

const TableModal = ({ show, handleClose, handleResetData, executionResult }) => {
  const [currentPage, setCurrentPage] = useState(1);
  const rowsPerPage = 10;

  const handleOnExited = () => {
    setCurrentPage(1);
    if (handleResetData) handleResetData();
  };

  const tableData = useMemo(() => {
    if (
      !executionResult ||
      typeof executionResult === "string" ||
      Object.keys(executionResult).length === 0
    ) {
      return { headers: [], rows: [] };
    }

    const rows = Object.values(executionResult);
    if (rows.length === 0 || !Array.isArray(rows[0])) {
      return { headers: [], rows: [] };
    }

    const headers = rows[0].map((item) => item.columnName);
    const dataRows = rows.map((row) => row.map((item) => item.value));

    return { headers, rows: dataRows };
  }, [executionResult]);

  const totalRows = tableData.rows.length;
  const totalPages = Math.ceil(totalRows / rowsPerPage);

  const paginatedRows = useMemo(() => {
    const startIndex = (currentPage - 1) * rowsPerPage;
    const endIndex = Math.min(startIndex + rowsPerPage, totalRows);
    return tableData.rows.slice(startIndex, endIndex);
  }, [tableData.rows, currentPage, rowsPerPage, totalRows]);

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  const renderPagination = () => {
    if (totalPages <= 1) return null;

    const items = [];
    const maxPageItems = 5;
    let startPage = Math.max(1, currentPage - Math.floor(maxPageItems / 2));
    let endPage = Math.min(totalPages, startPage + maxPageItems - 1);

    if (endPage - startPage + 1 < maxPageItems) {
      startPage = Math.max(1, endPage - maxPageItems + 1);
    }

    items.push(
      <Pagination.Prev
        key="prev"
        onClick={() => handlePageChange(Math.max(1, currentPage - 1))}
        disabled={currentPage === 1}
      />
    );

    if (startPage > 1) {
      items.push(
        <Pagination.Item key={1} onClick={() => handlePageChange(1)}>
          1
        </Pagination.Item>
      );
      if (startPage > 2) {
        items.push(<Pagination.Ellipsis key="ellipsis-1" disabled />);
      }
    }

    for (let page = startPage; page <= endPage; page++) {
      items.push(
        <Pagination.Item
          key={page}
          active={page === currentPage}
          onClick={() => handlePageChange(page)}
        >
          {page}
        </Pagination.Item>
      );
    }

    if (endPage < totalPages) {
      if (endPage < totalPages - 1) {
        items.push(<Pagination.Ellipsis key="ellipsis-2" disabled />);
      }
      items.push(
        <Pagination.Item key={totalPages} onClick={() => handlePageChange(totalPages)}>
          {totalPages}
        </Pagination.Item>
      );
    }

    items.push(
      <Pagination.Next
        key="next"
        onClick={() => handlePageChange(Math.min(totalPages, currentPage + 1))}
        disabled={currentPage === totalPages}
      />
    );

    return (
      <div className="d-flex justify-content-center mt-3" data-bs-theme="light">
        <Pagination>{items}</Pagination>
      </div>
    );
  };

  return (
    <Modal 
      show={show} 
      onHide={handleClose} 
      onExited={handleOnExited}
      size="lg" 
      centered
    >
      <Modal.Header closeButton data-bs-theme="light">
        <Modal.Title>Execution Result</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        {totalRows > 0 ? (
          <>
            <div className="table-responsive">
              <Table className="custom-table" striped bordered hover variant="light">
                <thead>
                  <tr>
                    {tableData.headers.map((header, index) => (
                      <th key={index}>{header}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {paginatedRows.map((row, rowIndex) => (
                    <tr key={rowIndex}>
                      {row.map((cell, cellIndex) => (
                        <td key={cellIndex}>{String(cell)}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </Table>
            </div>
            {renderPagination()}
            <div className="mt-3 text-center">
              Showing rows {(currentPage - 1) * rowsPerPage + 1}-
              {Math.min(currentPage * rowsPerPage, totalRows)} of {totalRows}
            </div>
          </>
        ) : (
          <div className="text-center py-4">No data available</div>
        )}
      </Modal.Body>
      <Modal.Footer>
        <Button variant="light" onClick={handleClose}>
          Close
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default TableModal;

TableModal.propTypes = {
  show: PropTypes.bool,
  handleClose: PropTypes.func,
  handleResetData: PropTypes.func,
  executionResult: PropTypes.oneOfType([PropTypes.object, PropTypes.string]),
};

