import React, { useState, useRef, useEffect } from "react";
import { Overlay, Tooltip } from "react-bootstrap";
import "./CustomTooltip.css";

const CustomTooltip = ({
  id,
  content,
  children,
  delay = { show: 400, hide: 250 },
  placement = "right",
}) => {
  const [show, setShow] = useState(false);
  const target = useRef(null);

  const showTimeout = useRef(null);
  const hideTimeout = useRef(null);

  useEffect(() => {
    return () => {
      clearTimeout(showTimeout.current);
      clearTimeout(hideTimeout.current);
    };
  }, []);

  const handleMouseEnter = () => {
    clearTimeout(hideTimeout.current);

    if (!show) {
      showTimeout.current = setTimeout(() => {
        setShow(true);
      }, delay.show);
    }
  };

  const handleMouseLeave = () => {
    clearTimeout(showTimeout.current);

    hideTimeout.current = setTimeout(() => {
      setShow(false);
    }, delay.hide);
  };

  return (
    <>
      {React.cloneElement(children, {
        ref: target,
        onMouseEnter: handleMouseEnter,
        onMouseLeave: handleMouseLeave,
      })}

      <Overlay target={target.current} show={show} placement={placement}>
        {(props) => (
          <Tooltip
            id={id}
            {...props}
            className="custom-light-tooltip"
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
          >
            <div className="custom-tooltip-scroll-content">{content}</div>
          </Tooltip>
        )}
      </Overlay>
    </>
  );
};

export default CustomTooltip;

import React from 'react';
import PropTypes from 'prop-types';
import Form from 'react-bootstrap/Form';
import Button from 'react-bootstrap/Button';
import Spinner from 'react-bootstrap/Spinner';
import Alert from 'react-bootstrap/Alert';
import Table from 'react-bootstrap/Table';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import Popover from 'react-bootstrap/Popover';
import { getDelimiterLabel } from './utils';

const PREVIEW_VALUE_MAX = 200;

const truncateValue = (val) => {
  if (val === undefined || val === null) return '<value>';
  const str = String(val);
  return str.length > PREVIEW_VALUE_MAX ? `${str.slice(0, PREVIEW_VALUE_MAX)}…` : str;
};

const buildColumnHelpPopover = (preview, selected) => {
  // Pick up to three columns to illustrate, prefer ones the user has selected.
  const columns = preview?.columns || [];
  const sampleRow = preview?.rows?.[0] || {};
  const picks = (selected && selected.length ? selected : columns).slice(0, 3);

  return (
    <Popover id="vectorize-help-popover" style={{ maxWidth: '420px' }}>
      <Popover.Header as="h3">What does "columns to vectorize" mean?</Popover.Header>
      <Popover.Body style={{ fontSize: '0.85em' }}>
        <p className="mb-2">
          The <strong>selected columns</strong> become the searchable text that gets
          embedded. This means that the similarity search will be performed on the composite string of those columns.
          When searching, the knowledge_query tool will return this composite string.
        </p>
        <p className="mb-2">
          With your current pick the embedded text for the first row would be:
        </p>
        <div className="p-2 bg-light rounded mb-2" style={{ whiteSpace: 'pre-wrap' }}>
          {picks.length === 0 ? (
            <em>(pick at least one column)</em>
          ) : (
            picks.map((c, i) => (
              <div key={c} className={i < picks.length - 1 ? 'mb-2' : ''}>
                <strong>{c}:</strong> {truncateValue(sampleRow[c])}
              </div>
            ))
          )}
        </div>
        <hr />
        <p className="mb-0 text-muted">
          Tip: pick columns whose <em>meaning</em> answers questions (titles, descriptions,
          bodies). Skip IDs, timestamps and other columns that look like noise.
        </p>
      </Popover.Body>
    </Popover>
  );
};

const AddCSVForm = ({
  newCSV,
  setNewCSV,
  preview,
  isLoadingPreview,
  isGeneratingDescription,
  isAdding,
  currentUserIsAdmin,
  onSubmit,
  onCancel,
  onFileChange,
  onGenerateDescription
}) => {
  const columns = preview?.columns || [];
  const selected = newCSV.vectorizedColumns || [];

  const toggleColumn = (col) => {
    setNewCSV((prev) => {
      const current = new Set(prev.vectorizedColumns || []);
      if (current.has(col)) current.delete(col);
      else current.add(col);
      // Preserve column order from preview when storing.
      const ordered = columns.filter((c) => current.has(c));
      return { ...prev, vectorizedColumns: ordered };
    });
  };

  const setAll = (value) => {
    setNewCSV((prev) => ({ ...prev, vectorizedColumns: value ? [...columns] : [] }));
  };

  return (
    <div className="mb-4 p-3 border rounded">
      <h6>Add New CSV Source</h6>
      <Form onSubmit={onSubmit}>
        {newCSV.path ? (
          <Alert variant="light" className="py-2 mb-3">
            <small><strong>File:</strong> {newCSV.sourceName}.csv</small>
          </Alert>
        ) : (
          <Form.Group className="mb-3">
            <Form.Label>Select CSV file</Form.Label>
            <Form.Control type="file" accept=".csv" onChange={onFileChange} />
          </Form.Group>
        )}

        {isLoadingPreview && (
          <div className="mb-3 text-muted">
            <Spinner size="sm" className="me-2" />Loading preview...
          </div>
        )}

        {preview && (
          <div className="mb-3 p-2 bg-light rounded" style={{ fontSize: '0.85em' }}>
            <div className="mb-2">
              {newCSV.sourceName && (
                <span className="me-3"><strong>Collection name:</strong> {newCSV.sourceName}</span>
              )}
              <strong>Detected delimiter:</strong> {getDelimiterLabel(preview.delimiter)}
              <span className="ms-3"><strong>Columns:</strong> {preview.columns.length}</span>
            </div>
            <div style={{ maxHeight: '150px', overflowY: 'auto', overflowX: 'auto' }}>
              <Table size="sm" bordered style={{ fontSize: '0.8em', marginBottom: 0 }}>
                <thead>
                  <tr>
                    {preview.columns.map((col) => (
                      <th key={col} style={{ whiteSpace: 'nowrap', padding: '4px 8px' }}>{col}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {preview.rows.map((row, rowIdx) => {
                    const rowKey = `row-${Object.values(row).slice(0, 2).join('-')}-${rowIdx}`;
                    return (
                      <tr key={rowKey}>
                        {preview.columns.map((col) => (
                          <td key={col} style={{ whiteSpace: 'nowrap', padding: '4px 8px', maxWidth: '200px', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                            {row[col]}
                          </td>
                        ))}
                      </tr>
                    );
                  })}
                </tbody>
              </Table>
            </div>
          </div>
        )}

        {columns.length > 0 && (
          <Form.Group className="mb-3">
            <Form.Label className="d-flex align-items-center">
              Columns to vectorize
              <OverlayTrigger
                trigger={['click', 'focus']}
                placement="right"
                rootClose
                overlay={buildColumnHelpPopover(preview, selected)}
              >
                <Button variant="link" size="sm" className="p-0 ms-2" title="What does this mean?">
                  <i className="bi bi-question-circle text-secondary"></i>
                </Button>
              </OverlayTrigger>
              <span className="ms-auto">
                <Button variant="link" size="sm" className="p-0 me-2" onClick={() => setAll(true)}>Select all</Button>
                <Button variant="link" size="sm" className="p-0" onClick={() => setAll(false)}>None</Button>
              </span>
            </Form.Label>
            <div className="d-flex flex-wrap gap-2 p-2 border rounded bg-white">
              {columns.map((col) => {
                const isChecked = selected.includes(col);
                return (
                  <Form.Check
                    key={col}
                    type="checkbox"
                    id={`vectorize-col-${col}`}
                    label={col}
                    checked={isChecked}
                    onChange={() => toggleColumn(col)}
                    className="me-2"
                  />
                );
              })}
            </div>
            <Form.Text muted>
              Selected: {selected.length}/{columns.length}. At least one column is required.
            </Form.Text>
          </Form.Group>
        )}

        <Form.Group className="mb-3">
          <Form.Label>Delimiter</Form.Label>
          <Form.Control
            type="text"
            maxLength={1}
            value={newCSV.delimiter}
            onChange={(e) => setNewCSV((prev) => ({ ...prev, delimiter: e.target.value }))}
            style={{ width: '60px' }}
          />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>
            Description *
            {(newCSV.file || newCSV.path) && (
              <Button
                variant="outline-primary"
                size="sm"
                className="ms-2"
                onClick={onGenerateDescription}
                disabled={isGeneratingDescription}
              >
                {isGeneratingDescription ? (
                  <><Spinner size="sm" className="me-1" />Generating...</>
                ) : '✨ Suggest Description with AI'}
              </Button>
            )}
          </Form.Label>
          <Form.Control
            as="textarea"
            rows={3}
            placeholder="Describe the contents of the CSV file"
            value={newCSV.description}
            onChange={(e) => setNewCSV((prev) => ({ ...prev, description: e.target.value }))}
            required
          />
        </Form.Group>

        {currentUserIsAdmin ? (
          <Form.Group className="mb-3">
            <Form.Check
              type="switch"
              id="csv-private-toggle"
              label={
                <span>
                  <i className={`bi ${newCSV.private ? 'bi-lock-fill' : 'bi-unlock'} me-1`} />
                  Private — only you can see this collection
                </span>
              }
              checked={!!newCSV.private}
              onChange={(e) => setNewCSV((prev) => ({ ...prev, private: e.target.checked }))}
            />
            <Form.Text muted>
              As an admin you can publish this collection. Toggle off to make it public for
              everyone using this chatbot. Only the owner can later delete it or edit its description.
            </Form.Text>
          </Form.Group>
        ) : (
          <Alert variant="light" className="py-2 mb-3 d-flex align-items-center">
            <i className="bi bi-lock-fill me-2 text-dark" />
            <small className="mb-0">
              This collection will be <strong>private</strong> — only visible to you.
              Only an admin can publish a collection.
            </small>
          </Alert>
        )}

        <div className="d-flex gap-2">
          <Button variant="light" onClick={onCancel}>Cancel</Button>
          <Button
            variant="dark"
            type="submit"
            disabled={
              isAdding
              || !newCSV.description
              || (!newCSV.file && !newCSV.path)
              || selected.length === 0
            }
          >
            {isAdding ? <Spinner size="sm" /> : 'Add Source'}
          </Button>
        </div>
      </Form>
    </div>
  );
};

AddCSVForm.propTypes = {
  newCSV: PropTypes.shape({
    file: PropTypes.object,
    description: PropTypes.string,
    delimiter: PropTypes.string,
    path: PropTypes.string,
    sourceName: PropTypes.string,
    vectorizedColumns: PropTypes.arrayOf(PropTypes.string),
    private: PropTypes.bool
  }).isRequired,
  setNewCSV: PropTypes.func.isRequired,
  preview: PropTypes.shape({
    delimiter: PropTypes.string,
    columns: PropTypes.arrayOf(PropTypes.string),
    rows: PropTypes.arrayOf(PropTypes.object)
  }),
  isLoadingPreview: PropTypes.bool.isRequired,
  isGeneratingDescription: PropTypes.bool.isRequired,
  isAdding: PropTypes.bool.isRequired,
  currentUserIsAdmin: PropTypes.bool,
  onSubmit: PropTypes.func.isRequired,
  onCancel: PropTypes.func.isRequired,
  onFileChange: PropTypes.func.isRequired,
  onGenerateDescription: PropTypes.func.isRequired
};

export default AddCSVForm;

import React, { useState, useEffect, useCallback } from 'react';
import PropTypes from 'prop-types';
import Modal from 'react-bootstrap/Modal';
import Button from 'react-bootstrap/Button';
import Spinner from 'react-bootstrap/Spinner';
import Alert from 'react-bootstrap/Alert';
import Table from 'react-bootstrap/Table';
import api from '../../../api/client';
import AddCSVForm from './AddCSVForm';
import SourceRow from './SourceRow';
import ScannedFileRow from './ScannedFileRow';
import NotificationToast from '../../NotificationToast/NotificationToast';

const emptyNewCSV = {
  file: null,
  description: '',
  delimiter: ';',
  path: null,
  sourceName: null,
  vectorizedColumns: [],
  private: false
};

const CSVManagerModal = ({ show, handleClose, hasActiveConversation = false, selectedChatbot }) => {
  const agentName = selectedChatbot?.name || 'General Chat';
  const [sources, setSources] = useState([]);
  const [scannedFiles, setScannedFiles] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newCSV, setNewCSV] = useState(emptyNewCSV);
  const [isAdding, setIsAdding] = useState(false);
  const [preview, setPreview] = useState(null);
  const [isLoadingPreview, setIsLoadingPreview] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);
  const [editingSource, setEditingSource] = useState(null);
  const [editingDescription, setEditingDescription] = useState('');
  const [currentUsername, setCurrentUsername] = useState('');
  const [currentUserIsAdmin, setCurrentUserIsAdmin] = useState(false);
  const [downloadingSources, setDownloadingSources] = useState(() => new Set());
  const [deletingSources, setDeletingSources] = useState(() => new Set());
  const [togglingPrivateSources, setTogglingPrivateSources] = useState(() => new Set());

  // Tracks whether the user has made any change to sources during this
  // open-session of the modal. Used to decide whether to warn on close
  // that changes won't apply to an ongoing conversation.
  const [hasChanges, setHasChanges] = useState(false);

  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: '',
    variant: 'info',
    title: '',
    duration: 8000,
  });

  const showToast = (message, variant, title, duration = 8000) => {
    setToastConfig({ show: true, message, variant, title, duration });
  };

  const handleToastClose = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  // Flip the dirty flag whenever a mutation succeeds, so we know on close
  // whether to warn that changes won't apply to the ongoing conversation.
  const notifySourcesChanged = useCallback(() => {
    setHasChanges(true);
  }, []);

  // Reset dirty state every time the modal is opened.
  useEffect(() => {
    if (show) {
      setHasChanges(false);
    }
  }, [show]);

  // Intercept the Close button / backdrop dismiss: if the user made changes
  // and there's an ongoing conversation, show the warning via Toast.
  const requestClose = () => {
    if (hasChanges && hasActiveConversation) {
      showToast(
        "Changes saved. The agent may rely on previous context and ignore new files. Ask it to 'search again' or start a new chat.",
        "info",
        "Knowledge base updated",
        8000
      );
    }
    handleClose();
  };

  const addBusy = (setter, name) =>
    setter((prev) => {
      const next = new Set(prev);
      next.add(name);
      return next;
    });
  const removeBusy = (setter, name) =>
    setter((prev) => {
      const next = new Set(prev);
      next.delete(name);
      return next;
    });

  useEffect(() => {
    setCurrentUsername(localStorage.getItem('current_user') || '');
  }, [show]);

  const fetchSources = useCallback(async () => {
    if (!show) return;
    setIsLoading(true);
    setError(null);
    try {
      const response = await api.get('csv/list');
      if (response.data.success) {
        setSources(response.data.sources || []);
        setCurrentUserIsAdmin(!!response.data.current_user_is_admin);
      }
    } catch (err) {
      setError('Failed to load CSV sources');
      console.error('Error fetching CSV sources:', err);
    } finally {
      setIsLoading(false);
    }
  }, [show]);

  const fetchScannedFiles = useCallback(async () => {
    if (!show) return;
    try {
      const response = await api.get('csv/scan');
      if (response.data.success) {
        const sourceNames = new Set(sources.map((s) => s.source_name));
        setScannedFiles((response.data.files || []).filter((f) => !sourceNames.has(f.source_name)));
      }
    } catch (err) {
      console.error('Error scanning CSV files:', err);
    }
  }, [show, sources]);

  useEffect(() => { fetchSources(); }, [fetchSources]);
  useEffect(() => { fetchScannedFiles(); }, [fetchScannedFiles]);

  const handleToggleActive = async (sourceName, currentActive) => {
    const source = sources.find((s) => s.source_name === sourceName);
    if (!currentActive && source && !source.description?.trim()) {
      setError('Cannot activate source without a description.');
      return;
    }
    try {
      const response = await api.post('csv/activate', { source_name: sourceName, active: !currentActive });
      if (response.data.success) {
        setSources((prev) => prev.map((s) => s.source_name === sourceName ? { ...s, active: !currentActive } : s));
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to toggle source: ${err.response?.data?.error || err.message}`);
    }
  };

  const handleDelete = async (sourceName, deleteFile = false) => {
    if (deletingSources.has(sourceName)) return;
    const confirmMessage = `Are you sure you want to delete "${sourceName}"? This removes it for all users of this chatbot.${deleteFile ? ' The CSV file will also be deleted.' : ''}`;
    if (!window.confirm(confirmMessage)) return;
    addBusy(setDeletingSources, sourceName);
    try {
      const response = await api.delete(`csv/delete/${sourceName}`, { data: { delete_file: deleteFile } });
      if (response.data.success) {
        setSources((prev) => prev.filter((s) => s.source_name !== sourceName));
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to delete source: ${err.response?.data?.error || err.message}`);
    } finally {
      removeBusy(setDeletingSources, sourceName);
    }
  };

  const handleTogglePrivate = async (sourceName, nextPrivate) => {
    if (togglingPrivateSources.has(sourceName)) return;
    addBusy(setTogglingPrivateSources, sourceName);
    try {
      const response = await api.post('csv/set_private', { source_name: sourceName, private: nextPrivate });
      if (response.data.success) {
        setSources((prev) => prev.map((s) =>
          s.source_name === sourceName ? { ...s, private: nextPrivate } : s
        ));
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to update visibility: ${err.response?.data?.error || err.message}`);
    } finally {
      removeBusy(setTogglingPrivateSources, sourceName);
    }
  };

  const handleDownload = async (sourceName) => {
    if (downloadingSources.has(sourceName)) return;
    setDownloadingSources((prev) => {
      const next = new Set(prev);
      next.add(sourceName);
      return next;
    });
    try {
      const response = await api.get(`csv/download/${sourceName}`, { responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([response.data], { type: 'text/csv' }));
      const link = document.createElement('a');
      link.href = url;
      link.download = `${sourceName}_with_embeddings.csv`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      setError(`Failed to download CSV: ${err.response?.data?.error || err.message}`);
    } finally {
      setDownloadingSources((prev) => {
        const next = new Set(prev);
        next.delete(sourceName);
        return next;
      });
    }
  };

  const handleUpdateDescription = async (sourceName) => {
    if (!editingDescription.trim()) { setError('Description cannot be empty'); return; }
    try {
      const response = await api.post('csv/update_description', {
        source_name: sourceName,
        description: editingDescription.trim()
      });
      if (response.data.success) {
        setSources((prev) => prev.map((s) =>
          s.source_name === sourceName ? { ...s, description: editingDescription.trim() } : s
        ));
        setEditingSource(null);
        setEditingDescription('');
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to update description: ${err.response?.data?.error || err.message}`);
    }
  };

  const handleStartEditing = (source) => {
    setEditingSource(source.source_name);
    setEditingDescription(source.description || '');
  };

  const handleCancelEditing = () => {
    setEditingSource(null);
    setEditingDescription('');
  };

  const handleAddScannedFile = async (scannedFile) => {
    setIsLoadingPreview(true);
    setShowAddForm(true);
    setNewCSV({ ...emptyNewCSV, path: scannedFile.path, sourceName: scannedFile.source_name });
    try {
      const response = await api.post('csv/preview', { path: scannedFile.path });
      if (response.data.success) {
        setPreview(response.data);
        setNewCSV((prev) => ({
          ...prev,
          delimiter: response.data.delimiter,
          vectorizedColumns: response.data.columns || []
        }));
      }
    } catch (err) {
      setError(`Failed to preview CSV: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsLoadingPreview(false);
    }
  };

  const handleGenerateDescription = async () => {
    if (!newCSV.file && !newCSV.path) return;
    setIsGeneratingDescription(true);
    try {
      let response;
      const vectorizedColumns = newCSV.vectorizedColumns || [];
      if (newCSV.path) {
        response = await api.post('csv/generate_description', {
          path: newCSV.path,
          delimiter: newCSV.delimiter,
          vectorized_columns: vectorizedColumns
        });
      } else {
        const formData = new FormData();
        formData.append('file', newCSV.file);
        formData.append('delimiter', newCSV.delimiter);
        formData.append('vectorized_columns', JSON.stringify(vectorizedColumns));
        response = await api.post('csv/generate_description', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
      }
      if (response.data.success) {
        setNewCSV((prev) => ({ ...prev, description: response.data.description }));
      }
    } catch (err) {
      setError(`Failed to generate description: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsGeneratingDescription(false);
    }
  };

  const handleAddSource = async (e) => {
    e.preventDefault();
    if (!newCSV.file && !newCSV.path) { setError('Please select a CSV file'); return; }
    if (!newCSV.description) { setError('Description is required'); return; }
    if (!newCSV.vectorizedColumns || newCSV.vectorizedColumns.length === 0) {
      setError('Select at least one column to vectorize');
      return;
    }

    setIsAdding(true);
    setError(null);
    try {
      let response;
      const vectorizedColumnsJson = JSON.stringify(newCSV.vectorizedColumns);
      if (newCSV.path) {
        response = await api.post('csv/add', {
          path: newCSV.path,
          source_name: newCSV.sourceName,
          description: newCSV.description,
          delimiter: newCSV.delimiter,
          auto_detect_delimiter: false,
          auto_generate_description: false,
          vectorized_columns: newCSV.vectorizedColumns,
          private: currentUserIsAdmin ? !!newCSV.private : true
        });
      } else {
        const formData = new FormData();
        formData.append('file', newCSV.file);
        formData.append('description', newCSV.description);
        formData.append('delimiter', newCSV.delimiter);
        formData.append('auto_detect_delimiter', 'false');
        formData.append('auto_generate_description', 'false');
        formData.append('vectorized_columns', vectorizedColumnsJson);
        formData.append('private', (currentUserIsAdmin ? !!newCSV.private : true) ? 'true' : 'false');
        response = await api.post('csv/add', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
      }

      if (response.data.success) {
        await fetchSources();
        setNewCSV(emptyNewCSV);
        setPreview(null);
        setShowAddForm(false);
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to add CSV: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsAdding(false);
    }
  };

  const handleFileChange = async (e) => {
    const file = e.target.files?.[0];
    if (file?.name.endsWith('.csv')) {
      setNewCSV((prev) => ({ ...prev, file, sourceName: file.name.replace(/\.csv$/, '') }));
      setPreview(null);
      setIsLoadingPreview(true);
      try {
        const formData = new FormData();
        formData.append('file', file);
        const response = await api.post('csv/preview', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        if (response.data.success) {
          setPreview(response.data);
          setNewCSV((prev) => ({
            ...prev,
            delimiter: response.data.delimiter,
            vectorizedColumns: response.data.columns || []
          }));
        }
      } catch (err) {
        setError(`Failed to preview CSV: ${err.response?.data?.error || err.message}`);
      } finally {
        setIsLoadingPreview(false);
      }
    } else if (file) {
      setError('Please select a valid CSV file');
      e.target.value = null;
    }
  };

  const handleCancelAddForm = () => {
    setShowAddForm(false);
    setPreview(null);
    setNewCSV(emptyNewCSV);
  };

  const hasNoData = sources.length === 0 && scannedFiles.length === 0;

  return (
    <>
      <Modal show={show} onHide={requestClose} centered size="xl" dialogClassName="modal-90w">
        <Modal.Header closeButton data-bs-theme="light">
          <Modal.Title>Knowledge Base Manager</Modal.Title>
        </Modal.Header>
        <Modal.Body style={{ maxHeight: '70vh', overflowY: 'auto' }}>
          {error && (
            <Alert variant="danger" onClose={() => setError(null)} dismissible>
              {error}
            </Alert>
          )}

          <Alert variant="primary" className="mb-3 py-2">
            <small>
              <i className="bi bi-info-circle me-1" />
              You are configuring the knowledge base for <strong>{agentName}</strong>.
              <strong> Active</strong> toggles apply <strong>only to this chatbot</strong> — the
              same collection can be active in some chatbots and inactive in others.
              Uploading, deleting and changing <strong>Public/Private</strong> visibility apply to
              every chatbot.
            </small>
          </Alert>

          {showAddForm ? (
            <AddCSVForm
              newCSV={newCSV}
              setNewCSV={setNewCSV}
              preview={preview}
              isLoadingPreview={isLoadingPreview}
              isGeneratingDescription={isGeneratingDescription}
              isAdding={isAdding}
              currentUserIsAdmin={currentUserIsAdmin}
              onSubmit={handleAddSource}
              onCancel={handleCancelAddForm}
              onFileChange={handleFileChange}
              onGenerateDescription={handleGenerateDescription}
            />
          ) : (
            <Button
              variant="outline-dark"
              size="sm"
              className="mb-3"
              onClick={() => setShowAddForm(true)}
            >
              + Add CSV Source
            </Button>
          )}

          {isLoading && !showAddForm && (
            <div className="text-center p-4"><Spinner animation="border" /></div>
          )}

          {!isLoading && hasNoData && (
            <Alert variant="warning">
              No CSV sources configured. Click "Add CSV Source" to add one.
            </Alert>
          )}

          {!isLoading && !hasNoData && (
            <Table striped bordered hover size="sm" variant="light">
              <thead>
                <tr>
                  <th style={{ width: '70px' }}>Active</th>
                  <th>Name</th>
                  <th style={{ width: '130px' }}>Status</th>
                  <th>Description</th>
                  <th style={{ width: '120px' }}>Owner</th>
                  <th style={{ width: '140px' }}>Uploaded</th>
                  <th style={{ width: '200px' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {sources.map((source) => (
                  <SourceRow
                    key={source.source_name}
                    source={source}
                    currentUsername={currentUsername}
                    editingSource={editingSource}
                    editingDescription={editingDescription}
                    onToggleActive={handleToggleActive}
                    onDelete={handleDelete}
                    onDownload={handleDownload}
                    isDownloading={downloadingSources.has(source.source_name)}
                    isDeleting={deletingSources.has(source.source_name)}
                    isTogglingPrivate={togglingPrivateSources.has(source.source_name)}
                    onTogglePrivate={handleTogglePrivate}
                    onStartEditing={handleStartEditing}
                    onUpdateDescription={handleUpdateDescription}
                    onCancelEditing={handleCancelEditing}
                    setEditingDescription={setEditingDescription}
                  />
                ))}
                {scannedFiles.map((scannedFile) => (
                  <ScannedFileRow
                    key={`scanned-${scannedFile.source_name}`}
                    scannedFile={scannedFile}
                    onAdd={handleAddScannedFile}
                  />
                ))}
              </tbody>
            </Table>
          )}

          <Alert variant="info" className="mb-3 py-2">
            <small>
              <strong>Note:</strong> Files in <code>sample_chatbot/sample_data/unstructured</code> are scanned automatically and shown
              as "Scanned" until someone adds them.
            </small>
          </Alert>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="light" onClick={requestClose}>Close</Button>
        </Modal.Footer>
      </Modal>

      <NotificationToast
        show={toastConfig.show}
        message={toastConfig.message}
        variant={toastConfig.variant}
        title={toastConfig.title}
        duration={toastConfig.duration}
        onClose={handleToastClose}
      />
    </>
  );
};

CSVManagerModal.propTypes = {
  show: PropTypes.bool.isRequired,
  handleClose: PropTypes.func.isRequired,
  hasActiveConversation: PropTypes.bool,
  selectedChatbot: PropTypes.object
};

export default CSVManagerModal;

