import React from 'react';
import PropTypes from 'prop-types';
import Form from 'react-bootstrap/Form';
import Button from 'react-bootstrap/Button';
import Badge from 'react-bootstrap/Badge';
import Spinner from 'react-bootstrap/Spinner';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import Tooltip from 'react-bootstrap/Tooltip';

const formatDate = (ms) => {
  if (!ms) return '—';
  const d = new Date(typeof ms === 'number' ? ms : Number(ms));
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleString(undefined, {
    year: 'numeric', month: 'short', day: '2-digit', hour: '2-digit', minute: '2-digit'
  });
};

const SourceRow = ({
  source,
  currentUsername,
  editingSource,
  editingDescription,
  onToggleActive,
  onDelete,
  isDeleting,
  onDownload,
  isDownloading,
  onTogglePrivate,
  isTogglingPrivate,
  onStartEditing,
  onUpdateDescription,
  onCancelEditing,
  setEditingDescription
}) => {
  const isEditing = editingSource === source.source_name;
  const hasDescription = Boolean(source.description?.trim());
  const isOwner = source.is_owner ?? (source.owner && source.owner === currentUsername);
  const isPrivate = Boolean(source.private);
  // Capability flags come from the server; fall back to legacy logic for safety.
  const canSubscribe = source.can_subscribe ?? !isPrivate ?? isOwner;
  const canDelete = source.can_delete ?? isOwner;
  const canEdit = source.can_edit ?? isOwner;
  const canMakePublic = source.can_make_public ?? false;
  const canMakePrivate = source.can_make_private ?? isOwner;
  // The lock/unlock button: show only when the user can change visibility in
  // the direction the click would take it.
  const canTogglePrivacy = isPrivate ? canMakePublic : canMakePrivate;

  return (
    <tr style={{ verticalAlign: 'middle' }}>
      <td className="text-center">
        <Form.Check
          type="switch"
          checked={source.active}
          onChange={() => onToggleActive(source.source_name, source.active)}
          disabled={!hasDescription || !canSubscribe}
          title={
            !canSubscribe
              ? 'Private — only the owner can activate'
              : (hasDescription ? '' : 'Add a description to enable')
          }
        />
      </td>
      <td style={{ maxWidth: '260px', overflowWrap: 'anywhere', wordBreak: 'break-word' }}>
        <strong>{source.source_name}</strong>
        {source.document_count ? (
          <span className="text-muted ms-1" style={{ fontSize: '0.8em' }}>
            ({source.document_count} rows)
          </span>
        ) : null}
      </td>
      <td>
        <div className="d-flex flex-wrap gap-1">
          {isPrivate ? (
            <OverlayTrigger placement="top" overlay={<Tooltip>Visible only to you</Tooltip>}>
              <Badge bg="dark"><i className="bi bi-lock-fill me-1" />Private</Badge>
            </OverlayTrigger>
          ) : (
            <OverlayTrigger placement="top" overlay={<Tooltip>Anyone on this chatbot can use</Tooltip>}>
              <Badge bg="success"><i className="bi bi-globe2 me-1" />Public</Badge>
            </OverlayTrigger>
          )}
          {!source.path_valid && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip>Original CSV file is gone, but vectors are still searchable.</Tooltip>}
            >
              <Badge bg="warning" text="dark" style={{ cursor: 'help' }}>
                <i className="bi bi-exclamation-triangle-fill me-1" />file missing
              </Badge>
            </OverlayTrigger>
          )}
        </div>
      </td>
      <td style={{ fontSize: '0.85em' }}>
        {isEditing ? (
          <div className="d-flex flex-column gap-1">
            <Form.Control
              as="textarea"
              rows={2}
              size="sm"
              value={editingDescription}
              onChange={(e) => setEditingDescription(e.target.value)}
              autoFocus
            />
            <div className="d-flex gap-1">
              <Button variant="dark" size="sm" onClick={() => onUpdateDescription(source.source_name)}>Save</Button>
              <Button variant="light" size="sm" onClick={onCancelEditing}>Cancel</Button>
            </div>
          </div>
        ) : (
          <div
            onDoubleClick={() => canEdit && onStartEditing(source)}
            style={{ cursor: canEdit ? 'pointer' : 'default' }}
            title={canEdit ? 'Double-click to edit' : 'Only the owner can edit the description'}
          >
            {source.description?.substring(0, 100)}
            {source.description?.length > 100 ? '...' : ''}
            {!hasDescription && (
              <span className="text-warning fst-italic">No description</span>
            )}
          </div>
        )}
      </td>
      <td className="text-center" style={{ fontSize: '0.85em' }}>
        {source.owner ? (
          <span className="text-muted">{source.owner}</span>
        ) : (
          <span className="text-muted">—</span>
        )}
      </td>
      <td className="text-center text-muted" style={{ fontSize: '0.8em' }}>
        {formatDate(source.last_vectorized)}
      </td>
      <td>
        <div className="d-flex gap-1 flex-wrap">
          {canSubscribe && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip>{isDownloading ? 'Preparing CSV…' : 'Download CSV with embedding column'}</Tooltip>}
            >
              <Button
                variant="outline-success"
                size="sm"
                onClick={() => onDownload(source.source_name)}
                disabled={isDownloading}
              >
                {isDownloading ? (
                  <Spinner animation="border" size="sm" role="status" aria-label="Downloading" />
                ) : (
                  <i className="bi bi-download" />
                )}
              </Button>
            </OverlayTrigger>
          )}
          {canTogglePrivacy && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip>
                {isTogglingPrivate
                  ? 'Updating visibility…'
                  : isPrivate
                    ? 'Publish (admin only)'
                    : 'Make private (only you can see it)'}
              </Tooltip>}
            >
              <Button
                variant={isPrivate ? 'outline-dark' : 'outline-secondary'}
                size="sm"
                onClick={() => onTogglePrivate(source.source_name, !isPrivate)}
                disabled={isTogglingPrivate || isDeleting}
              >
                {isTogglingPrivate ? (
                  <Spinner animation="border" size="sm" role="status" aria-label="Updating visibility" />
                ) : (
                  <i className={`bi ${isPrivate ? 'bi-unlock' : 'bi-lock'}`} />
                )}
              </Button>
            </OverlayTrigger>
          )}
          {canDelete && (
            <Button
              variant="outline-danger"
              size="sm"
              onClick={() => onDelete(source.source_name, false)}
              disabled={isDeleting || isTogglingPrivate}
              title={isOwner ? '' : 'Admin: delete this collection'}
            >
              {isDeleting ? (
                <>
                  <Spinner animation="border" size="sm" role="status" className="me-1" aria-label="Deleting" />
                  Deleting…
                </>
              ) : 'Delete'}
            </Button>
          )}
        </div>
      </td>
    </tr>
  );
};

SourceRow.propTypes = {
  source: PropTypes.shape({
    source_name: PropTypes.string.isRequired,
    active: PropTypes.bool.isRequired,
    description: PropTypes.string,
    path_valid: PropTypes.bool,
    owner: PropTypes.string,
    is_owner: PropTypes.bool,
    document_count: PropTypes.number,
    vectorized_columns: PropTypes.arrayOf(PropTypes.string),
    last_vectorized: PropTypes.number,
    private: PropTypes.bool,
    can_subscribe: PropTypes.bool,
    can_delete: PropTypes.bool,
    can_edit: PropTypes.bool,
    can_make_public: PropTypes.bool,
    can_make_private: PropTypes.bool
  }).isRequired,
  currentUsername: PropTypes.string,
  editingSource: PropTypes.string,
  editingDescription: PropTypes.string.isRequired,
  onToggleActive: PropTypes.func.isRequired,
  onDelete: PropTypes.func.isRequired,
  isDeleting: PropTypes.bool,
  onDownload: PropTypes.func.isRequired,
  isDownloading: PropTypes.bool,
  onTogglePrivate: PropTypes.func.isRequired,
  isTogglingPrivate: PropTypes.bool,
  onStartEditing: PropTypes.func.isRequired,
  onUpdateDescription: PropTypes.func.isRequired,
  onCancelEditing: PropTypes.func.isRequired,
  setEditingDescription: PropTypes.func.isRequired
};

export default SourceRow;

// Helper function to format delimiter label
export const getDelimiterLabel = (delimiter) => {
  if (delimiter === ',') return 'comma (,)';
  if (delimiter === ';') return 'semicolon (;)';
  return `"${delimiter}"`;
};

/* Dropdown toggle text color */
.custom-nav-dropdown .dropdown-toggle { color: white !important; }
.user-nav-dropdown .dropdown-toggle { color: white !important; }

/* Consistent toggle height and alignment */
.custom-nav-dropdown .dropdown-toggle,
.user-nav-dropdown .dropdown-toggle { display: inline-flex; align-items: center; height: 36px; padding: 0 0.5rem; font-weight: 500; }

/* Hover/active state for dropdown toggles */
.custom-nav-dropdown .dropdown-toggle:hover,
.custom-nav-dropdown.show .dropdown-toggle,
.user-nav-dropdown .dropdown-toggle:hover,
.user-nav-dropdown.show .dropdown-toggle { background-color: #112533 !important; color: #ffffff !important; box-shadow: 0 0 0 1px #ffffff !important; border-radius: 0 !important; outline: none !important; }

/* Background and border colors */
.custom-nav-dropdown .dropdown-menu,
.user-nav-dropdown .dropdown-menu { background-color: #112533 !important; border: 1px solid #000000; border-radius: 4px; box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12); }

/* Items color */
.custom-nav-dropdown .dropdown-item,
.user-nav-dropdown .dropdown-item { font-size: 0.9rem; color: #ffffff !important; background-color: #112533 !important; transition: background-color 0.15s ease-in-out, color 0.15s ease-in-out; font-weight: 500; }

.custom-nav-dropdown .dropdown-item:hover,
.custom-nav-dropdown .dropdown-item:focus,
.user-nav-dropdown .dropdown-item:hover,
.user-nav-dropdown .dropdown-item:focus { background-color: #4F5E69 !important; color: #ffffff !important; }

/* Danger color */
.custom-nav-dropdown .dropdown-item.text-danger,
.custom-nav-dropdown .dropdown-item.text-danger:hover,
.custom-nav-dropdown .dropdown-item.text-danger:focus,
.user-nav-dropdown .dropdown-item.text-danger,
.user-nav-dropdown .dropdown-item.text-danger:hover,
.user-nav-dropdown .dropdown-item.text-danger:focus { color: #dc3545; }

/* Remove dividers and item separators */
.custom-nav-dropdown .dropdown-divider,
.user-nav-dropdown .dropdown-divider { display: none !important; border: 0 !important; margin: 0 !important; padding: 0 !important; }
.custom-nav-dropdown .dropdown-item + .dropdown-item,
.user-nav-dropdown .dropdown-item + .dropdown-item { border-top: 0 !important; }

/* User avatar dropdown */
.user-nav-dropdown .dropdown-toggle { padding: 0 0.25rem; }
.user-dropdown-toggle { display: inline-flex; align-items: center; }
.user-avatar { width: 16px; height: 16px; border-radius: 50%; border: 1px solid #adb5bd; background: #fff; }

/* Brand ask text */
.brand-ask { 
  text-transform: uppercase; 
  font-weight: 500;
  font-size: 1.15rem;
  letter-spacing: 0.02em; 
}

.brand-spacing {
  padding-bottom: 17px !important;
}

/* Header background image layer */
.background-header { position: absolute; top: 0; left: 0; height: 70px; width: 100%; background-size: cover; background-repeat: no-repeat; background-position: center; z-index: 1029; pointer-events: none; }
.navbar-transparent {
  height: 70px;
  background-color: transparent !important;
}
.navbar-transparent .navbar-nav .nav-link, .navbar-transparent .navbar-brand, .navbar-transparent .dropdown-toggle { color: #fff !important; }

import React, { useState, useRef } from "react";
import PropTypes from 'prop-types';
import Container from "react-bootstrap/Container";
import Navbar from "react-bootstrap/Navbar";
import Button from "react-bootstrap/Button";
import Badge from "react-bootstrap/Badge";
import Nav from 'react-bootstrap/Nav';
import NavDropdown from 'react-bootstrap/NavDropdown';
import VectorDBSyncModal from './VectorDBSyncModal';
import SettingsModal from './SettingsModal';
import ProfileModal from './ProfileModal';
import CSVManagerModal from './CSVManagerModal/CSVManagerModal';
import SkillsManagerModal from './SkillsManagerModal/SkillsManagerModal';
import { useReport } from '../../contexts/ReportContext';
import { useConfig } from '../../contexts/ConfigContext';
import api from "../../api/client";
import './Header.css';

const assetBaseUrl = import.meta.env.BASE_URL;

const Header = ({ 
  isAuthenticated, 
  setIsAuthenticated, 
  handleClearResults, 
  onOpenCSVManager,
  showCSVManager,
  setShowCSVManager,
  renderLogo,
  showBrandAsk = true,
  syncedResources,
  userSyncPermissions,
  onResourcesUpdate,
  hasActiveConversation = false,
  toggleSidebar,
  isSidebarOpen,
  selectedChatbot,
  globalEnabled = false,
  onSettingsApplied,
  isSwitchingAgent
}) => {
  const [showVectorDBSync, setShowVectorDBSync] = useState(false);
  const [showSkillsManager, setShowSkillsManager] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [showToolsDropdown, setShowToolsDropdown] = useState(false);
  const [showAdminDropdown, setShowAdminDropdown] = useState(false);
  const [showUserDropdown, setShowUserDropdown] = useState(false);
  const { config } = useConfig();
  const { reports, setIsModalOpen } = useReport();

  // Hover-delay timers for dropdowns
  const toolsTimerRef = useRef(null);
  const adminTimerRef = useRef(null);
  const userTimerRef = useRef(null);
  const HOVER_DELAY_MS = 100;

  const isWelcomeScreen = !selectedChatbot;
  const isGlobalChat = selectedChatbot && selectedChatbot.isGlobal;
  const isSpecializedChat = selectedChatbot && !selectedChatbot.isGlobal;

  const canShowAdvancedOptions = (globalEnabled && (isWelcomeScreen || isGlobalChat)) || isSpecializedChat;

  const showDeepQuery = canShowAdvancedOptions && config.enable_deep_query;
  const showKnowledgeBase = canShowAdvancedOptions && config.unstructured_mode;
  const showSkills = canShowAdvancedOptions;

  const showVectorDBManager = config.allow_sync && (globalEnabled && (isWelcomeScreen || isGlobalChat)) && (config.has_ai_sdk_credentials || userSyncPermissions);

  const hasToolsItems = showDeepQuery || showKnowledgeBase || showSkills || showVectorDBManager;
  const showToolsMenu = hasToolsItems;

  const canEditLLM = canShowAdvancedOptions && config.user_edit_llm;
  const canEditInstructions = canShowAdvancedOptions && config.can_edit_instructions;
  const showAdminMenu = !isWelcomeScreen && (canEditLLM || canEditInstructions);

  const clearTimer = (ref) => {
    if (ref.current) {
      clearTimeout(ref.current);
      ref.current = null;
    }
  };

  const closeAllNow = () => {
    clearTimer(toolsTimerRef);
    clearTimer(adminTimerRef);
    clearTimer(userTimerRef);
    setShowToolsDropdown(false);
    setShowAdminDropdown(false);
    setShowUserDropdown(false);
  };

  const handleEnterWhich = (which) => {
    if (isSwitchingAgent) return;
    clearTimer(toolsTimerRef);
    clearTimer(adminTimerRef);
    clearTimer(userTimerRef);
    if (which === 'tools') {
      setShowToolsDropdown(true);
      setShowAdminDropdown(false);
      setShowUserDropdown(false);
    } else if (which === 'admin') {
      setShowAdminDropdown(true);
      setShowToolsDropdown(false);
      setShowUserDropdown(false);
    } else {
      setShowUserDropdown(true);
      setShowToolsDropdown(false);
      setShowAdminDropdown(false);
    }
  };

  const handleLeaveWhich = (which) => {
    if (isSwitchingAgent) return;
    if (which === 'tools') {
      clearTimer(toolsTimerRef);
      toolsTimerRef.current = setTimeout(() => setShowToolsDropdown(false), HOVER_DELAY_MS);
    } else if (which === 'admin') {
      clearTimer(adminTimerRef);
      adminTimerRef.current = setTimeout(() => setShowAdminDropdown(false), HOVER_DELAY_MS);
    } else {
      clearTimer(userTimerRef);
      userTimerRef.current = setTimeout(() => setShowUserDropdown(false), HOVER_DELAY_MS);
    }
  };

  const handleToggleWhich = (which, isOpen) => {
    if (isSwitchingAgent) return;
    closeAllNow();
    if (!isOpen) return;
    if (which === 'tools') setShowToolsDropdown(true);
    else if (which === 'admin') setShowAdminDropdown(true);
    else setShowUserDropdown(true);
  };

  const handleLogout = async () => {
    try {
      await api.post("logout");
      handleClearResults();
      setIsAuthenticated(false);
    } catch (error) {
      console.error("Logout error:", error);
      alert("An error occurred during logout. Please try again.");
    }
  };

  const getBadgeProps = () => {
    // Default if no reports exist
    if (!reports || reports.length === 0) {
      return { bg: 'warning', text: 'dark' };
    }

    // Check the LAST report in the array
    const lastReport = reports[reports.length - 1];
    const status = lastReport?.status;

    if (status === 'completed') {
      return { bg: 'success', text: 'white' };
    } else if (status === 'failed') {
      return { bg: 'danger', text: 'white' }; 
    } else {
      return { bg: 'warning', text: 'dark' };
    }
  };

  const badgeProps = getBadgeProps();

  const agentName = selectedChatbot ? (selectedChatbot.isGlobal ? 'General Chat' : selectedChatbot.name) : 'General Chat';
  const settingsTitle = agentName.length > 20 ? 'Custom Agent Settings' : `${agentName} Settings`;

  return (
    <>
      <div 
        style={{
          backgroundImage: `url(${assetBaseUrl}header/header_background.png)`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat',
          width: '100%',
          boxShadow: '0 2px 4px rgba(0,0,0,0.08)'
        }}
      >
        <Navbar className="navbar-transparent position-relative" data-bs-theme="dark" style={{ height: '76px' }}>
          <Container fluid className="d-flex justify-content-between align-items-center">
            <div className="d-flex align-items-center flex-grow-1">
              {isAuthenticated && (
                <Button
                  variant="link"
                  onClick={toggleSidebar}
                  className="text-light p-0 me-3 d-flex align-items-center justify-content-center"
                  style={{
                    textDecoration: 'none',
                    border: 'none',
                    visibility: isSidebarOpen ? 'hidden' : 'visible',
                    pointerEvents: isSidebarOpen ? 'none' : 'auto',
                    opacity: isSwitchingAgent ? 0.5 : 1
                  }}
                  disabled={isSwitchingAgent}
                  title="Open sidebar"
                >
                  <i className="bi bi-list" style={{ fontSize: '1.5rem', lineHeight: 1 }}></i>
                </Button>
              )}

              <Navbar.Brand className="text-nowrap d-flex align-items-baseline brand-spacing m-0 px-0" style={{ paddingBottom: '5px' }}>
                {renderLogo()}
                {showBrandAsk && (
                  <span className="brand-ask ms-2">ASK A QUESTION</span>
                )}
              </Navbar.Brand>
            </div>

            {isAuthenticated && selectedChatbot && !selectedChatbot.isGlobal && (
              <div className="position-absolute top-50 start-50 translate-middle d-none d-md-flex align-items-center justify-content-center" style={{ pointerEvents: 'none' }}>
                <span className="brand-ask text-light m-0 p-0" style={{ letterSpacing: '0.5px', lineHeight: 1 }}>
                  {selectedChatbot.name.toUpperCase()}
                </span>
              </div>
            )}

            <div>
              {isAuthenticated && (
                  <Nav className="align-items-center">

                    {showToolsMenu && (
                      <NavDropdown
                        title="Tools"
                        id="tools-nav-dropdown"
                        align="end"
                        className="custom-nav-dropdown"
                        show={showToolsDropdown}
                        onMouseEnter={() => handleEnterWhich('tools')}
                        onMouseLeave={() => handleLeaveWhich('tools')}
                        onToggle={(isOpen) => handleToggleWhich('tools', isOpen)}
                        disabled={isSwitchingAgent}
                        style={{ opacity: isSwitchingAgent ? 0.5 : 1, pointerEvents: isSwitchingAgent ? 'none' : 'auto' }}
                      >
                        {showDeepQuery && (
                          <NavDropdown.Item onClick={() => setIsModalOpen(true)}>
                            DeepQuery Reports
                            {reports.length > 0 && (
                              <Badge bg={badgeProps.bg} text={badgeProps.text} className="ms-2">
                                {reports.length}
                              </Badge>
                            )}
                          </NavDropdown.Item>
                        )}

                        {showKnowledgeBase && (
                          <NavDropdown.Item onClick={onOpenCSVManager}>Knowledge Base Manager</NavDropdown.Item>
                        )}

                        {showSkills && (
                          <NavDropdown.Item onClick={() => setShowSkillsManager(true)}>Skills Manager</NavDropdown.Item>
                        )}

                        {showVectorDBManager && (
                          <NavDropdown.Item onClick={() => setShowVectorDBSync(true)}>Vector DB Manager</NavDropdown.Item>
                        )}
                      </NavDropdown>
                    )}

                  {showAdminMenu && (
                    <NavDropdown
                      title="Administration"
                      id="admin-nav-dropdown"
                      align="end"
                      className="custom-nav-dropdown"
                      show={showAdminDropdown}
                      onMouseEnter={() => handleEnterWhich('admin')}
                      onMouseLeave={() => handleLeaveWhich('admin')}
                      onToggle={(isOpen) => handleToggleWhich('admin', isOpen)}
                      disabled={isSwitchingAgent}
                      style={{ opacity: isSwitchingAgent ? 0.5 : 1, pointerEvents: isSwitchingAgent ? 'none' : 'auto' }}
                    >
                      <NavDropdown.Item onClick={() => setShowSettings(true)}>
                        {settingsTitle}
                      </NavDropdown.Item>
                    </NavDropdown>
                  )}

                    <NavDropdown
                      id="user-nav-dropdown"
                      align="end"
                      className="user-nav-dropdown"
                      title={(<span className="user-dropdown-toggle"><img alt="User" src={`${assetBaseUrl}header/user.png`} className="user-avatar" /></span>)}
                      show={showUserDropdown}
                      onMouseEnter={() => handleEnterWhich('user')}
                      onMouseLeave={() => handleLeaveWhich('user')}
                      onToggle={(isOpen) => handleToggleWhich('user', isOpen)}
                      disabled={isSwitchingAgent}
                      style={{ opacity: isSwitchingAgent ? 0.5 : 1, pointerEvents: isSwitchingAgent ? 'none' : 'auto' }}
                    >
                      <NavDropdown.Item onClick={() => setShowProfile(true)}>Profile</NavDropdown.Item>
                      <NavDropdown.Divider />
                      <NavDropdown.Item onClick={handleLogout} className="text-danger">Logout</NavDropdown.Item>
                    </NavDropdown>
                  </Nav>
              )}
            </div>
          </Container>
        </Navbar>
      </div>

      <VectorDBSyncModal
        show={showVectorDBSync}
        handleClose={() => setShowVectorDBSync(false)}
        syncedResources={syncedResources} 
        onResourcesUpdate={onResourcesUpdate}
      />
      <SettingsModal
        show={showSettings}
        handleClose={() => setShowSettings(false)}
        selectedChatbot={selectedChatbot}
        onSettingsApplied={onSettingsApplied}
        title={settingsTitle} 
      />
      <ProfileModal
        show={showProfile}
        handleClose={() => setShowProfile(false)}
        selectedChatbot={selectedChatbot}
      />
      {showCSVManager !== undefined && (
        <CSVManagerModal
          show={showCSVManager}
          handleClose={() => setShowCSVManager(false)}
          hasActiveConversation={hasActiveConversation}
          selectedChatbot={selectedChatbot}
        />
      )}
      <SkillsManagerModal
        show={showSkillsManager}
        handleClose={() => setShowSkillsManager(false)}
        hasActiveConversation={hasActiveConversation}
        selectedChatbot={selectedChatbot}
      />

    </>
  );
};

Header.propTypes = {
  isAuthenticated: PropTypes.bool.isRequired,
  setIsAuthenticated: PropTypes.func.isRequired,
  handleClearResults: PropTypes.func.isRequired,
  onOpenCSVManager: PropTypes.func,
  showCSVManager: PropTypes.bool,
  setShowCSVManager: PropTypes.func,
  renderLogo: PropTypes.func.isRequired,
  showBrandAsk: PropTypes.bool,
  syncedResources: PropTypes.object,
  userSyncPermissions: PropTypes.bool,
  onResourcesUpdate: PropTypes.func,
  hasActiveConversation: PropTypes.bool,
  toggleSidebar: PropTypes.func,
  isSidebarOpen: PropTypes.bool,
  selectedChatbot: PropTypes.object,
  globalEnabled: PropTypes.bool,
  onSettingsApplied: PropTypes.func,
  isSwitchingAgent: PropTypes.bool
};

export default Header;

import React, { useState, useEffect } from 'react';
import Modal from 'react-bootstrap/Modal';
import Button from 'react-bootstrap/Button';
import Form from 'react-bootstrap/Form';
import Spinner from 'react-bootstrap/Spinner';
import api from '../../api/client';
import CustomTooltip from '../CustomTooltip/CustomTooltip';
import NotificationToast from '../NotificationToast/NotificationToast';

const ProfileModal = ({ 
  show, 
  handleClose,
  selectedChatbot 
}) => {
  const [userDetails, setUserDetails] = useState('');
  const [username, setUsername] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: '',
    variant: 'info',
    title: ''
  });

  const currentAgentKey = selectedChatbot ? (selectedChatbot.isGlobal ? 'global' : selectedChatbot.id) : 'global';

  useEffect(() => {
    if (show) {
      const currentUser = localStorage.getItem('current_user');
      if (!currentUser) return;

      setUsername(currentUser);

      const savedUserDetails = localStorage.getItem(`${currentUser}_user_details`) || '';
      setUserDetails(savedUserDetails);
    }
  }, [show]);

  const handleOnExited = () => {
    setIsLoading(false);
  };

  const showToast = (message, variant, title) => {
    setToastConfig({ show: true, message, variant, title, duration: 4000 });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const dictString = localStorage.getItem(`${username}_custom_instructions_dict`);
      let instructionsPayload = {};
      if (dictString) {
        try {
          instructionsPayload = JSON.parse(dictString);
        } catch (e) {}
      }

      const response = await api.post("update_custom_instructions", {
        custom_instructions: instructionsPayload,
        user_details: userDetails
      });

      if (response.status === 200) {
        localStorage.setItem(`${username}_user_details`, userDetails);
        showToast('Your user profile has been successfully updated.', 'success', 'Profile Saved');
        handleClose();
      }
    } catch (error) {
      console.error('Error updating profile:', error);
      showToast(error.response?.data?.error || 'An error occurred while updating your profile.', 'danger', 'Update Error');
      setIsLoading(false);
    }
  };

  return (
    <>
      <Modal show={show} onHide={handleClose} onExited={handleOnExited} centered>
        <Modal.Header closeButton data-bs-theme="light">
          <Modal.Title>User Profile</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form id="profile-form" onSubmit={handleSubmit}>
            <Form.Group controlId="formUsername" className="mb-3">
              <Form.Label>Username</Form.Label>
              <Form.Control
                type="text"
                readOnly
                value={username}
                placeholder="Loading username..."
              />
            </Form.Group>

            <Form.Group controlId="formUserDetails" className="mb-3">
              <Form.Label className="d-flex align-items-center">
                What should the agents know about you?
                <CustomTooltip 
                  id="tooltip-user-details" 
                  content="This information is sent to the agent to personalize the conversation. For example, you could ask about how many clients you have if your email was included in this field."
                >
                  <i 
                    className="bi bi-info-circle ms-2" 
                    style={{ cursor: 'help', fontSize: '0.85rem', color: '#adb5bd', transition: 'color 0.2s' }}
                    onMouseEnter={(e) => e.target.style.color = '#112533'}
                    onMouseLeave={(e) => e.target.style.color = '#adb5bd'}
                  ></i>
                </CustomTooltip>
              </Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                placeholder="Example: My name is Matthew Richardson, I'm a loan officer and my email is matthew.richardson@example.com"
                value={userDetails}
                onChange={(e) => setUserDetails(e.target.value)}
              />
            </Form.Group>
          </Form>
        </Modal.Body>

        <Modal.Footer>
          <Button variant="light" onClick={handleClose} disabled={isLoading}>
            Cancel
          </Button>
          <Button 
            variant="dark" 
            type="submit" 
            form="profile-form"
            disabled={isLoading}
          >
              {isLoading ? (
                <>
                  <Spinner
                    as="span"
                    animation="border"
                    size="sm"
                    role="status"
                    aria-hidden="true"
                  />
                  <span className="ms-2">Updating...</span>
                </>
              ) : (
                'Save Profile'
              )}
          </Button>
        </Modal.Footer>
      </Modal>

      <NotificationToast
        show={toastConfig.show}
        message={toastConfig.message}
        variant={toastConfig.variant}
        title={toastConfig.title}
        duration={toastConfig.duration}
        onClose={() => setToastConfig(prev => ({...prev, show: false}))}
      />
    </>
  );
};

export default ProfileModal;

import React from "react";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import Table from "react-bootstrap/Table";
import Badge from "react-bootstrap/Badge";
import Spinner from "react-bootstrap/Spinner";
import OverlayTrigger from "react-bootstrap/OverlayTrigger";
import Tooltip from "react-bootstrap/Tooltip";
import { useReport, REPORT_STATUS } from "../../contexts/ReportContext";

const ReportManagementModal = () => {
  const { reports, isModalOpen, setIsModalOpen, removeReport, clearAllReports } = useReport();

  const getStatusBadge = (status) => {
    switch (status) {
      case REPORT_STATUS.PENDING:
        return <Badge bg="secondary">Pending</Badge>;
      case REPORT_STATUS.PROCESSING:
        return (
          <Badge bg="warning" text="dark" className="d-flex align-items-center">
            <Spinner size="sm" animation="border" className="me-1" />
            Processing
          </Badge>
        );
      case REPORT_STATUS.COMPLETED:
        return <Badge bg="success">Completed</Badge>;
      case REPORT_STATUS.FAILED:
        return <Badge bg="danger">Failed</Badge>;
      default:
        return <Badge bg="secondary">Unknown</Badge>;
    }
  };

  const formatDate = (date) => {
    return new Date(date).toLocaleString(undefined, {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: 'numeric',
      minute: '2-digit',
    });
  };

  const handleDownload = (report) => {
    if (report.downloadUrl) {
      const link = document.createElement('a');
      link.href = report.downloadUrl;
      const defaultFilename = report.reportTitle 
        ? `${report.reportTitle.replace(/[^a-z0-9]/gi, '_').toLowerCase()}_report.html`
        : `${report.id}_report.html`;
      link.download = report.filename || defaultFilename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  const handleClose = () => {
    setIsModalOpen(false);
  };

  const renderTooltip = (content) => (
    <Tooltip>{content}</Tooltip>
  );

  return (
    <Modal 
      show={isModalOpen} 
      onHide={handleClose} 
      size="xl" 
      centered
    >
      <Modal.Header closeButton data-bs-theme="light">
        <Modal.Title>DeepQuery Reports</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        {reports.length === 0 ? (
          <div className="text-center py-4">
            <p>No reports generated yet. Use DeepQuery to generate a report.</p>
          </div>
        ) : (
          <>
            <div className="d-flex justify-content-between align-items-center mb-3">
              <h6 className="mb-0">
                Total: {reports.length} report{reports.length !== 1 ? 's' : ''}
              </h6>
              {reports.length > 0 && (
                <Button 
                  variant="outline-danger" 
                  size="sm"
                  onClick={clearAllReports}
                >
                  Clear All
                </Button>
              )}
            </div>

            <Table striped bordered hover variant="light" className="table-responsive">
              <thead>
                <tr>
                  <th style={{ width: '40%' }}>Report Title</th>
                  <th style={{ width: '15%' }}>Status</th>
                  <th style={{ width: '15%' }}>Requested</th>
                  <th style={{ width: '15%' }}>Generated</th>
                  <th style={{ width: '15%' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {reports.map((report) => (
                  <tr key={report.id}>
                    <td>
                      <div style={{ maxWidth: '500px' }}>
                        <OverlayTrigger
                          placement="top"
                          overlay={renderTooltip(report.reportTitle || report.question)}
                        >
                          <span className="text-truncate d-block">
                            {report.reportTitle || report.question}
                          </span>
                        </OverlayTrigger>
                      </div>
                    </td>
                    <td>
                      {getStatusBadge(report.status)}
                      {report.error && (
                        <OverlayTrigger
                          placement="top"
                          overlay={renderTooltip(report.error)}
                        >
                          <i className="bi bi-exclamation-triangle-fill text-warning ms-2"></i>
                        </OverlayTrigger>
                      )}
                    </td>
                    <td>
                      <small>{formatDate(report.createdAt)}</small>
                    </td>
                    <td>
                      <small>
                        {report.completedAt ? formatDate(report.completedAt) : '-'}
                      </small>
                    </td>
                    <td>
                      <div className="d-flex gap-1">
                        {report.status === REPORT_STATUS.COMPLETED && (
                          <OverlayTrigger
                            placement="top"
                            overlay={renderTooltip("Download report")}
                          >
                            <Button
                              variant="success"
                              size="sm"
                              onClick={() => handleDownload(report)}
                            >
                              <i className="bi bi-download"></i>
                            </Button>
                          </OverlayTrigger>
                        )}
                        <OverlayTrigger
                          placement="top"
                          overlay={renderTooltip("Remove from list")}
                        >
                          <Button
                            variant="outline-danger"
                            size="sm"
                            onClick={() => removeReport(report.id)}
                          >
                            <i className="bi bi-trash"></i>
                          </Button>
                        </OverlayTrigger>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>

            <div className="mt-3">
              <small className="text-muted">
                <strong>Note:</strong> Reports are generated asynchronously and will be available for download once completed.
                Failed reports can be removed from the list.
              </small>
            </div>
          </>
        )}
      </Modal.Body>
      <Modal.Footer>
        <Button variant="light" onClick={handleClose}>
          Close
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default ReportManagementModal;

import React, { useState, useEffect } from "react";
import PropTypes from "prop-types";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import Form from "react-bootstrap/Form";
import Alert from "react-bootstrap/Alert";
import Spinner from "react-bootstrap/Spinner";
import Tabs from "react-bootstrap/Tabs";
import Tab from "react-bootstrap/Tab";
import NotificationToast from "../NotificationToast/NotificationToast";
import CustomTooltip from "../CustomTooltip/CustomTooltip";
import { useConfig } from "../../contexts/ConfigContext";
import api from "../../api/client";

const assetBaseUrl = import.meta.env.BASE_URL;

export const AI_SDK_STORAGE_KEY = "ai_sdk_llm_settings";
export const CHATBOT_STORAGE_KEY = "chatbot_llm_settings";

export const getDict = (username, dictName) => {
  try {
    const stored = localStorage.getItem(`${username}_${dictName}`);
    return stored ? JSON.parse(stored) : {};
  } catch {
    return {};
  }
};

export const saveDict = (username, dictName, dict) => {
  try {
    localStorage.setItem(`${username}_${dictName}`, JSON.stringify(dict));
  } catch (e) {
    console.error(`Error saving ${dictName}:`, e);
  }
};

const readInstructionEntry = (dict, key) => {
  const raw = dict[key];
  if (!raw) return { ai_sdk: "", chatbot: "" };
  if (typeof raw === "string") return { ai_sdk: raw, chatbot: "" };
  return {
    ai_sdk: raw.ai_sdk || "",
    chatbot: raw.chatbot || "",
  };
};

/** Map API/YAML provider string to the option value from valid_providers (case-insensitive). */
const canonicalProviderForSelect = (provider, validProviders) => {
  if (!provider || !validProviders?.length) return provider || "";
  const match = validProviders.find(
    (p) => p.toLowerCase() === String(provider).toLowerCase(),
  );
  if (match === undefined) return provider;
  return match;
};

const SettingsModal = ({
  show,
  handleClose,
  selectedChatbot,
  onSettingsApplied,
  title,
}) => {
  const [activeTab, setActiveTab] = useState("info");
  const [isLoading, setIsLoading] = useState(false);
  const [isFetching, setIsFetching] = useState(false);

  const { config } = useConfig();

  const [validProviders, setValidProviders] = useState([]);
  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: "",
    variant: "info",
    title: "Notification",
    duration: 5000,
  });

  const [chatbotInstructions, setChatbotInstructions] = useState("");
  const [aiSdkUserInstructions, setAiSdkUserInstructions] = useState("");

  const [aiSDKBaseLLM, setAISDKBaseLLM] = useState({
    provider: "",
    model: "",
    temperature: "",
    max_tokens: "",
  });
  const [aiSDKThinkingLLM, setAISDKThinkingLLM] = useState({
    provider: "",
    model: "",
    temperature: "",
    max_tokens: "",
  });
  const [useBaseLLMForExecution, setUseBaseLLMForExecution] = useState(false);
  const [checkAmbiguity, setCheckAmbiguity] = useState(true);
  const [isCustomBaseProvider, setIsCustomBaseProvider] = useState(false);
  const [isCustomThinkingProvider, setIsCustomThinkingProvider] =
    useState(false);
  const [sdkDefaults, setSdkDefaults] = useState({ base: {}, thinking: {} });
  const [sdkDeepQueryEnabled, setSdkDeepQueryEnabled] = useState(false);

  const [chatbotLLM, setChatbotLLM] = useState({
    provider: "",
    model: "",
    temperature: "",
    max_tokens: "",
  });
  const [isCustomChatbotProvider, setIsCustomChatbotProvider] = useState(false);
  const [chatbotDefaults, setChatbotDefaults] = useState({});
  const [chatbotDeepQueryEnabled, setChatbotDeepQueryEnabled] = useState(false);
  const [defaultCustomInstructions, setDefaultCustomInstructions] = useState({
    chatbot: "",
    ai_sdk: "",
  });

  const agentKey = selectedChatbot
    ? selectedChatbot.isGlobal
      ? "global"
      : selectedChatbot.id
    : "global";
  const isGlobalChat = selectedChatbot && selectedChatbot.isGlobal;

  const canEditLLM = config?.user_edit_llm;
  const canEditInstructions = config?.can_edit_instructions;

  const showToast = (message, variant, toastTitle, duration = 5000) => {
    toastConfig && setToastConfig({
      show: true,
      message,
      variant,
      title: toastTitle,
      duration,
    });
  };

  const handleToastClose = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  const handleOnExited = () => {
    setActiveTab("info");
    setIsLoading(false);
  };

  useEffect(() => {
    if (!show) return;

    const fetchSettings = async () => {
      setIsFetching(true);
      try {
        const response = await api.get("llm_settings");
        const data = response.data;

        const sdkInfo = data.ai_sdk_info || {};
        const providers = sdkInfo.valid_providers || [];

        const baseDefaults =
          Object.keys(data.ai_sdk_base_llm_defaults || {}).length > 0
            ? data.ai_sdk_base_llm_defaults
            : sdkInfo.base_llm || {};

        const thinkingDefaults =
          Object.keys(data.ai_sdk_thinking_llm_defaults || {}).length > 0
            ? data.ai_sdk_thinking_llm_defaults
            : sdkInfo.thinking_llm || {};

        const chatbotServerDefaults = data.chatbot_llm_defaults || {};

        const basePrefs = data.ai_sdk_base_llm_preferences || {};
        const thinkingPrefs = data.ai_sdk_thinking_llm_preferences || {};
        const chatbotPrefs = data.chatbot_llm_preferences || {};

        setValidProviders(providers);

        const hasThinkingModel =
          sdkInfo.thinking_llm != null ||
          Object.keys(data.ai_sdk_thinking_llm_defaults || {}).length > 0;
        setSdkDeepQueryEnabled(hasThinkingModel);
        setChatbotDeepQueryEnabled(data.chatbot_deepquery ?? false);
        setSdkDefaults({ base: baseDefaults, thinking: thinkingDefaults });
        setChatbotDefaults(chatbotServerDefaults);

        const effectiveBaseProvider = canonicalProviderForSelect(
          basePrefs.provider || baseDefaults.provider || "",
          providers,
        );
        const effectiveBaseSettings = {
          provider: effectiveBaseProvider,
          model: basePrefs.model || baseDefaults.model || "",
          temperature: basePrefs.temperature ?? baseDefaults.temperature ?? "",
          max_tokens: basePrefs.max_tokens || baseDefaults.max_tokens || "",
        };

        const effectiveThinkingProvider = canonicalProviderForSelect(
          thinkingPrefs.provider || thinkingDefaults.provider || "",
          providers,
        );
        const effectiveThinkingSettings = {
          provider: effectiveThinkingProvider,
          model: thinkingPrefs.model || thinkingDefaults.model || "",
          temperature:
            thinkingPrefs.temperature ?? thinkingDefaults.temperature ?? "",
          max_tokens:
            thinkingPrefs.max_tokens || thinkingDefaults.max_tokens || "",
        };

        const checkAmbVal =
          data.check_ambiguity ?? sdkInfo.check_ambiguity ?? true;

        const execModelFromData = data.use_base_llm_for_execution;
        const useBaseExecVal =
          execModelFromData !== null && execModelFromData !== undefined
            ? execModelFromData
            : sdkInfo.deepquery_execution_model === "base";

        const effectiveChatbotProvider = canonicalProviderForSelect(
          chatbotPrefs.provider || chatbotServerDefaults.provider || "",
          providers,
        );
        const effectiveChatbotSettings = {
          provider: effectiveChatbotProvider,
          model: chatbotPrefs.model || chatbotServerDefaults.model || "",
          temperature:
            chatbotPrefs.temperature ?? chatbotServerDefaults.temperature ?? "",
          max_tokens:
            chatbotPrefs.max_tokens || chatbotServerDefaults.max_tokens || "",
        };

        const defs = data.default_custom_instructions || {};
        setDefaultCustomInstructions({
          chatbot: defs.chatbot || "",
          ai_sdk: defs.ai_sdk || "",
        });
        const username = localStorage.getItem("current_user") || "";
        const customInstDict = username
          ? getDict(username, "custom_instructions_dict")
          : {};
        const hasStored =
          username &&
          Object.prototype.hasOwnProperty.call(customInstDict, agentKey);
        const entry = readInstructionEntry(customInstDict, agentKey);
        if (!hasStored) {
          setChatbotInstructions(entry.chatbot || defs.chatbot || "");
          setAiSdkUserInstructions(entry.ai_sdk || defs.ai_sdk || "");
        } else {
          setChatbotInstructions(entry.chatbot);
          setAiSdkUserInstructions(entry.ai_sdk);
        }

        if (username) {
          if (canEditLLM) {
            const aiSdkLlmDict = getDict(username, "ai_sdk_llm_settings_dict");
            aiSdkLlmDict[agentKey] = {
              ai_sdk_base_llm: effectiveBaseSettings,
              check_ambiguity: checkAmbVal,
              ...(hasThinkingModel &&
                data.chatbot_deepquery && {
                  ai_sdk_thinking_llm: effectiveThinkingSettings,
                  use_base_llm_for_execution: useBaseExecVal,
                }),
            };
            saveDict(username, "ai_sdk_llm_settings_dict", aiSdkLlmDict);

            const chatbotLlmDict = getDict(
              username,
              "chatbot_llm_settings_dict",
            );
            chatbotLlmDict[agentKey] = effectiveChatbotSettings;
            saveDict(username, "chatbot_llm_settings_dict", chatbotLlmDict);
          }
        }

        setAISDKBaseLLM(effectiveBaseSettings);
        setAISDKThinkingLLM(effectiveThinkingSettings);
        setChatbotLLM(effectiveChatbotSettings);
        setCheckAmbiguity(checkAmbVal);
        setUseBaseLLMForExecution(useBaseExecVal);

        const providersLower = new Set(providers.map((p) => p.toLowerCase()));
        setIsCustomBaseProvider(
          effectiveBaseProvider !== "" &&
            !providersLower.has(effectiveBaseProvider.toLowerCase()),
        );
        setIsCustomThinkingProvider(
          effectiveThinkingProvider !== "" &&
            !providersLower.has(effectiveThinkingProvider.toLowerCase()),
        );
        setIsCustomChatbotProvider(
          effectiveChatbotProvider !== "" &&
            !providersLower.has(effectiveChatbotProvider.toLowerCase()),
        );
      } catch (error) {
        console.error("Error fetching settings:", error);
      } finally {
        setIsFetching(false);
      }
    };

    fetchSettings();
  }, [show, agentKey, canEditInstructions, canEditLLM]);

  const validateTemperature = (temp) => {
    if (temp === "" || temp === null || temp === undefined) return true;
    const tempFloat = parseFloat(temp);
    return !isNaN(tempFloat) && tempFloat >= 0.0 && tempFloat <= 2.0;
  };

  const validateMaxTokens = (tokens) => {
    if (tokens === "" || tokens === null || tokens === undefined) return true;
    const tokensInt = parseInt(tokens);
    return !isNaN(tokensInt) && tokensInt >= 1024 && tokensInt <= 20000;
  };

  const deepQueryActive = sdkDeepQueryEnabled && chatbotDeepQueryEnabled;

  const validateForm = () => {
    if (!canEditLLM) return true;

    if (
      !validateTemperature(aiSDKBaseLLM.temperature) ||
      !validateTemperature(chatbotLLM.temperature)
    ) {
      showToast(
        "Temperature must be between 0.0 and 2.0",
        "warning",
        "Validation Error",
      );
      return false;
    }
    if (
      !validateMaxTokens(aiSDKBaseLLM.max_tokens) ||
      !validateMaxTokens(chatbotLLM.max_tokens)
    ) {
      showToast(
        "Max Output Tokens must be between 1024 and 20000",
        "warning",
        "Validation Error",
      );
      return false;
    }
    if (deepQueryActive) {
      if (!validateTemperature(aiSDKThinkingLLM.temperature)) {
        showToast(
          "AI SDK Thinking LLM Temperature must be between 0.0 and 2.0",
          "warning",
          "Validation Error",
        );
        return false;
      }
      if (!validateMaxTokens(aiSDKThinkingLLM.max_tokens)) {
        showToast(
          "AI SDK Thinking LLM Max Output Tokens must be between 1024 and 20000",
          "warning",
          "Validation Error",
        );
        return false;
      }
    }
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    setIsLoading(true);
    try {
      const username = localStorage.getItem("current_user") || "";

      if (username && canEditInstructions) {
        const userDetails =
          localStorage.getItem(`${username}_user_details`) || "";
        const customInstDict = getDict(username, "custom_instructions_dict");
        customInstDict[agentKey] = {
          ai_sdk: aiSdkUserInstructions,
          chatbot: chatbotInstructions,
        };
        await api.post("update_custom_instructions", {
          custom_instructions: customInstDict,
          user_details: userDetails,
        });

        saveDict(username, "custom_instructions_dict", customInstDict);
      }

      if (username && canEditLLM) {
        const payload = {
          ai_sdk_base_llm: aiSDKBaseLLM,
          check_ambiguity: checkAmbiguity,
          ...(deepQueryActive && {
            ai_sdk_thinking_llm: aiSDKThinkingLLM,
            use_base_llm_for_execution: useBaseLLMForExecution,
          }),
          chatbot_llm: chatbotLLM,
        };

        await api.post("update_llm_settings", payload);

        const aiSdkLlmDict = getDict(username, "ai_sdk_llm_settings_dict");
        aiSdkLlmDict[agentKey] = {
          ai_sdk_base_llm: aiSDKBaseLLM,
          check_ambiguity: checkAmbiguity,
          ...(deepQueryActive && {
            ai_sdk_thinking_llm: aiSDKThinkingLLM,
            use_base_llm_for_execution: useBaseLLMForExecution,
          }),
        };
        saveDict(username, "ai_sdk_llm_settings_dict", aiSdkLlmDict);

        const chatbotLlmDict = getDict(username, "chatbot_llm_settings_dict");
        chatbotLlmDict[agentKey] = chatbotLLM;
        saveDict(username, "chatbot_llm_settings_dict", chatbotLlmDict);
      }

      if (onSettingsApplied && selectedChatbot) {
        await onSettingsApplied(selectedChatbot);
      }

      showToast(
        "Settings updated successfully.",
        "success",
        "Settings Updated",
      );
      handleClose();
    } catch (error) {
      console.error("Error updating settings:", error);
      showToast(
        error.response?.data?.error ||
          "An error occurred while updating settings.",
        "danger",
        "Update Error",
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetToDefaults = async () => {
    setIsLoading(true);
    try {
      const response = await api.get("llm_settings");
      const data = response.data;
      const sdkInfo = data.ai_sdk_info || {};

      const baseDefaults =
        Object.keys(data.ai_sdk_base_llm_defaults || {}).length > 0
          ? data.ai_sdk_base_llm_defaults
          : sdkInfo.base_llm || {};

      const thinkingDefaults =
        Object.keys(data.ai_sdk_thinking_llm_defaults || {}).length > 0
          ? data.ai_sdk_thinking_llm_defaults
          : sdkInfo.thinking_llm || {};

      const chatbotServerDefaults = data.chatbot_llm_defaults || {};
      const providersLower = new Set(
        validProviders.map((p) => p.toLowerCase()),
      );

      const markCustom = (provider) =>
        provider !== "" && !providersLower.has(provider.toLowerCase());

      if (activeTab === "agent_llm") {
        const p = canonicalProviderForSelect(
          chatbotServerDefaults.provider || "",
          validProviders,
        );
        setChatbotLLM({
          provider: p,
          model: chatbotServerDefaults.model || "",
          temperature: chatbotServerDefaults.temperature ?? "",
          max_tokens: chatbotServerDefaults.max_tokens || "",
        });
        setIsCustomChatbotProvider(markCustom(p));
      } else if (activeTab === "ai_sdk") {
        const baseP = canonicalProviderForSelect(
          baseDefaults.provider || "",
          validProviders,
        );
        setAISDKBaseLLM({
          provider: baseP,
          model: baseDefaults.model || "",
          temperature: baseDefaults.temperature ?? "",
          max_tokens: baseDefaults.max_tokens || "",
        });
        setIsCustomBaseProvider(markCustom(baseP));

        const hasThinkingModel =
          sdkInfo.thinking_llm != null ||
          Object.keys(data.ai_sdk_thinking_llm_defaults || {}).length > 0;
        const deepQ = hasThinkingModel && (data.chatbot_deepquery ?? false);

        if (deepQ) {
          const thP = canonicalProviderForSelect(
            thinkingDefaults.provider || "",
            validProviders,
          );
          setAISDKThinkingLLM({
            provider: thP,
            model: thinkingDefaults.model || "",
            temperature: thinkingDefaults.temperature ?? "",
            max_tokens: thinkingDefaults.max_tokens || "",
          });
          setIsCustomThinkingProvider(markCustom(thP));
          const defExec = data.use_base_llm_for_execution_default;
          setUseBaseLLMForExecution(
            defExec !== null && defExec !== undefined
              ? defExec
              : sdkInfo.deepquery_execution_model === "base",
          );
        }

        const defAmb = data.check_ambiguity_default;
        setCheckAmbiguity(
          defAmb !== null && defAmb !== undefined ? defAmb : true,
        );

        const defs = data.default_custom_instructions || {};
        setDefaultCustomInstructions((prev) => ({
          ...prev,
          ai_sdk: defs.ai_sdk || "",
        }));
        setAiSdkUserInstructions(defs.ai_sdk || "");
      }

      showToast(
        activeTab === "ai_sdk"
          ? "AI SDK custom instructions, LLM options, and related settings restored to server defaults. Save to apply."
          : "LLM fields restored to server defaults. Save to apply.",
        "info",
        "Defaults restored",
      );
    } catch (error) {
      console.error("Error loading defaults:", error);
      showToast(
        error.response?.data?.error ||
          "Could not load default settings to restore the form.",
        "danger",
        "Reset Error",
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetGeneralDefaults = () => {
    setChatbotInstructions(defaultCustomInstructions.chatbot);
    showToast(
      "General (agent) instructions reset to server defaults. Save to apply.",
      "info",
      "Defaults restored",
    );
  };

  const handleProviderSelect = (value, setLLMState, setIsCustom) => {
    if (value === "__custom__") {
      setIsCustom(true);
      setLLMState((prev) => ({ ...prev, provider: "" }));
    } else {
      setIsCustom(false);
      setLLMState((prev) => ({ ...prev, provider: value }));
    }
  };

  const renderProviderField = (
    llmState,
    setLLMState,
    isCustom,
    setIsCustom,
  ) => {
    if (isCustom) {
      return (
        <div className="d-flex gap-1">
          <Form.Control
            size="sm"
            type="text"
            placeholder="Custom provider name"
            value={llmState.provider}
            onChange={(e) =>
              setLLMState((prev) => ({ ...prev, provider: e.target.value }))
            }
          />
          <Button
            size="sm"
            variant="outline-secondary"
            onClick={() => setIsCustom(false)}
            title="Switch back to provider list"
          >
            &#x2630;
          </Button>
        </div>
      );
    }
    return (
      <Form.Select
        size="sm"
        value={llmState.provider}
        onChange={(e) =>
          handleProviderSelect(e.target.value, setLLMState, setIsCustom)
        }
      >
        <option value="">Select provider...</option>
        {validProviders.map((p) => (
          <option key={p} value={p}>
            {p}
          </option>
        ))}
        <option value="__custom__">Custom...</option>
      </Form.Select>
    );
  };

  const renderLLMSection = (
    sectionTitle,
    llmState,
    setLLMState,
    isCustom,
    setIsCustom,
  ) => (
    <div className="mb-3">
      {sectionTitle && <h6 className="mb-2 small fw-bold">{sectionTitle}</h6>}
      <div className="row g-2">
        <div className="col-md-6">
          <Form.Group className="mb-2">
            <Form.Label className="small">Provider</Form.Label>
            {renderProviderField(llmState, setLLMState, isCustom, setIsCustom)}
          </Form.Group>
        </div>
        <div className="col-md-6">
          <Form.Group className="mb-2">
            <Form.Label className="small">Model</Form.Label>
            <Form.Control
              size="sm"
              type="text"
              placeholder="e.g., gpt-5.2-none, gemini-2.5-flash"
              value={llmState.model}
              onChange={(e) =>
                setLLMState((prev) => ({ ...prev, model: e.target.value }))
              }
            />
          </Form.Group>
        </div>
        <div className="col-md-6">
          <Form.Group className="mb-2">
            <Form.Label className="small">Temperature (0.0 - 2.0)</Form.Label>
            <Form.Control
              size="sm"
              type="number"
              step="0.1"
              min="0.0"
              max="2.0"
              placeholder="e.g., 0.7"
              value={llmState.temperature}
              onChange={(e) =>
                setLLMState((prev) => ({
                  ...prev,
                  temperature: e.target.value,
                }))
              }
            />
          </Form.Group>
        </div>
        <div className="col-md-6">
          <Form.Group className="mb-2">
            <Form.Label className="small">Max Output Tokens</Form.Label>
            <Form.Control
              size="sm"
              type="number"
              min="1024"
              max="20000"
              placeholder="e.g., 4096"
              value={llmState.max_tokens}
              onChange={(e) =>
                setLLMState((prev) => ({ ...prev, max_tokens: e.target.value }))
              }
            />
          </Form.Group>
        </div>
      </div>
    </div>
  );

  const showSDKWarning =
    (aiSDKBaseLLM.provider &&
      sdkDefaults.base?.provider &&
      aiSDKBaseLLM.provider.toLowerCase() !==
        sdkDefaults.base.provider.toLowerCase()) ||
    (deepQueryActive &&
      aiSDKThinkingLLM.provider &&
      sdkDefaults.thinking?.provider &&
      aiSDKThinkingLLM.provider.toLowerCase() !==
        sdkDefaults.thinking.provider.toLowerCase());

  const showChatbotWarning =
    chatbotLLM.provider &&
    chatbotDefaults.provider &&
    chatbotLLM.provider.toLowerCase() !==
      chatbotDefaults.provider.toLowerCase();

  const tooltipAiSdkInstructionsContent =
    "Only the data query path (e.g. data_search tool) uses this text as request custom_instructions. The AI SDK server appends it after CUSTOM_INSTRUCTIONS from sdk_config.env. The metadata search path does not use an LLM the same way.";

  if (!canEditLLM && !canEditInstructions) return null;

  return (
    <>
      <Modal
        show={show}
        onHide={handleClose}
        onExited={handleOnExited}
        size="lg"
        centered
      >
        <Modal.Header closeButton data-bs-theme="light">
          <Modal.Title>{title}</Modal.Title>
        </Modal.Header>
        <Modal.Body style={{ maxHeight: "70vh", overflowY: "auto" }}>
          <Alert variant="info" className="mb-3 py-2">
            <small>
              <strong>Note:</strong> Fields are pre-filled with the current
              configurations for this agent. Your settings are saved and will be
              restored on your next login. Changing the LLM settings mid-conversation 
              is supported, but starting a new chat is recommended for best results.
            </small>
          </Alert>

          {isFetching ? (
            <div className="text-center py-4">
              <Spinner animation="border" size="sm" />
              <span className="ms-2">Loading current settings...</span>
            </div>
          ) : (
            <Form id="combined-settings-form" onSubmit={handleSubmit}>
              <Tabs
                activeKey={activeTab}
                onSelect={(k) => setActiveTab(k)}
                className="mb-3"
              >
                <Tab eventKey="info" title="General">
                  <div className="mt-3">
                    <div
                      className="d-flex align-items-center p-3 mb-4 rounded"
                      style={{
                        backgroundColor: "#f8f9fa",
                        border: "1px solid #e9ecef",
                      }}
                    >
                      <div
                        className="me-3 rounded-circle d-flex justify-content-center align-items-center bg-white border"
                        style={{
                          width: "56px",
                          height: "56px",
                          flexShrink: 0,
                        }}
                      >
                        {isGlobalChat ? (
                          <img
                            src={`${assetBaseUrl}denodo_chat_transparent.png`}
                            alt="General Chat"
                            style={{
                              height: "32px",
                              width: "32px",
                              objectFit: "contain",
                            }}
                            onError={(e) => {
                              e.target.style.display = "none";
                              e.target.nextSibling.style.display =
                                "inline-block";
                            }}
                          />
                        ) : selectedChatbot?.icon ? (
                          <img
                            src={selectedChatbot.icon}
                            alt={selectedChatbot.name}
                            style={{
                              height: "32px",
                              width: "32px",
                              objectFit: "contain",
                            }}
                            onError={(e) => {
                              e.target.style.display = "none";
                              e.target.nextSibling.style.display =
                                "inline-block";
                            }}
                          />
                        ) : null}
                        <i
                          className={
                            isGlobalChat
                              ? "bi bi-chat-left-text"
                              : "bi bi-robot"
                          }
                          style={{
                            fontSize: "1.5rem",
                            color: "#143142",
                            display:
                              isGlobalChat || selectedChatbot?.icon
                                ? "none"
                                : "inline-block",
                          }}
                        ></i>
                      </div>
                      <div>
                        <h5 className="mb-1 fw-bold text-dark">
                          {selectedChatbot?.name || "General Chat"}
                        </h5>
                        <span
                          className="text-muted"
                          style={{ fontSize: "0.9rem" }}
                        >
                          {selectedChatbot?.description ||
                            "No description provided for this agent."}
                        </span>
                      </div>
                    </div>

                    {canEditInstructions && (
                      <Form.Group
                        controlId="formChatbotInstructions"
                        className="mb-3"
                      >

import React, { useState, useEffect, useCallback } from 'react';
import PropTypes from 'prop-types';
import Modal from 'react-bootstrap/Modal';
import Button from 'react-bootstrap/Button';
import Spinner from 'react-bootstrap/Spinner';
import Alert from 'react-bootstrap/Alert';
import Table from 'react-bootstrap/Table';
import Form from 'react-bootstrap/Form';
import Badge from 'react-bootstrap/Badge';
import api from '../../../api/client';
import NotificationToast from '../../NotificationToast/NotificationToast';

const emptyNewSkill = {
  skillName: '',
  content: ''
};

const SkillsManagerModal = ({ show, handleClose, hasActiveConversation = false, selectedChatbot }) => {
  const agentName = selectedChatbot?.name || 'General Chat';
  const [skills, setSkills] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newSkill, setNewSkill] = useState(emptyNewSkill);
  const [isAdding, setIsAdding] = useState(false);
  const [viewingSkill, setViewingSkill] = useState(null);
  const [viewingContent, setViewingContent] = useState('');
  const [isLoadingContent, setIsLoadingContent] = useState(false);
  const [deletingSkills, setDeletingSkills] = useState(() => new Set());

  // Tracks whether the user has made any change during this open-session of
  // the modal. Used to decide whether to warn on close that changes won't
  // apply to an ongoing conversation.
  const [hasChanges, setHasChanges] = useState(false);

  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: '',
    variant: 'info',
    title: '',
    duration: 8000,
  });

  const showToast = (message, variant, title, duration = 8000) => {
    setToastConfig({ show: true, message, variant, title, duration });
  };

  const handleToastClose = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  const notifySkillsChanged = useCallback(() => {
    setHasChanges(true);
  }, []);

  // Reset dirty/view state every time the modal is opened.
  useEffect(() => {
    if (show) {
      setHasChanges(false);
      setViewingSkill(null);
      setViewingContent('');
      setShowAddForm(false);
      setNewSkill(emptyNewSkill);
    }
  }, [show]);

  const requestClose = () => {
    if (hasChanges && hasActiveConversation) {
      showToast(
        "Changes saved. The agent may rely on previous context and ignore skill changes. Start a new chat to make sure they apply.",
        "info",
        "Skills updated",
        8000
      );
    }
    handleClose();
  };

  const fetchSkills = useCallback(async () => {
    if (!show) return;
    setIsLoading(true);
    setError(null);
    try {
      const response = await api.get('skills/list');
      if (response.data.success) {
        setSkills(response.data.skills || []);
      }
    } catch (err) {
      setError('Failed to load skills');
      console.error('Error fetching skills:', err);
    } finally {
      setIsLoading(false);
    }
  }, [show]);

  useEffect(() => { fetchSkills(); }, [fetchSkills]);

  const handleToggleActive = async (skillName, currentActive) => {
    try {
      const response = await api.post('skills/activate', { skill_name: skillName, active: !currentActive });
      if (response.data.success) {
        setSkills((prev) => prev.map((s) => s.skill_name === skillName ? { ...s, active: !currentActive } : s));
        notifySkillsChanged();
      }
    } catch (err) {
      setError(`Failed to toggle skill: ${err.response?.data?.error || err.message}`);
    }
  };

  const handleView = async (skillName) => {
    if (viewingSkill === skillName) {
      setViewingSkill(null);
      setViewingContent('');
      return;
    }
    setViewingSkill(skillName);
    setViewingContent('');
    setIsLoadingContent(true);
    try {
      const response = await api.get(`skills/read/${skillName}`);
      if (response.data.success) {
        setViewingContent(response.data.content || '');
      }
    } catch (err) {
      setError(`Failed to read skill: ${err.response?.data?.error || err.message}`);
      setViewingSkill(null);
    } finally {
      setIsLoadingContent(false);
    }
  };

  const handleDelete = async (skillName) => {
    if (deletingSkills.has(skillName)) return;
    if (!window.confirm(`Are you sure you want to delete your personal skill "${skillName}"?`)) return;
    setDeletingSkills((prev) => {
      const next = new Set(prev);
      next.add(skillName);
      return next;
    });
    try {
      const response = await api.delete(`skills/delete/${skillName}`);
      if (response.data.success) {
        setSkills((prev) => prev.filter((s) => s.skill_name !== skillName));
        if (viewingSkill === skillName) {
          setViewingSkill(null);
          setViewingContent('');
        }
        notifySkillsChanged();
      }
    } catch (err) {
      setError(`Failed to delete skill: ${err.response?.data?.error || err.message}`);
    } finally {
      setDeletingSkills((prev) => {
        const next = new Set(prev);
        next.delete(skillName);
        return next;
      });
    }
  };

  const handleAddSkill = async (e) => {
    e.preventDefault();
    const skillName = newSkill.skillName.trim();
    if (!skillName) { setError('Please provide a skill name'); return; }
    if (!/^[A-Za-z0-9_-]+$/.test(skillName)) {
      setError('Skill names may only contain letters, digits, hyphens and underscores');
      return;
    }
    if (!newSkill.content.trim()) { setError('Skill content cannot be empty'); return; }

    setIsAdding(true);
    setError(null);
    try {
      const response = await api.post('skills/create', {
        skill_name: skillName,
        content: newSkill.content
      });
      if (response.data.success) {
        await fetchSkills();
        setNewSkill(emptyNewSkill);
        setShowAddForm(false);
        notifySkillsChanged();
      }
    } catch (err) {
      setError(`Failed to create skill: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsAdding(false);
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.name.endsWith('.md') && !file.name.endsWith('.txt')) {
      setError('Please select a markdown (.md) or text (.txt) file');
      e.target.value = null;
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const suggestedName = file.name
        .replace(/\.(md|txt)$/i, '')
        .replace(/[^A-Za-z0-9_-]/g, '_');
      setNewSkill((prev) => ({
        skillName: prev.skillName || (suggestedName === 'SKILL' ? '' : suggestedName),
        content: String(reader.result || '')
      }));
    };
    reader.readAsText(file);
  };

  const handleCancelAddForm = () => {
    setShowAddForm(false);
    setNewSkill(emptyNewSkill);
  };

  return (
    <>
      <Modal show={show} onHide={requestClose} centered size="xl" dialogClassName="modal-90w">
        <Modal.Header closeButton data-bs-theme="light">
          <Modal.Title>Skills Manager</Modal.Title>
        </Modal.Header>
        <Modal.Body style={{ maxHeight: '70vh', overflowY: 'auto' }}>
          {error && (
            <Alert variant="danger" onClose={() => setError(null)} dismissible>
              {error}
            </Alert>
          )}

          <Alert variant="primary" className="mb-3 py-2">
            <small>
              <i className="bi bi-info-circle me-1" />
              Skills are reusable guidance the agent reads on demand while answering in <strong>{agentName}</strong>.
              <strong> System</strong> skills are shared with every user; <strong>Personal</strong> skills
              are yours only. <strong>Active</strong> toggles apply only to you — deactivated skills are
              not offered to the agent.
            </small>
          </Alert>

          {showAddForm ? (
            <Form onSubmit={handleAddSkill} className="border rounded p-3 mb-3 bg-light">
              <h6 className="mb-3">Add Personal Skill</h6>
              <Form.Group className="mb-3" controlId="skillName">
                <Form.Label>Skill name</Form.Label>
                <Form.Control
                  type="text"
                  placeholder="my_reporting_process"
                  value={newSkill.skillName}
                  onChange={(e) => setNewSkill((prev) => ({ ...prev, skillName: e.target.value }))}
                  disabled={isAdding}
                />
                <Form.Text muted>Letters, digits, hyphens and underscores only.</Form.Text>
              </Form.Group>
              <Form.Group className="mb-3" controlId="skillFile">
                <Form.Label>Upload a SKILL.md file (optional)</Form.Label>
                <Form.Control type="file" accept=".md,.txt" onChange={handleFileChange} disabled={isAdding} />
              </Form.Group>
              <Form.Group className="mb-3" controlId="skillContent">
                <Form.Label>Content</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={10}
                  placeholder={"---\nname: my_reporting_process\ndescription: One-line description the agent uses to decide when to read this skill.\n---\n\nStep-by-step guidance for the agent..."}
                  value={newSkill.content}
                  onChange={(e) => setNewSkill((prev) => ({ ...prev, content: e.target.value }))}
                  disabled={isAdding}
                  style={{ fontFamily: 'monospace', fontSize: '0.85rem' }}
                />
                <Form.Text muted>
                  Start with a YAML frontmatter block containing a one-line <code>description:</code> — the
                  agent uses it to decide when to read the skill.
                </Form.Text>
              </Form.Group>
              <div className="d-flex gap-2">
                <Button variant="dark" size="sm" type="submit" disabled={isAdding}>
                  {isAdding ? (<><Spinner animation="border" size="sm" className="me-1" />Adding...</>) : 'Add Skill'}
                </Button>
                <Button variant="outline-secondary" size="sm" onClick={handleCancelAddForm} disabled={isAdding}>
                  Cancel
                </Button>
              </div>
            </Form>
          ) : (
            <Button
              variant="outline-dark"
              size="sm"
              className="mb-3"
              onClick={() => setShowAddForm(true)}
            >
              + Add Personal Skill
            </Button>
          )}

          {isLoading && !showAddForm && (
            <div className="text-center p-4"><Spinner animation="border" /></div>
          )}

          {!isLoading && skills.length === 0 && (
            <Alert variant="warning">
              No skills available. Click "Add Personal Skill" to create one.
            </Alert>
          )}

          {!isLoading && skills.length > 0 && (
            <Table striped bordered hover size="sm" variant="light">
              <thead>
                <tr>
                  <th style={{ width: '70px' }}>Active</th>
                  <th style={{ width: '220px' }}>Name</th>
                  <th style={{ width: '100px' }}>Type</th>
                  <th>Description</th>
                  <th style={{ width: '160px' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {skills.map((skill) => (
                  <React.Fragment key={skill.skill_name}>
                    <tr>
                      <td className="text-center align-middle">
                        <Form.Check
                          type="switch"
                          id={`skill-active-${skill.skill_name}`}
                          checked={skill.active}
                          onChange={() => handleToggleActive(skill.skill_name, skill.active)}
                          title={skill.active ? 'Deactivate for you' : 'Activate for you'}
                        />
                      </td>
                      <td className="align-middle"><code>{skill.skill_name}</code></td>
                      <td className="align-middle">
                        {skill.scope === 'personal' ? (
                          <Badge bg="dark"><i className="bi bi-person-fill me-1" />Personal</Badge>
                        ) : (
                          <Badge bg="success"><i className="bi bi-globe2 me-1" />System</Badge>
                        )}
                      </td>
                      <td className="align-middle">
                        <small>{skill.description || <em className="text-muted">No description</em>}</small>
                        {skill.references && skill.references.length > 0 && (
                          <div>
                            <small className="text-muted">References: {skill.references.join(', ')}</small>
                          </div>
                        )}
                      </td>
                      <td className="align-middle">
                        <div className="d-flex gap-2">
                          <Button
                            variant="outline-secondary"
                            size="sm"
                            onClick={() => handleView(skill.skill_name)}
                            title="View skill content"
                          >
                            <i className={`bi ${viewingSkill === skill.skill_name ? 'bi-eye-slash' : 'bi-eye'}`} />
                          </Button>
                          {skill.scope === 'personal' && (
                            <Button
                              variant="outline-danger"
                              size="sm"
                              onClick={() => handleDelete(skill.skill_name)}
                              disabled={deletingSkills.has(skill.skill_name)}
                              title="Delete personal skill"
                            >
                              {deletingSkills.has(skill.skill_name)
                                ? <Spinner animation="border" size="sm" />
                                : <i className="bi bi-trash" />}
                            </Button>
                          )}
                        </div>
                      </td>
                    </tr>
                    {viewingSkill === skill.skill_name && (
                      <tr>
                        <td colSpan={5} className="bg-light">
                          {isLoadingContent ? (
                            <div className="text-center p-3"><Spinner animation="border" size="sm" /></div>
                          ) : (
                            <pre
                              className="mb-0 p-2"
                              style={{ whiteSpace: 'pre-wrap', fontSize: '0.8rem', maxHeight: '300px', overflowY: 'auto' }}
                            >
                              {viewingContent}
                            </pre>
                          )}
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </Table>
          )}

          <Alert variant="info" className="mb-3 py-2">
            <small>
              <strong>Note:</strong> System skills are provided by your administrator in the AI SDK <code>skills/</code> folder.
              You can also ask the chatbot to create or edit personal skills for you during a conversation.
            </small>
          </Alert>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="light" onClick={requestClose}>Close</Button>
        </Modal.Footer>
      </Modal>

      <NotificationToast
        show={toastConfig.show}
        message={toastConfig.message}
        variant={toastConfig.variant}
        title={toastConfig.title}
        duration={toastConfig.duration}
        onClose={handleToastClose}
      />
    </>
  );
};

SkillsManagerModal.propTypes = {
  show: PropTypes.bool.isRequired,
  handleClose: PropTypes.func.isRequired,
  hasActiveConversation: PropTypes.bool,
  selectedChatbot: PropTypes.object
};

export default SkillsManagerModal;

import React, { useState, useEffect } from 'react';
import { isAxiosError } from 'axios';
import Modal from 'react-bootstrap/Modal';
import Button from 'react-bootstrap/Button';
import Form from 'react-bootstrap/Form';
import Spinner from 'react-bootstrap/Spinner';
import Alert from 'react-bootstrap/Alert';
import Tabs from 'react-bootstrap/Tabs';
import Tab from 'react-bootstrap/Tab';
import ListGroup from 'react-bootstrap/ListGroup';
import api from '../../api/client';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import Tooltip from 'react-bootstrap/Tooltip';
import NotificationToast from "../NotificationToast/NotificationToast";

const formatTimestamp = (timestamp) => {
  if (!timestamp) return 'N/A';
  try {
    const date = new Date(timestamp);
    const options = {
      dateStyle: 'short',
      timeStyle: 'short'
    };
    return date.toLocaleString(undefined, options);
  } catch (error) {
    console.error('Error formatting timestamp:', error);
    return 'Invalid date';
  }
};

const VectorDBSyncModal = ({ show, handleClose, syncedResources, onResourcesUpdate }) => {
  // Common state
  const [activeTab, setActiveTab] = useState('status');
  const [isLoading, setIsLoading] = useState(false);
  const [statusData, setStatusData] = useState(syncedResources || {});

  // Toast State
  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: '',
    variant: 'info',
    title: '',
    duration: 5000
  });

  // Sync state
  const [syncVdbs, setSyncVdbs] = useState('');
  const [syncTags, setSyncTags] = useState('');
  const [ignoreTags, setIgnoreTags] = useState('');
  const [examplesPerTable, setExamplesPerTable] = useState(100);
  const [timeoutSeconds, setTimeoutSeconds] = useState(300);
  const [incremental, setIncremental] = useState(false);
  const [parallel, setParallel] = useState(true);

  // Delete state
  const [deleteVdbs, setDeleteVdbs] = useState('');
  const [deleteTags, setDeleteTags] = useState('');
  const [deleteConflicting, setDeleteConflicting] = useState(false);

  useEffect(() => {
    if (show) {
      if (!isLoading) {
        setStatusData(syncedResources || {});
      }
    }
  }, [show, syncedResources, isLoading]);

  const showToast = (message, variant, title, duration = 5000) => {
    setToastConfig({ show: true, message, variant, title, duration });
  };

  const handleToastClose = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  const checkResourcesAlreadyExist = (requestedVdbs, requestedTags) => {
    const existingVdbs = statusData?.DATABASE ? Object.keys(statusData.DATABASE) : [];
    const existingTags = statusData?.TAG ? Object.keys(statusData.TAG) : [];

    return requestedVdbs.some(vdb => existingVdbs.includes(vdb)) || 
           requestedTags.some(tag => existingTags.includes(tag));
  };

  const isTimeoutValid = timeoutSeconds !== '' && Number(timeoutSeconds) > 0;
  const isExamplesValid = examplesPerTable !== '' && Number(examplesPerTable) >= 0 && Number(examplesPerTable) <= 500;

  const handleSyncSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    const processedVdbs = syncVdbs.split(',').map(vdb => vdb.trim()).filter(vdb => vdb);
    const processedTags = syncTags.split(',').map(tag => tag.trim()).filter(tag => tag);
    const processedIgnoreTags = ignoreTags.split(',').map(tag => tag.trim()).filter(tag => tag);

    const finalTimeoutSeconds = parseInt(timeoutSeconds, 10) || 300;
    const axiosTimeoutMs = finalTimeoutSeconds * 1000;

    try {
      const response = await api.post("sync_vdbs", {
        vdbs: processedVdbs,
        tags: processedTags,
        tags_to_ignore: processedIgnoreTags,
        examples_per_table: examplesPerTable,
        timeout_seconds: finalTimeoutSeconds,
        incremental,
        parallel
      }, {
        timeout: axiosTimeoutMs
      });

      if (response.status === 204) {
        if (incremental) {
            const existsLocally = checkResourcesAlreadyExist(processedVdbs, processedTags);
            if (existsLocally) {
                showToast(
                    "You made an incremental request, but no updates have been made to the desired data since the last sync.",
                    "warning",
                    "No updates",
                    10000
                );
            } else {
                showToast(
                    "The selected databases/tags were not found in the Data Marketplace.",
                    "danger",
                    "Not found"
                );
            }
        } else {
            showToast(
                "The selected databases/tags were not found in the Data Marketplace.",
                "danger",
                "Not found"
            );
        }
      } else {
        const errors = response.data.dataUsageErrors || [];

        // extract timings
        let timingsMsg = "";

        if (Array.isArray(response.data.timings) && response.data.timings.length > 0) {
          const aggregatedTimings = {};

          response.data.timings.forEach(timingObj => {
            Object.entries(timingObj).forEach(([key, value]) => {
              if (typeof value === 'number') {
                aggregatedTimings[key] = (aggregatedTimings[key] || 0) + value;
              }
            });
          });

          if (Object.keys(aggregatedTimings).length > 0) {
            timingsMsg += "\n\nTiming Breakdown (Aggregate):";

            const keyOrder = [
              'metadata_retrieval',
              'vector_store_deletion',
              'metadata_processing',
              'vector_store_embedding',
              'sample_data_processing',
              'total_execution_time'
            ];

            const sortedKeys = Object.keys(aggregatedTimings).sort((a, b) => {
              const indexA = keyOrder.indexOf(a);
              const indexB = keyOrder.indexOf(b);
              if (indexA === -1 && indexB === -1) return a.localeCompare(b);
              if (indexA === -1) return 1;
              if (indexB === -1) return -1;
              return indexA - indexB;
            });

            sortedKeys.forEach(key => {
              const formattedKey = key.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
              timingsMsg += `\n• ${formattedKey}: ${Number(aggregatedTimings[key]).toFixed(2)}s`;
            });
          }
        } else if (response.data.timings && typeof response.data.timings === 'object' && !Array.isArray(response.data.timings)) {
          timingsMsg += "\n\nTiming Breakdown:";
          Object.entries(response.data.timings).forEach(([key, value]) => {
            const formattedKey = key.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
            timingsMsg += `\n• ${formattedKey}: ${Number(value).toFixed(2)}s`;
          });
        }

        // append timings to toast
        if (errors.length > 0) {
          const formatError = (errObj) => {
            const msg = errObj.cause || 'Unknown error';

            if (errObj.databaseName && errObj.viewName) {
              const fieldInfo = errObj.fieldName ? `.${errObj.fieldName}` : '';
              return `• [${errObj.databaseName}.${errObj.viewName}${fieldInfo}] ${msg}`;
            }
            return `• ${msg}`;
          };

          const errorList = errors.slice(0, 3).map(formatError).join('\n');
          const moreErrors = errors.length > 3 ? `\n...and ${errors.length - 3} more.` : '';

          showToast(
              `Sync completed, but with ${errors.length} warning(s):\n${errorList}${moreErrors}${timingsMsg}`,
              'warning',
              'Sync completed with warnings',
              30000
          );
        } else {
          let successMsg = response.data.message || "Synchronization successful.";
          successMsg += timingsMsg;

          if (response.data) {
            if (response.data.syncedResources) {
              setStatusData(response.data.syncedResources);
            }

            if (onResourcesUpdate) {
              onResourcesUpdate(response.data);
            }
          }

          showToast(successMsg, 'success', 'Sync completed', 15000);
        }
      }

    } catch (error) {
      let errorMsg = 'An error occurred during synchronization.';
      if (isAxiosError(error) && error.code === 'ECONNABORTED') {
        errorMsg = `The synchronization timeout has been exceeded (${finalTimeoutSeconds} seconds). The request was cancelled before completion. It is recommended to synchronize again to ensure no metadata is missing.`;
      } else {
        errorMsg = error.response?.data?.message || errorMsg;
      }
      const toastTitle = isAxiosError(error) && error.code === 'ECONNABORTED' ? 'Sync Timeout' : 'Sync Error';
      showToast(errorMsg, 'danger', toastTitle, 10000);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const response = await api.delete("delete_metadata", {
        data: {
          vdp_database_names: deleteVdbs,
          vdp_tag_names: deleteTags,
          delete_conflicting: deleteConflicting
        }
      });

      if (response.status === 204) {
          showToast(
            "No metadata found matching the specified criteria for deletion.",
            'warning',
            'No content'
          );
      } else {
          const successMsg = response.data.message || "Deletion successful.";
          showToast(successMsg, 'success', 'Deletion completed');

          if (response.data) {
            if (response.data.syncedResources) {
              setStatusData(response.data.syncedResources);
            }

            if (onResourcesUpdate) {
              onResourcesUpdate(response.data);
            }
          }
      }

    } catch (error) {
      const errorMsg = error.response?.data?.message || 'An error occurred during deletion.';
      showToast(errorMsg, 'danger', 'Delete error');
    } finally {
      setIsLoading(false);
    }
  };

  const renderResourceList = (resources) => {
    if (!resources || Object.keys(resources).length === 0) {
      return null;
    }
    return (
      <>
        {Object.entries(resources).map(([name, timestamp]) => (
          <ListGroup.Item key={name} className="d-flex justify-content-between align-items-center gap-3">
            <OverlayTrigger
              placement="top"
              delay={{ show: 250, hide: 400 }}
              overlay={
                <Tooltip id={`tooltip-${name}`}>
                  {name}
                </Tooltip>
              }
            >
              <code className="text-truncate" style={{ minWidth: 0 }}>
                {name}
              </code>
            </OverlayTrigger>
            <span style={{fontSize: '0.9em'}} className="text-nowrap flex-shrink-0">
              {formatTimestamp(timestamp)}
            </span>
          </ListGroup.Item>
        ))}
      </>
    );
  };

  const hasDatabases = statusData && statusData.DATABASE && Object.keys(statusData.DATABASE).length > 0;
  const hasTags = statusData && statusData.TAG && Object.keys(statusData.TAG).length > 0;
  const hasAnyData = hasDatabases || hasTags;

  const resetState = () => {
    setActiveTab('status');
    setSyncVdbs('');
    setSyncTags('');
    setIgnoreTags('');
    setDeleteVdbs('');
    setDeleteTags('');
    setDeleteConflicting(false);
  };

  const handleOnExited = () => {
    resetState();
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  const renderFooterButtons = () => {
    if (activeTab === 'status') {
      return (
        <Button variant="light" onClick={handleClose}>
          Close
        </Button>
      );
    }

    if (activeTab === 'sync') {
      return (
        <>
          <Button variant="light" onClick={handleClose}>
            Cancel
          </Button>
          <Button
              variant="dark"
              type="submit"
              disabled={isLoading || !isTimeoutValid || !isExamplesValid}
              form="sync-form"
          >
            {isLoading ? (
              <>
                <Spinner as="span" animation="border" size="sm" role="status" aria-hidden="true" />
                <span className="ms-2">Syncing...</span>
              </>
            ) : ( 'Sync' )}
          </Button>
        </>
      );
    }
    if (activeTab === 'delete') {
      return (
        <>
          <Button variant="light" onClick={handleClose}>
            Cancel
          </Button>
          <Button variant="danger" type="submit" disabled={isLoading} form="delete-form">
            {isLoading ? (
              <>
                <Spinner as="span" animation="border" size="sm" role="status" aria-hidden="true" />
                <span className="ms-2">Deleting...</span>
              </>
            ) : ( 'Delete' )}
          </Button>
        </>
      );
    }
    return null;
  };

  return (
    <>
      <NotificationToast
        show={toastConfig.show}
        message={toastConfig.message}
        variant={toastConfig.variant}
        title={toastConfig.title}
        duration={toastConfig.duration}
        onClose={handleToastClose}
      />

      <Modal
        show={show}
        onHide={handleClose}
        onExited={handleOnExited}
        centered
        data-bs-theme="light"
      >
        <Modal.Header closeButton>
          <Modal.Title>Vector DB Manager</Modal.Title>
        </Modal.Header>
        <Modal.Body>
            <Tabs
              activeKey={activeTab}
              onSelect={(k) => !isLoading && setActiveTab(k)}
              id="vdb-management-tabs"
              className="mb-3"
              data-bs-theme="light"
            >
              <Tab eventKey="status" title="Vector DB Info" disabled={isLoading}>
                <p>This tab shows the synchronized VDBs and tags with their last synchronization date.</p>
                {hasDatabases && (
                  <>
                    <h5>Synchronized Databases</h5>
                    <div className="border rounded" style={{ maxHeight: '200px', overflowY: 'auto' }}>
                      <ListGroup variant="flush">
                        {renderResourceList(statusData.DATABASE)}
                      </ListGroup>
                    </div>
                  </>
                )}
                {hasTags && (
                  <>
                    <h5 className={hasDatabases ? "mt-4" : ""}>Synchronized Tags</h5>
                    <div className="border rounded" style={{ maxHeight: '200px', overflowY: 'auto' }}>
                      <ListGroup variant="flush">
                        {renderResourceList(statusData.TAG)}
                      </ListGroup>
                    </div>
                  </>
                )}
                {!hasAnyData && (
                  <Alert variant="info" className="mt-3">
                    No synchronized resources found for your account. Use the 'Sync' tab to add them.
                  </Alert>
                )}
              </Tab>

              <Tab eventKey="sync" title="Sync" disabled={isLoading}>
                <Form id="sync-form" onSubmit={handleSyncSubmit}>
                  <Form.Group className="mb-3">
                    <Form.Label>VDBs to Sync (comma-separated)</Form.Label>
                    <Form.Control
                      type="text"
                      placeholder="Specify a comma-separated list of VDBs to sync"
                      value={syncVdbs}
                      onChange={(e) => setSyncVdbs(e.target.value)}
                    />
                  </Form.Group>
                  <Form.Group className="mb-3">
                    <Form.Label>Tags to Sync (comma-separated)</Form.Label>
                    <Form.Control
                      type="text"
                      placeholder="Specify a comma-separated list of tags to sync"
                      value={syncTags}
                      onChange={(e) => setSyncTags(e.target.value)}
                    />
                  </Form.Group>
                  <Form.Group className="mb-3">
                    <Form.Label>Tags to ignore (comma-separated)</Form.Label>
                    <Form.Control
                      type="text"
                      placeholder="Specify a comma-separated list of tags to ignore"
                      value={ignoreTags}
                      onChange={(e) => setIgnoreTags(e.target.value)}
                    />
                  </Form.Group>
                  <div className="row">
                    <div className="col-md-6">
                        <Form.Group className="mb-3">
                            <Form.Label>Examples per Table</Form.Label>
                            <Form.Control
                                type="number"
                                min="0"
                                max="500"
                                value={examplesPerTable}
                                isInvalid={examplesPerTable !== '' && !isExamplesValid}
                                onChange={(e) => setExamplesPerTable(e.target.value === '' ? '' : parseInt(e.target.value))}
                            />
                            <Form.Control.Feedback type="invalid">
                                Must be between 0 and 500.
                            </Form.Control.Feedback>
                        </Form.Group>
                    </div>
                    <div className="col-md-6">
                        <Form.Group className="mb-3">
                          <Form.Label>Timeout (seconds)</Form.Label>
                          <Form.Control
                              type="number"
                              min="1"
                              value={timeoutSeconds}
                              isInvalid={timeoutSeconds !== '' && Number(timeoutSeconds) <= 0}
                              onChange={(e) => setTimeoutSeconds(e.target.value === '' ? '' : parseInt(e.target.value))}
                          />
                          <Form.Control.Feedback type="invalid">
                              Must be greater than 0.
                          </Form.Control.Feedback>
                      </Form.Group>
                    </div>
                  </div>
                  <Form.Group className="mb-3">
                    <Form.Check
                      type="checkbox"
                      label="Enable incremental loading"
                      checked={incremental}
                      onChange={(e) => setIncremental(e.target.checked)}
                    />
                  </Form.Group>
                  <Form.Group className="mb-3">
                    <Form.Check
                      type="checkbox"
                      label="Enable parallel processing"
                      checked={parallel}
                      onChange={(e) => setParallel(e.target.checked)}
                    />
                  </Form.Group>
                </Form>
              </Tab>

              <Tab eventKey="delete" title="Delete" disabled={isLoading}>
                <Form id="delete-form" onSubmit={handleDeleteSubmit}>
                  <Form.Group className="mb-3">
                    <Form.Label>VDBs to Delete (comma-separated)</Form.Label>
                    <Form.Control
                      type="text"
                      placeholder="Leave empty to ignore, or list VDBs"
                      value={deleteVdbs}
                      onChange={(e) => setDeleteVdbs(e.target.value)}
                    />
                  </Form.Group>
                  <Form.Group className="mb-3">
                    <Form.Label>Tags to Delete (comma-separated)</Form.Label>
                    <Form.Control
                      type="text"
                      placeholder="Leave empty to ignore, or list tags"
                      value={deleteTags}
                      onChange={(e) => setDeleteTags(e.target.value)}
                    />
                    <Form.Text>
                      At least one VDB or tag must be provided.
                    </Form.Text>
                  </Form.Group>
                  <Form.Group className="mb-3">
                    <Form.Check
                      type="checkbox"
                      label="Delete conflicting entries"
                      checked={deleteConflicting}
                      onChange={(e) => setDeleteConflicting(e.target.checked)}
                    />
                    <Form.Text>
                      If unchecked, entries linked to other synchronized sources will be preserved.
                    </Form.Text>
                  </Form.Group>
                </Form>
              </Tab>
            </Tabs>
        </Modal.Body>
        <Modal.Footer>
          {renderFooterButtons()}
        </Modal.Footer>
      </Modal>
    </>
  );
};

export default VectorDBSyncModal;

