import Form from "react-bootstrap/Form";
import Navbar from "react-bootstrap/Navbar";
import Button from "react-bootstrap/Button";
import Dropdown from "react-bootstrap/Dropdown";
import Modal from "react-bootstrap/Modal"; 
import React, { useEffect, useState } from "react";
import ResourcesFilterModal from "./ResourcesFilterModal";
import useQuestionForm from "../../hooks/useQuestionForm";
import NotificationToast from "../NotificationToast/NotificationToast";
import "./QuestionForm.css";

const baseToolOptions = [
  { id: 'auto', label: 'Auto (Default)', bg: '#6c757d', icon: 'bi-stars', iconColor: '#6c757d' }, 
  { id: 'deep_query', label: 'Deep Query', bg: 'linear-gradient(135deg, #ED342A 0%, #413581 100%)', icon: 'bi-magic', iconColor: '#7953aa' },
  { id: 'data_agent', label: 'Data Agent', bg: '#0d6efd', icon: 'bi-database', iconColor: '#0d6efd' }, 
  { id: 'metadata_search', label: 'Metadata Search', bg: '#20c997', icon: 'bi-code-slash', iconColor: '#20c997' }, 
  { id: 'knowledge_query', label: 'Knowledge Base Query', bg: '#fd7e14', icon: 'bi-book', iconColor: '#fd7e14' }
];

const QuestionForm = ({ 
  results, 
  dispatch, 
  isAuthenticated, 
  currentQuestion: propCurrentQuestion,
  setCurrentQuestion: propSetCurrentQuestion,
  sdk,
  syncedResources,
  partialResources,
  selectedChatbot
}) => {
  const {
    currentQuestion,
    showFilterModal,
    setShowFilterModal,
    searchFilters,
    allowExternalAssociations,
    isDeepQueryRunning,
    isAnyQueryRunning,
    filterCount,
    textInputRef,
    handleQuestionChange,
    handleFilterSave,
    handleSendClick,
    handleCancelDeepQuery,
    lastToolRequest,
    config,
  } = useQuestionForm(
    propCurrentQuestion,
    propSetCurrentQuestion,
    results,
    dispatch,
    sdk,
    isAuthenticated,
    selectedChatbot
  );

  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: "",
    variant: "info",
    title: "",
  });

  const toolOptions = baseToolOptions.filter(tool => {
    if (tool.id === 'deep_query') return config.enable_deep_query;
    if (tool.id === 'knowledge_query') return config.unstructured_mode;
    return true;
  });

  const [activeTool, setActiveTool] = useState(toolOptions[0]);

  useEffect(() => {
    setActiveTool(baseToolOptions[0]);
  }, [selectedChatbot]);

  const handleToastClose = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  useEffect(() => {
    if (lastToolRequest) {
      if (lastToolRequest.name === 'deep_query' && !config.enable_deep_query) return;
      if (lastToolRequest.name === 'knowledge_query' && !config.unstructured_mode) return;

      const matchedTool = baseToolOptions.find(tool => tool.id === lastToolRequest.name);
      const toolLabel = (matchedTool && matchedTool.label) || lastToolRequest.prettyName || lastToolRequest.name || "tool";

      setToastConfig({
        show: true,
        message: `Requested the "${toolLabel}" tool for this question.`,
        variant: "info",
        title: "Tool Requested",
      });
    }
  }, [lastToolRequest, config.enable_deep_query, config.unstructured_mode]);

  const handleCustomSubmit = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    const forceTool = activeTool.id === 'auto' ? null : activeTool.id;
    handleSendClick(e, forceTool);
  };

  const onCustomKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleCustomSubmit(e);
    }
  };

  const getPlaceholder = () => {
    if (!isAuthenticated) return "Please sign in to ask questions";

    let options = ['@data', '@metadata'];
    if (config.unstructured_mode) options.push('@kb');
    if (config.enable_deep_query) options.push('@deepquery');

    return `Type your question here. Use @ to ask the LLM to use a specific tool, e.g. ${options.join(', ')}.`;
  };

  const getPaddingRight = () => {
    let base = 60;
    if (isDeepQueryRunning) {
      base += 80;
    } else {
      base += 40;
    }
    return `${base}px`;
  };

  return (
    <>
    <NotificationToast
      show={toastConfig.show}
      message={toastConfig.message}
      variant={toastConfig.variant}
      title={toastConfig.title}
      onClose={handleToastClose}
    />

    <Navbar className="justify-content-center w-100" data-bs-theme="dark" style={{ backgroundColor: "transparent" }}>
      <div className="w-100 d-flex justify-content-center">
        <div style={{ width: '80%', maxWidth: '800px' }}>
          <Form onSubmit={handleCustomSubmit}>
            <div className="position-relative">
              <div
                className="position-absolute" 
                style={{ left: '12px', top: '50%', transform: 'translateY(-50%)', zIndex: 5, display: 'flex', alignItems: 'center' }}
              >
                {config.filters_enabled && (
                  <Button
                    variant="link"
                    onClick={() => setShowFilterModal(true)}
                    disabled={!isAuthenticated || isAnyQueryRunning}
                    title="Context selection"
                    style={{ 
                      color: '#6c757d', 
                      textDecoration: 'none',
                      padding: '0.2rem 0.4rem',
                      position: 'relative'
                    }}
                    onMouseEnter={(e) => e.target.style.color = '#112533'}
                    onMouseLeave={(e) => e.target.style.color = '#6c757d'}
                  >
                    <i className="bi bi-filter" style={{ fontSize: '1.25rem' }}></i>
                    {filterCount > 0 && (
                      <span 
                        className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                        style={{ 
                              fontSize: '0.6em', 
                              padding: '0.3em 0.5em',
                              pointerEvents: 'none' 
                          }}
                      >
                        {filterCount}
                      </span>
                    )}
                  </Button>
                )}
              </div>
              <Form.Control
                ref={textInputRef}
                as="textarea"
                type="text"
                placeholder={getPlaceholder()}
                value={currentQuestion}
                onChange={handleQuestionChange}
                onKeyDown={onCustomKeyDown}
                disabled={!isAuthenticated}
                className="question-textarea bg-white"
                style={{ 
                  paddingRight: getPaddingRight(),
                  paddingLeft: '60px',
                  paddingTop: '12px',
                  paddingBottom: '12px',
                  minHeight: '47px',
                  resize: 'none',
                  color: '#212529',
                  border: '1px solid #ced4da',
                  borderRadius: '1.25em',
                  boxShadow: '0 2px 6px rgba(0,0,0,0.05)'
                }}
              />
              <div className="position-absolute" style={{ right: '12px', top: '50%', transform: 'translateY(-50%)', display: 'flex', gap: '8px', alignItems: 'center' }}>
                {isDeepQueryRunning ? (
                  <Button
                    variant="link"
                    type="button"
                    onClick={handleCancelDeepQuery}
                    title="Stop DeepQuery"
                    style={{
                      color: '#dc3545',
                      textDecoration: 'none',
                      padding: '0.2rem',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      transition: 'all 0.2s ease'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.color = '#a71d2a';
                      e.currentTarget.style.transform = 'scale(1.15)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.color = '#dc3545';
                      e.currentTarget.style.transform = 'scale(1)';
                    }}
                  >
                    <i className="bi bi-stop-circle" style={{ fontSize: '1.2rem', pointerEvents: 'none' }}></i>
                  </Button>
                ) : (
                  <Dropdown drop="up" title={activeTool.label}>
                    <Dropdown.Toggle
                      size="sm"
                      disabled={!isAuthenticated || isAnyQueryRunning}
                      style={{
                        background: activeTool.id === 'auto' ? 'transparent' : activeTool.bg,
                        border: activeTool.id === 'auto' ? '1px solid #ced4da' : 'none',
                        color: activeTool.id === 'auto' ? '#6c757d' : 'white',
                        height: '32px',
                        transition: 'all 0.3s ease',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        padding: '0 10px',
                        borderRadius: '8px'
                      }}
                      id="dropdown-tool-selector"
                    >
                      <i className={`bi ${activeTool.icon}`} style={{ fontSize: '1.1rem' }}></i>
                    </Dropdown.Toggle>

                    <Dropdown.Menu
                      align="end"
                      className="shadow border-0 mb-2"
                      style={{
                        fontSize: '0.9rem',
                        minWidth: '200px',
                        borderRadius: '0.75rem',
                        backgroundColor: '#ffffff',
                        padding: '0.5rem 0'
                      }}
                    >
                      <Dropdown.Header className="py-1 fw-bold" style={{ fontSize: '0.75rem', textTransform: 'uppercase', color: '#112533' }}>
                        Select Mode
                      </Dropdown.Header>

                      {toolOptions.map(tool => (
                        <Dropdown.Item
                          key={tool.id}
                          onClick={() => setActiveTool(tool)}
                          className={`py-2 d-flex align-items-center ${activeTool.id === tool.id ? 'fw-bold' : ''}`}
                          style={{
                            color: '#212529',
                            backgroundColor: activeTool.id === tool.id ? '#f8f9fa' : 'transparent',
                            cursor: 'pointer'
                          }}
                        >
                          <i
                            className={`bi ${tool.icon} me-2`}
                            style={{
                              fontSize: '1.1rem',
                              color: activeTool.id === tool.id ? (tool.iconColor || tool.bg.split(' ')[0]) : '#6c757d'
                            }}
                          ></i>
                          {tool.label}
                        </Dropdown.Item>
                      ))}
                    </Dropdown.Menu>
                  </Dropdown>
                )}

                <Button
                  variant="link"
                  type="button"
                  onClick={handleCustomSubmit}
                  disabled={!isAuthenticated || isAnyQueryRunning}
                  title="Send question"
                  style={{
                    color: activeTool.id === 'auto' ? '#112533' : (activeTool.iconColor || activeTool.bg.split(' ')[0]),
                    textDecoration: 'none',
                    padding: '0.2rem',
                    opacity: (!isAuthenticated || isAnyQueryRunning || !currentQuestion.trim()) ? 0.4 : 1,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    transition: 'all 0.2s ease'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.color = activeTool.id === 'auto' ? '#0056b3' : (activeTool.iconColor || activeTool.bg.split(' ')[0]);
                    e.currentTarget.style.transform = 'scale(1.15)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.color = activeTool.id === 'auto' ? '#112533' : (activeTool.iconColor || activeTool.bg.split(' ')[0]);
                    e.currentTarget.style.transform = 'scale(1)';
                  }}
                >
                  <i className="bi bi-send" style={{ fontSize: '1.2rem', pointerEvents: 'none' }}></i>
                </Button>
               </div>
             </div>
           </Form>
         </div>
       </div>
     </Navbar>

    <ResourcesFilterModal 
      show={showFilterModal}
      handleClose={() => setShowFilterModal(false)}
      syncedResources={syncedResources}
      partialResources={partialResources}
      currentFilters={searchFilters}
      currentAllowExternalAssociations={allowExternalAssociations}
      onSave={handleFilterSave}
    />
  </>
  );
};

export default QuestionForm;

import React, { useState, useEffect, useMemo } from "react";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import Form from "react-bootstrap/Form";

const ResourcesFilterModal = ({
  show,
  handleClose,
  syncedResources,
  partialResources,
  currentFilters,
  currentAllowExternalAssociations,
  onSave
}) => {
  const [selectedDatabases, setSelectedDatabases] = useState(
    currentFilters.databases || []
  );
  const [selectedTags, setSelectedTags] = useState(currentFilters.tags || []);
  const [allowExternalAssociations, setAllowExternalAssociations] = useState(
    currentAllowExternalAssociations
  );

  const { allDbNames, allTagNames, isDbPartial, isTagPartial } = useMemo(() => {
    const syncedDbs = Object.keys(syncedResources?.DATABASE || {});
    const syncedTags = Object.keys(syncedResources?.TAG || {});

    const partialDbSet = new Set();
    const partialTagSet = new Set();

    const pDbsByTag = partialResources?.partial_dbs_by_tag || {};
    Object.values(pDbsByTag).forEach((dbList) => {
      dbList.forEach((db) => partialDbSet.add(db));
    });

    const pTagsByDb = partialResources?.partial_tags_by_db || {};
    Object.values(pTagsByDb).forEach((tagList) => {
      tagList.forEach((tag) => partialTagSet.add(tag));
    });

    const pTagsByTag = partialResources?.partial_tags_by_tag || {};
    Object.values(pTagsByTag).forEach((tagList) => {
      tagList.forEach((tag) => partialTagSet.add(tag));
    });

    const combinedDbs = Array.from(new Set([...syncedDbs, ...partialDbSet])).sort();
    const combinedTags = Array.from(new Set([...syncedTags, ...partialTagSet])).sort();

    return {
      allDbNames: combinedDbs,
      allTagNames: combinedTags,
      isDbPartial: (name) => !syncedDbs.includes(name) && partialDbSet.has(name),
      isTagPartial: (name) => !syncedTags.includes(name) && partialTagSet.has(name)
    };
  }, [syncedResources, partialResources]);

  const hasData = allDbNames.length > 0 || allTagNames.length > 0;
  const hasPartials = allDbNames.some(isDbPartial) || allTagNames.some(isTagPartial);

  useEffect(() => {
    setSelectedDatabases(currentFilters.databases || []);
    setSelectedTags(currentFilters.tags || []);
    setAllowExternalAssociations(currentAllowExternalAssociations);
  }, [currentFilters, currentAllowExternalAssociations, show]);

  const handleDatabaseChange = (dbName) => {
    setSelectedDatabases((prev) =>
      prev.includes(dbName)
        ? prev.filter((db) => db !== dbName)
        : [...prev, dbName]
    );
  };

  const handleTagChange = (tagName) => {
    setSelectedTags((prev) =>
      prev.includes(tagName)
        ? prev.filter((tag) => tag !== tagName)
        : [...prev, tagName]
    );
  };

  const handleApply = () => {
    onSave({
      databases: selectedDatabases,
      tags: selectedTags,
      allowExternalAssociations: allowExternalAssociations,
    });
    handleClose();
  };

  const handleClear = () => {
    setSelectedDatabases([]);
    setSelectedTags([]);
    setAllowExternalAssociations(true);
    onSave({ databases: [], tags: [], allowExternalAssociations: true });
    handleClose();
  };

  const allDbsSelected =
    allDbNames.length > 0 && selectedDatabases.length === allDbNames.length;
  const someDbsSelected = selectedDatabases.length > 0 && !allDbsSelected;

  const handleSelectAllDbs = () => {
    if (allDbsSelected) {
      setSelectedDatabases([]);
    } else {
      setSelectedDatabases(allDbNames);
    }
  };

  const allTagsSelected =
    allTagNames.length > 0 && selectedTags.length === allTagNames.length;
  const someTagsSelected = selectedTags.length > 0 && !allTagsSelected;

  const handleSelectAllTags = () => {
    if (allTagsSelected) {
      setSelectedTags([]);
    } else {
      setSelectedTags(allTagNames);
    }
  };

  const renderLabel = (name, isPartial) => (
    <span>
      {name}
      {isPartial && (
        <span className="text-muted ms-1" style={{ fontSize: "0.85em", fontStyle: "italic" }}>
          (partial)
        </span>
      )}
    </span>
  );

  return (
    <Modal show={show} onHide={handleClose} centered>
      <Modal.Header closeButton data-bs-theme="light">
        <Modal.Title>Context Selection</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <p>
          These are the databases and tags the AI SDK has access to. You can
          limit here the context of what the AI SDK will have access to answer
          your question. If none are selected, all accessible resources will be
          used.
        </p>

        {hasPartials && (
          <div className="alert alert-light border p-2 mb-3" style={{ fontSize: "0.9em" }}>
            <strong>Note:</strong> Resources marked as (partial) have not been directly 
            synchronized but were found associated with other synchronized resources.
          </div>
        )}

        {!hasData && (
          <p className="text-muted">
            No synchronized resources found to filter by.
          </p>
        )}

        {allDbNames.length > 0 && (
          <>
            <h5>Databases</h5>
            <div
              style={{ maxHeight: "150px", overflowY: "auto" }}
              className="border rounded p-2"
            >
              <Form>
                <Form.Check
                  type="checkbox"
                  label={allDbsSelected ? "Deselect All" : "Select All"}
                  id="db-select-all"
                  checked={allDbsSelected}
                  ref={(input) => {
                    if (input) input.indeterminate = someDbsSelected;
                  }}
                  onChange={handleSelectAllDbs}
                  className="fw-bold"
                />
                <hr className="my-1" />
                {allDbNames.map((dbName) => (
                  <Form.Check
                    key={dbName}
                    type="checkbox"
                    label={renderLabel(dbName, isDbPartial(dbName))}
                    id={`db-check-${dbName}`}
                    checked={selectedDatabases.includes(dbName)}
                    onChange={() => handleDatabaseChange(dbName)}
                  />
                ))}
              </Form>
            </div>
          </>
        )}

        {allTagNames.length > 0 && (
          <>
            <h5 className="mt-3">Tags</h5>
            <div
              style={{ maxHeight: "150px", overflowY: "auto" }}
              className="border rounded p-2"
            >
              <Form>
                <Form.Check
                  type="checkbox"
                  label={allTagsSelected ? "Deselect All" : "Select All"}
                  id="tag-select-all"
                  checked={allTagsSelected}
                  ref={(input) => {
                    if (input) input.indeterminate = someTagsSelected;
                  }}
                  onChange={handleSelectAllTags}
                  className="fw-bold"
                />
                <hr className="my-1" />
                {allTagNames.map((tagName) => (
                  <Form.Check
                    key={tagName}
                    type="checkbox"
                    label={renderLabel(tagName, isTagPartial(tagName))}
                    id={`tag-check-${tagName}`}
                    checked={selectedTags.includes(tagName)}
                    onChange={() => handleTagChange(tagName)}
                  />
                ))}
              </Form>
            </div>
          </>
        )}

        {hasData && (
          <Form.Check
            type="switch"
            id="allow-external-assoc"
            label="Include associated views (even if outside the filtered context)"
            checked={allowExternalAssociations}
            onChange={(e) => setAllowExternalAssociations(e.target.checked)}
            className="mt-3"
          />
        )}
      </Modal.Body>
      <Modal.Footer>
        {hasData ? (
          <>
            <Button variant="light" onClick={handleClear}>
              Clear All
            </Button>
            <Button variant="dark" onClick={handleApply}>
              Apply
            </Button>
          </>
        ) : (
          <Button variant="light" onClick={handleClose}>
            Close
          </Button>
        )}
      </Modal.Footer>
    </Modal>
  );
};

export default ResourcesFilterModal;

import React from "react";
import { Modal, Button } from "react-bootstrap";

const DeleteChatModal = ({ show, onHide, onConfirm }) => (
  <Modal show={show} onHide={onHide} centered backdrop="static">
    <Modal.Header closeButton data-bs-theme="light">
      <Modal.Title>Delete conversation</Modal.Title>
    </Modal.Header>
    <Modal.Body style={{ color: "#495057", fontSize: "1.05rem" }}>
      Are you sure you want to delete this chat? This action is{" "}
      <strong>irreversible</strong>.
    </Modal.Body>
    <Modal.Footer className="border-0 pt-0">
      <Button variant="light" onClick={onHide}>
        Cancel
      </Button>
      <Button variant="danger" onClick={onConfirm}>
        Accept
      </Button>
    </Modal.Footer>
  </Modal>
);

export default DeleteChatModal;

import React from "react";
import { Modal, Button, Form } from "react-bootstrap";

const RenameChatModal = ({
  show,
  onHide,
  newChatName,
  setNewChatName,
  onConfirm,
}) => (
  <Modal show={show} onHide={onHide} centered>
    <Modal.Header closeButton data-bs-theme="light">
      <Modal.Title>Rename Chat</Modal.Title>
    </Modal.Header>
    <Modal.Body>
      <Form.Group>
        <Form.Label>Chat Title</Form.Label>
        <Form.Control
          type="text"
          value={newChatName}
          onChange={(e) => setNewChatName(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") onConfirm();
          }}
          autoFocus
        />
      </Form.Group>
    </Modal.Body>
    <Modal.Footer className="border-0 pt-0">
      <Button variant="light" onClick={onHide}>
        Cancel
      </Button>
      <Button variant="primary" onClick={onConfirm}>
        Save
      </Button>
    </Modal.Footer>
  </Modal>
);

export default RenameChatModal;

.sidebar-container {
  height: 100vh;
  flex-shrink: 0;
  transition: width 0.3s ease-in-out;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-size: 0.95rem;
}

.sidebar-container.closed {
  width: 0px;
}

.sidebar-container.open {
  width: 260px;
}

/* Header Styles */
.sidebar-header {
  height: 76px;
  min-height: 76px;
  background-color: #143142;
  border-right: 2px solid #143b5c;
}

.sidebar-header-logo {
  height: 30px;
  object-fit: contain;
}

.sidebar-close-btn {
  font-size: 1.5rem;
  cursor: pointer;
  transition: opacity 0.2s;
  color: white;
}

.sidebar-close-btn:hover {
  opacity: 0.7;
}

/* Content Area */
.sidebar-content {
  background-color: #ffffff; 
  border-right: 2px solid #e1e5e8;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: #c1c1c1 transparent;
}

.sidebar-content::-webkit-scrollbar {
  width: 6px;
}
.sidebar-content::-webkit-scrollbar-track {
  background: transparent;
}
.sidebar-content::-webkit-scrollbar-thumb {
  background-color: #e5e5e5;
  border-radius: 10px;
}
.sidebar-content::-webkit-scrollbar-thumb:hover {
  background-color: #c1c1c1;
}

/* Generic Icon Container */
.sidebar-icon-container {
  width: 32px;
  display: flex;
  justify-content: center;
  align-items: center;
  margin-right: 0.75rem;
  flex-shrink: 0;
}

/* Sidebar Items */
.sidebar-item {
  transition: background-color 0.2s ease, color 0.2s ease !important;
  color: #112533 !important;
  background-color: transparent !important;
  border-radius: 6px !important;
  margin: 2px 10px !important;
  width: auto !important;
  position: relative;
  min-width: 0;
}

.sidebar-item:hover {
  background-color: #f1f3f5 !important;
  color: #000000 !important;
  text-decoration: none;
}

.sidebar-item.active {
  background-color: #e9ecef !important;
  font-weight: 600 !important;
  color: #112533 !important;
  border: none !important;
}

.sidebar-item-text {
  flex-grow: 1;
  text-align: left;
  font-size: 0.95rem;
}

/* New Chat Style (Flat and minimalist) */
.new-chat-icon {
  font-size: 1.15rem;
  color: #006699;
}

/* Agent Icons */
.agent-icon {
  width: 30px;
  height: 30px;
  object-fit: contain;
}

.agent-icon-fallback {
  font-size: 1.4rem;
}

/* Section Headers */
.sidebar-section-header {
  font-size: 0.85rem; 
  font-weight: 650;
  color: #006699;
  text-align: left; 
  display: flex;
  justify-content: flex-start; 
  align-items: center;
  position: relative; 
  margin-top: 0.5rem; 
  margin-bottom: 0.5rem;
}

.sidebar-divider {
  height: 1.5px;
  min-height: 1.5px;
  background-color: #e4e9ee;
}

/* Info Icon */
.info-icon-wrapper {
  position: absolute;
  right: 15px; 
}

.info-icon {
  font-size: 1rem;
  color: #006699;
  cursor: help;
  transition: color 0.2s ease;
}

.info-icon:hover {
  color: #143142;
}

/* Upload Icon */
.upload-icon-wrapper {
  position: absolute;
  right: 15px; 
}

.upload-icon {
  font-size: 1rem; 
  color: #006699;
  transition: color 0.2s ease;
}

.upload-icon:hover {
  color: #143142;
}

/* Search Box */
.sidebar-search-wrapper {
  margin: 1.25rem 10px; 
}

.sidebar-search-container {
  padding: 8px 10px; 
  border-color: #ced4da;
  background-color: transparent !important; 
}

.sidebar-search-container input {
  font-size: inherit !important;
}

.search-clear-icon {
  font-size: 0.85rem;
}

/* Empty State / Loading State */
.sidebar-status-message {
  font-size: 0.85rem;
}

.sidebar-empty-state {
  font-style: italic;
  margin-top: 10px;
}

/* --- CHAT ITEM ACTIONS (Hover & Pin Logic) --- */
.sidebar-item-actions {
  position: absolute;
  right: 10px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* By default, the 3-dots menu wrapper is hidden */
.sidebar-dots-menu {
  display: none;
}

/* The pin icon is visible by default (if the chat is pinned) */
.sidebar-pin-icon {
  display: block;
  font-size: 0.9rem;
  color: #006699;
}

/* When hovering over the chat item, hide the pin and show the dots */
.sidebar-item:hover .sidebar-pin-icon {
  display: none;
}

.sidebar-item:hover .sidebar-dots-menu {
  display: flex;
}

/* Also show the dots if the dropdown is currently open (active) */
.sidebar-item.dropdown-open .sidebar-dots-menu {
  display: flex;
}
.sidebar-item.dropdown-open .sidebar-pin-icon {
  display: none;
}

/* Custom Dropdown Toggle (to remove caret) */
.dropdown-toggle-custom {
  cursor: pointer;
  padding: 4px;
}

.dropdown-dots-icon {
  font-size: 1rem;
}

/* Custom Dropdown Menu */
.sidebar-dropdown-menu {
  font-size: 0.9rem;
  min-width: 150px;
  border-color: #dcdfe3;
  border-radius: 8px;
  z-index: 9999;
  color: #006699;
}

/* Load More Button */
.sidebar-load-more {
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.3px;
  color: #6c757d;
  transition: color 0.2s;
}

.sidebar-load-more:hover {
  color: #143142;
}

/* --- Dropdown Menu Icons --- */
.sidebar-dropdown-menu .dropdown-item i {
  color: #006699;
}

.sidebar-dropdown-menu .dropdown-item:not(.text-danger):hover i {
  color: #143142; 
}

.sidebar-dropdown-menu .dropdown-item.text-danger i {
  color: #dc3545;
}

import React, { useRef, useState, useEffect } from "react";
import CustomTooltip from "../CustomTooltip/CustomTooltip";
import Dropdown from "react-bootstrap/Dropdown";
import Spinner from "react-bootstrap/Spinner";
import "./Sidebar.css";

const assetBaseUrl = import.meta.env.BASE_URL;

const Sidebar = ({
  isOpen,
  toggleSidebar,
  chatbots,
  selectedChatbot,
  onSelectChatbot,
  showDenodoSidebarHeaderIcon = true,
  onNewChat,
  chatHistoryList = [],
  currentThreadId,
  onLoadOldChat,
  onDeleteChat,
  onRenameChat,
  onExportChat,
  onImportChat,
  onLoadMoreChats,
  hasMoreChats,
  isLoadingList,
  isLoadingHistory,
  onPinChat,
  searchQuery,
  onSearchChange
}) => {
  const specializedBots = chatbots.filter((bot) => !bot.isGlobal);
  const fileInputRef = useRef(null);

  const [openDropdownId, setOpenDropdownId] = useState(null);

  useEffect(() => {
    const handleClickOutside = () => setOpenDropdownId(null);
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      onImportChat(e.target.files[0]);
      e.target.value = null;
    }
  };

  return (
    <div className={`sidebar-container ${isOpen ? "open" : "closed"}`}>
      <div
        className={`sidebar-header d-flex align-items-center px-3 ${
          showDenodoSidebarHeaderIcon ? "justify-content-between" : "justify-content-end"
        }`}
      >
        {showDenodoSidebarHeaderIcon && (
          <img
            src={`${assetBaseUrl}denodo_icon_white.svg`}
            alt="Denodo Logo"
            className="sidebar-header-logo"
            onError={(e) => (e.target.style.display = "none")}
          />
        )}

        <i
          className="bi bi-arrow-bar-left sidebar-close-btn"
          onClick={toggleSidebar}
          title="Close sidebar"
        ></i>
      </div>

      <div className="sidebar-content flex-grow-1 py-3 d-flex flex-column gap-3">

        <div className="px-2 d-flex flex-column">
          <div
            className="sidebar-item new-chat-btn d-flex align-items-center p-2 cursor-pointer"
            onClick={onNewChat}
          >
            <div className="sidebar-icon-container">
              <i className="bi bi-pencil-square new-chat-icon"></i>
            </div>
            <span className="sidebar-item-text new-chat-text text-truncate">
              New chat
            </span>
          </div>
        </div>

        {specializedBots.length > 0 && (
          <>
            <div className="mx-3 sidebar-divider"></div>

            <div className="px-2 d-flex flex-column">
              <div className="sidebar-section-header px-3">
                <span>AGENTS</span>

                <div className="info-icon-wrapper px-2">
                  <CustomTooltip
                    id="tooltip-agents-info"
                    content="Specialized assistants focused on handling specific tasks and data domains."
                    delay={{ show: 200, hide: 300 }}
                  >
                    <i className="bi bi-info-circle info-icon"></i>
                  </CustomTooltip>
                </div>
              </div>

              <div className="d-flex flex-column gap-1 mt-1">
                {specializedBots.map((bot) => (
                  <CustomTooltip key={bot.id} id={`tooltip-${bot.id}`} content={<div className="text-start"><strong>{bot.name}</strong><br/>{bot.description}</div>}>
                    <div
                      className={`sidebar-item d-flex align-items-center p-2 cursor-pointer ${selectedChatbot?.id === bot.id ? "active" : ""}`}
                      onClick={() => onSelectChatbot(bot)}
                    >
                      <div className="sidebar-icon-container">
                        {bot.icon ? (
                          <img src={bot.icon} alt="" className="agent-icon" onError={(e) => { e.target.style.display = "none"; e.target.nextSibling.style.display = "inline-block"; }} />
                        ) : null}
                        <i className="bi bi-robot agent-icon-fallback" style={{ display: bot.icon ? "none" : "inline-block" }}></i>
                      </div>
                      <span className="sidebar-item-text text-truncate">{bot.name}</span>
                    </div>
                  </CustomTooltip>
                ))}
              </div>
            </div>
          </>
        )}

        <div className="mx-3 sidebar-divider"></div>

        <div className="px-2 d-flex flex-column">

          <div className="sidebar-section-header px-3">
            <span>RECENT CHATS</span>
            <div className="upload-icon-wrapper px-2 d-flex align-items-center">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                style={{ display: 'none' }} 
                accept=".json" 
                disabled={isLoadingHistory} 
              />
              {isLoadingHistory ? (
                <Spinner animation="border" size="sm" className="text-muted" title="Importing..." />
              ) : (
                <i 
                  className="bi bi-upload cursor-pointer upload-icon" 
                  title="Import Chat"
                  onClick={() => fileInputRef.current.click()}
                ></i>
              )}
            </div>
          </div>

          <div className="sidebar-search-wrapper">
             <div className="d-flex align-items-center border rounded sidebar-search-container">
               <i className="bi bi-search text-muted me-2"></i>
               <input
                  type="text"
                  placeholder="Search chats by title..."
                  className="form-control border-0 shadow-none bg-transparent p-0"
                  value={searchQuery}
                  onChange={(e) => onSearchChange(e.target.value)}
               />
               {searchQuery && (
                  <i 
                    className="bi bi-x-circle-fill text-muted cursor-pointer ms-1 search-clear-icon" 
                    onClick={() => onSearchChange("")}
                  ></i>
               )}
             </div>
          </div>

          <div className="d-flex flex-column gap-1">
            {isLoadingList && chatHistoryList.length === 0 ? (
              <div className="d-flex align-items-center gap-2 px-4 py-2 text-muted sidebar-status-message">
                <Spinner animation="border" size="sm" />
                <span>Loading...</span>
              </div>
            ) : chatHistoryList.length === 0 ? (
              <div className="px-4 text-muted text-center sidebar-status-message sidebar-empty-state">
                {searchQuery ? "No matching chats found." : "No recent chats found."}
              </div>
            ) : (
              <>
                {chatHistoryList.map((chat) => {
                  const isDropdownOpen = openDropdownId === chat.thread_id;

                  return (
                    <div
                      key={chat.thread_id}
                      className={`sidebar-item d-flex align-items-center p-2 cursor-pointer ${
                        currentThreadId === chat.thread_id ? "active" : ""
                      } ${isDropdownOpen ? "dropdown-open" : ""}`}
                      onClick={() => onLoadOldChat(chat)}
                      title={chat.title}
                    >

                      <span className="sidebar-item-text text-truncate pe-4">
                        {chat.title}
                      </span>

                      <div className="sidebar-item-actions">
                        {chat.is_pinned && (
                          <i className="bi bi-pin-fill sidebar-pin-icon"></i>
                        )}

                        <div 
                          className="sidebar-dots-menu"
                          onClick={(e) => {
                            e.stopPropagation();
                            setOpenDropdownId(isDropdownOpen ? null : chat.thread_id);
                          }}
                        >
                          <Dropdown show={isDropdownOpen} drop="end">
                            <Dropdown.Toggle 
                              as="div"
                              bsPrefix="dropdown-toggle-custom"
                              className="text-muted d-flex align-items-center" 
                            >
                              <i className="bi bi-three-dots-vertical dropdown-dots-icon"></i>
                            </Dropdown.Toggle>

                            <Dropdown.Menu 
                              className="shadow-lg border sidebar-dropdown-menu" 
                              renderOnMount
                              popperConfig={{ 
                                strategy: 'fixed',
                                modifiers: [
                                  { name: 'preventOverflow', options: { boundary: 'window' } },
                                  { name: 'computeStyles', options: { adaptive: false } }
                                ]
                              }} 
                            >
                              <Dropdown.Item onClick={(e) => { e.stopPropagation(); setOpenDropdownId(null); onPinChat(chat.thread_id, !chat.is_pinned); }}>
                                <i className={`bi ${chat.is_pinned ? 'bi-pin' : 'bi-pin-fill'} me-2`}></i>
                                {chat.is_pinned ? 'Unpin chat' : 'Pin chat'}
                              </Dropdown.Item>

                              <Dropdown.Item onClick={(e) => { e.stopPropagation(); setOpenDropdownId(null); onRenameChat(chat); }}>
                                <i className="bi bi-pencil-fill me-2"></i> Rename
                              </Dropdown.Item>

                              <Dropdown.Item onClick={(e) => { e.stopPropagation(); setOpenDropdownId(null); onExportChat(chat); }}>
                                <i className="bi bi-download me-2"></i> Export
                              </Dropdown.Item>

                              <Dropdown.Divider />

                              <Dropdown.Item className="text-danger" onClick={(e) => { e.stopPropagation(); setOpenDropdownId(null); onDeleteChat(chat.thread_id); }}>
                                <i className="bi bi-trash3 me-2"></i> Delete
                              </Dropdown.Item>
                            </Dropdown.Menu>
                          </Dropdown>
                        </div>
                      </div>
                    </div>
                  );
                })}

                {hasMoreChats && !searchQuery && (
                  <div 
                    className="text-center py-3 mt-1 cursor-pointer sidebar-load-more"
                    onClick={onLoadMoreChats}
                  >
                    <i className="bi bi-chevron-down me-1"></i> Load older chats
                  </div>
                )}
              </>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

export default Sidebar;

import React from "react";

const assetBaseUrl = import.meta.env.BASE_URL;

const WelcomeScreen = ({
  selectedChatbot,
  customLogoState,
  username,
  globalEnabled,
}) => {
  if (!selectedChatbot) {
    return (
      <div className="d-flex flex-column align-items-center w-100">
        {customLogoState === "absent" && (
          <>
            <h1 className="animate-fade-in-up delay-1 display-6 fw-normal text-dark mb-3 text-center">
              Hi {username ? username : "user"}, welcome to
            </h1>
            <div className="animate-fade-in-up delay-2">
              <h2
                className="text-shine px-3 py-2 display-4 m-0 text-center"
                style={{ fontWeight: 600, letterSpacing: "-1.5px" }}
              >
                Denodo Ask A Question
              </h2>
            </div>
          </>
        )}
        {globalEnabled ? (
          <p
            className="animate-fade-in-up delay-3 lead text-muted mt-4 mb-3 mx-auto text-center"
            style={{ maxWidth: "650px" }}
          >
            Select a specialized chatbot from the sidebar, or start typing below
            to use the general chat immediately.
          </p>
        ) : (
          <p
            className="animate-fade-in-up delay-3 lead text-muted mt-4 mb-3 mx-auto text-center"
            style={{ maxWidth: "550px" }}
          >
            To get started, please select one of the available chatbots from the
            sidebar.
          </p>
        )}
      </div>
    );
  }

  return (
    <div
      key={selectedChatbot.id}
      className="fade-in-smooth d-flex flex-column align-items-center text-center px-4"
    >
      {selectedChatbot.isGlobal ? (
        <img
          src={`${assetBaseUrl}denodo_chat_transparent.png`}
          alt="Chat"
          style={{
            width: "80px",
            height: "80px",
            objectFit: "contain",
            marginBottom: "20px",
          }}
          onError={(e) => {
            e.target.style.display = "none";
            e.target.nextSibling.style.display = "flex";
          }}
        />
      ) : selectedChatbot.icon ? (
        <img
          src={selectedChatbot.icon}
          alt={selectedChatbot.name}
          style={{
            width: "80px",
            height: "80px",
            objectFit: "contain",
            marginBottom: "20px",
          }}
          onError={(e) => {
            e.target.style.display = "none";
            e.target.nextSibling.style.display = "flex";
          }}
        />
      ) : null}
      <div
        className="align-items-center justify-content-center"
        style={{
          display:
            selectedChatbot.icon || selectedChatbot.isGlobal ? "none" : "flex",
          width: "80px",
          height: "80px",
          backgroundColor: "#f1f3f5",
          borderRadius: "50%",
          marginBottom: "20px",
        }}
      >
        <i
          className={`bi ${selectedChatbot.isGlobal ? "bi-chat-left-text" : "bi-robot"}`}
          style={{ fontSize: "2.5rem", color: "#143142" }}
        ></i>
      </div>
      {!selectedChatbot.isGlobal && (
        <h2 style={{ color: "#112533", fontWeight: 600, marginBottom: "15px" }}>
          {selectedChatbot.name}
        </h2>
      )}
      <p
        style={{
          color: "#6c757d",
          maxWidth: "600px",
          fontSize: "1.1rem",
          lineHeight: "1.6",
          marginTop: selectedChatbot.isGlobal ? "15px" : "0",
          marginBottom: 0,
          maxHeight: "100px",
          overflowY: "auto",
          paddingRight: "10px",
        }}
      >
        {selectedChatbot.description ||
          "I'm ready to help you. Ask me anything!"}
      </p>
    </div>
  );
};

export default WelcomeScreen;

import React, { createContext, useState, useContext, useEffect } from 'react';
import api from '../api/client';

// Create the context
const ConfigContext = createContext();

// Create a provider component
export const ConfigProvider = ({ children }) => {
  const [config, setConfig] = useState({
    // No default values - we'll only use what the server provides
  });
  const [loading, setLoading] = useState(true);

  const updateConfig = (newParams) => {
    setConfig(prev => ({ ...prev, ...newParams }));
  };

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const response = await api.get("config");
        setConfig(response.data);
      } catch (error) {
        console.error('Error fetching config:', error);
        // Keep empty config if fetch fails
      } finally {
        setLoading(false);
      }
    };

    fetchConfig();
  }, []);

  return (
    <ConfigContext.Provider value={{ config, loading, updateConfig }}>
      {children}
    </ConfigContext.Provider>
  );
};

// Create a custom hook to use the config context
export const useConfig = () => {
  const context = useContext(ConfigContext);
  if (context === undefined) {
    throw new Error('useConfig must be used within a ConfigProvider');
  }
  return context;
};

export default ConfigContext;

import React, { createContext, useState, useContext, useCallback } from 'react';
import api from '../api/client';

// Create the context
const ReportContext = createContext();

// Report status constants
export const REPORT_STATUS = {
  PENDING: 'pending',
  PROCESSING: 'processing', 
  COMPLETED: 'completed',
  FAILED: 'failed'
};

// Create a provider component
export const ReportProvider = ({ children }) => {
  const [reports, setReports] = useState([]); // Array of report objects
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Generate a report from DeepQuery metadata
  const generateReport = useCallback(async (deepqueryMetadata, question, colorPalette = 'red') => {
    const reportId = `report_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Extract report title from metadata, fallback to question if not available
    const reportTitle = deepqueryMetadata?.analysis_title || question || 'Untitled Report';

    // Add to pending list
    const newReport = {
      id: reportId,
      question: question,
      reportTitle: reportTitle,
      status: REPORT_STATUS.PENDING,
      createdAt: new Date(),
      colorPalette: colorPalette,
      metadata: deepqueryMetadata,
      downloadUrl: null,
      error: null
    };

    setReports(prev => [...prev, newReport]);

    try {
      // Update status to processing
      setReports(prev => prev.map(report => 
        report.id === reportId 
          ? { ...report, status: REPORT_STATUS.PROCESSING }
          : report
      ));

      // Call the generate report endpoint
      const response = await api.post("generate_report", {
        deepquery_metadata: deepqueryMetadata,
        color_palette: colorPalette
      });

      const htmlReport = response.data.html_report;

      if (htmlReport) {
        const blob = new Blob([htmlReport], { type: 'text/html' });
        const downloadUrl = URL.createObjectURL(blob);

        const safeTitle = reportTitle
          ? reportTitle.replace(/[^a-z0-9]/gi, '_').toLowerCase()
          : reportId;
        const filename = `${safeTitle}_report.html`;

        setReports(prev => prev.map(report => 
          report.id === reportId 
            ? { 
                ...report, 
                status: REPORT_STATUS.COMPLETED,
                completedAt: new Date(),
                downloadUrl: downloadUrl,
                filename: filename
              }
            : report
        ));
      } else {
        throw new Error('No HTML report received');
      }

    } catch (error) {
      console.error('Error generating report:', error);
      setReports(prev => prev.map(report => 
        report.id === reportId 
          ? { 
              ...report, 
              status: REPORT_STATUS.FAILED,
              completedAt: new Date(),
              error: error.response?.data?.error || error.message
            }
          : report
      ));
    }

    return reportId;
  }, []);

  // Remove a report from the list
  const removeReport = useCallback((reportId) => {
    setReports(prev => {
      const toRemove = prev.find(report => report.id === reportId);
      if (toRemove && toRemove.downloadUrl) {
        URL.revokeObjectURL(toRemove.downloadUrl);
      }
      return prev.filter(report => report.id !== reportId);
    });
  }, []);

  // Clear all reports
  const clearAllReports = useCallback(() => {
    reports.forEach(report => {
      if (report.downloadUrl) {
        URL.revokeObjectURL(report.downloadUrl);
      }
    });
    setReports([]);
  }, [reports]);

  // Get counts by status
  const getStatusCounts = useCallback(() => {
    return reports.reduce((counts, report) => {
      counts[report.status] = (counts[report.status] || 0) + 1;
      return counts;
    }, {});
  }, [reports]);

  const value = {
    reports,
    isModalOpen,
    setIsModalOpen,
    generateReport,
    removeReport,
    clearAllReports,
    getStatusCounts
  };

  return (
    <ReportContext.Provider value={value}>
      {children}
    </ReportContext.Provider>
  );
};

// Create a custom hook to use the report context
export const useReport = () => {
  const context = useContext(ReportContext);
  if (context === undefined) {
    throw new Error('useReport must be used within a ReportProvider');
  }
  return context;
};

export default ReportContext;

import { useState, useMemo } from "react";
import api from "../api/client";

export const useAgentManager = (updateConfig) => {
  const [chatbots, setChatbots] = useState([]);
  const [selectedChatbot, setSelectedChatbot] = useState(null);
  const [globalEnabled, setGlobalEnabled] = useState(false);
  const [isSwitchingAgent, setIsSwitchingAgent] = useState(false);
  const [syncedResources, setSyncedResources] = useState({});
  const [partialResources, setPartialResources] = useState({});
  const [userSyncPermissions, setUserSyncPermissions] = useState(true);

  const activeChatbot = useMemo(() => {
    if (selectedChatbot) return selectedChatbot;
    const globalBot = chatbots.find((bot) => bot.isGlobal);
    return globalBot || { id: "global", isGlobal: true, name: "General Chat" };
  }, [selectedChatbot, chatbots]);

  const switchAgentInBackend = async (bot) => {
    const currentUser = localStorage.getItem("current_user") || "";
    const savedUserDetails =
      localStorage.getItem(`${currentUser}_user_details`) || "";
    const agentKey = bot.isGlobal ? "global" : bot.id;

    let savedCustomInstructions = null;
    try {
      savedCustomInstructions = JSON.parse(
        localStorage.getItem(`${currentUser}_custom_instructions_dict`),
      )[agentKey];
    } catch (e) {}

    let chatbotLlmSettings = null;
    try {
      chatbotLlmSettings = JSON.parse(
        localStorage.getItem(`${currentUser}_chatbot_llm_settings_dict`),
      )[agentKey];
    } catch (e) {}

    let aiSdkSettings = null;
    try {
      aiSdkSettings = JSON.parse(
        localStorage.getItem(`${currentUser}_ai_sdk_llm_settings_dict`),
      )[agentKey];
    } catch (e) {}

    const payload = {
      id: bot.id,
      user_details: savedUserDetails,
      custom_instructions: savedCustomInstructions,
      llm_settings: {},
    };

    if (chatbotLlmSettings)
      payload.llm_settings.chatbot_llm = chatbotLlmSettings;
    if (aiSdkSettings) {
      payload.llm_settings.ai_sdk_base_llm = aiSdkSettings.ai_sdk_base_llm;
      payload.llm_settings.ai_sdk_thinking_llm =
        aiSdkSettings.ai_sdk_thinking_llm;
      payload.llm_settings.use_base_llm_for_execution =
        aiSdkSettings.use_base_llm_for_execution;
      payload.llm_settings.check_ambiguity = aiSdkSettings.check_ambiguity;
    }

    const response = await api.post("change_agent", payload);
    if (response.data.success) {
      if (response.data.syncedResources)
        setSyncedResources(response.data.syncedResources);
      if (response.data.partialResources)
        setPartialResources(response.data.partialResources);
      if (response.data.config) updateConfig(response.data.config);
    }
  };

  return {
    chatbots,
    setChatbots,
    selectedChatbot,
    setSelectedChatbot,
    globalEnabled,
    setGlobalEnabled,
    isSwitchingAgent,
    setIsSwitchingAgent,
    syncedResources,
    setSyncedResources,
    partialResources,
    setPartialResources,
    userSyncPermissions,
    setUserSyncPermissions,
    activeChatbot,
    switchAgentInBackend,
  };
};

import { useState } from "react";
import api from "../api/client";
import { actionTypes } from "../reducers/chatReducer";

const CHAT_PAGE_LIMIT = 20;

export const useChatHistory = (
  dispatch,
  chatbots,
  switchAgentInBackend,
  setSelectedChatbot,
  setAutoOverwriteAccepted,
  handleLimitReached
) => {
  const [currentThreadId, setCurrentThreadId] = useState(null);
  const [chatHistoryList, setChatHistoryList] = useState([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [chatToDelete, setChatToDelete] = useState(null);
  const [chatToRename, setChatToRename] = useState(null);
  const [newChatName, setNewChatName] = useState("");
  const [chatOffset, setChatOffset] = useState(0);
  const [hasMoreChats, setHasMoreChats] = useState(true);
  const [isLoadingList, setIsLoadingList] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  const fetchChatHistoryList = async (
    isLoadMore = false,
    query = searchQuery,
  ) => {
    try {
      if (!isLoadMore) setIsLoadingList(true);
      const currentOffset = isLoadMore ? chatOffset + CHAT_PAGE_LIMIT : 0;
      const response = await api.get(
        `history?limit=${CHAT_PAGE_LIMIT}&offset=${currentOffset}&q=${encodeURIComponent(query)}`,
      );

      if (response.data && response.data.chats) {
        const newChats = response.data.chats;
        if (isLoadMore) {
          setChatHistoryList((prev) => [...prev, ...newChats]);
          setChatOffset(currentOffset);
        } else {
          setChatHistoryList(newChats);
          setChatOffset(0);
        }
        setHasMoreChats(newChats.length >= CHAT_PAGE_LIMIT);
      }
    } catch (error) {
      console.error("Error fetching chat history list", error);
    } finally {
      setIsLoadingList(false);
    }
  };

  const handleRequestCompletion = (requestId) => {
    fetchChatHistoryList(false);
  };

  const handleLoadOldChat = async (chat) => {
    try {
      setAutoOverwriteAccepted(false);
      setIsLoadingHistory(true);

      let targetBot = chatbots.find((b) => b.isGlobal);
      if (chat.agent_id) {
        targetBot = chatbots.find((b) => b.id === chat.agent_id) || targetBot;
      }
      await switchAgentInBackend(targetBot);

      setCurrentThreadId(chat.thread_id);
      setSelectedChatbot(targetBot);
      dispatch({ type: actionTypes.CLEAR_CHAT });

      const response = await api.get(`history/${chat.thread_id}/export`);
      const rawMessages = response.data.messages || [];
      const formattedResults = [];
      let currentInteraction = null;

      for (let i = 0; i < rawMessages.length; i++) {
        const msg = rawMessages[i];

        if (msg.role === "human" || msg.role === "user") {
          // Push previous interaction if exists
          if (currentInteraction) formattedResults.push(currentInteraction);

          let cleanQuestion = msg.content || "";
          if (cleanQuestion.includes("<user_query>")) {
            const match = cleanQuestion.match(
              /<user_query>([\s\S]*?)<\/user_query>/,
            );
            if (match && match[1]) cleanQuestion = match[1].trim();
          }

          // Start a new interaction
          currentInteraction = {
            question: cleanQuestion,
            result: "",
            blocks: [],
            uuid: msg.uuid || `hist-${chat.thread_id}-${formattedResults.length}`,
            isLoading: false,
            isError: false,
            toolCalls: [],
            chatbot_llm: null,
            relatedQuestions: [],
            relatedQuestionsDeepQuery: [],
            combinedTablesUsed: [],
            combinedVqls: "",
            disableFeedback: false,
          };
        } else if (currentInteraction) {
          // --- AI/ASSISTANT MESSAGES ---
          if (msg.role === "ai" || msg.role === "assistant") {

            if (msg.is_imported) {
              currentInteraction.disableFeedback = true;
            }

            if (msg.chatbot_llm) {
              currentInteraction.chatbot_llm = msg.chatbot_llm;
            } else if (!currentInteraction.chatbot_llm) {
              currentInteraction.chatbot_llm = "History Record";
            }

            // 1. Process Text Block sequentially
            if (msg.content && typeof msg.content === "string") {
              let text = msg.content;

              // Extract related questions
              const rqRegex =
                /<related_question[^>]*>([\s\S]*?)<\/related_question>/gi;
              let match;
              while ((match = rqRegex.exec(text)) !== null)
                currentInteraction.relatedQuestions.push(match[1].trim());

              const rqdqRegex =
                /<related_question_deepquery[^>]*>([\s\S]*?)<\/related_question_deepquery>/gi;
              while ((match = rqdqRegex.exec(text)) !== null)
                currentInteraction.relatedQuestionsDeepQuery.push(
                  match[1].trim(),
                );

              const rqaRegex =
                /<related_question_analysis[^>]*>([\s\S]*?)<\/related_question_analysis>/gi;
              while ((match = rqaRegex.exec(text)) !== null)
                currentInteraction.relatedQuestionsDeepQuery.push(
                  match[1].trim(),
                );

              // Clean text from tags
              text = text
                .replace(
                  /<related_question[^>]*>[\s\S]*?<\/related_question>/gi,
                  "",
                )
                .replace(
                  /<related_question_deepquery[^>]*>[\s\S]*?<\/related_question_deepquery>/gi,
                  "",
                )
                .replace(
                  /<related_question_analysis[^>]*>[\s\S]*?<\/related_question_analysis>/gi,
                  "",
                );

              const cleanText = text.trim();

              // Push text directly to blocks to maintain sequential order
              if (cleanText) {
                currentInteraction.blocks.push({
                  type: "message",
                  content: cleanText,
                });
                currentInteraction.result +=
                  (currentInteraction.result ? "\n" : "") + cleanText;
              }
            }

            // 2. Process Tool Calls sequentially
            if (msg.tool_calls && Array.isArray(msg.tool_calls)) {
              msg.tool_calls.forEach((tc) => {
                const toolBlock = {
                  type: "tool",
                  toolName: tc.name,
                  name: tc.name,
                  toolCallId: tc.id,
                  args: tc.args || {},
                  status: "running",
                };
                // Push reference to both arrays
                currentInteraction.toolCalls.push(toolBlock);
                currentInteraction.blocks.push(toolBlock);
              });
            }
          }

          // --- TOOL MESSAGES ---
          else if (msg.role === "tool") {
            let parsedResult = msg.content;
            try {
              if (msg.content && typeof msg.content === "string")
                parsedResult = JSON.parse(msg.content);
            } catch (e) {}

            const artifact = msg.artifact || {};
            if (artifact.tables_used && Array.isArray(artifact.tables_used)) {
              artifact.tables_used.forEach((table) => {
                if (!currentInteraction.combinedTablesUsed.includes(table))
                  currentInteraction.combinedTablesUsed.push(table);
              });
            }

            if (artifact.vql) {
              currentInteraction.combinedVqls +=
                (currentInteraction.combinedVqls ? "\n\n" : "") + artifact.vql;
            }

            // Find the sequential block and update it
            const blockIndex = currentInteraction.blocks.findIndex(
              (b) => b.type === "tool" && b.toolCallId === msg.tool_call_id,
            );

            if (blockIndex !== -1) {
              currentInteraction.blocks[blockIndex].status = "finished";
              currentInteraction.blocks[blockIndex].result = parsedResult;
              currentInteraction.blocks[blockIndex].output = parsedResult;
              currentInteraction.blocks[blockIndex].contentToLLM = msg.content;
              currentInteraction.blocks[blockIndex].artifact = artifact;
            } else {
              // Edge case: Tool answer without previous Tool call registered
              const newToolBlock = {
                type: "tool",
                toolName: msg.tool_name || "tool",
                name: msg.tool_name || "tool",
                toolCallId: msg.tool_call_id,
                status: "finished",
                result: parsedResult,
                output: parsedResult,
                contentToLLM: msg.content,
                artifact: artifact,
                args: {},
              };
              currentInteraction.toolCalls.push(newToolBlock);
              currentInteraction.blocks.push(newToolBlock);
            }
          }
        }
      }

      if (currentInteraction) formattedResults.push(currentInteraction);

      dispatch({
        type: actionTypes.SET_CHAT_HISTORY,
        payload: formattedResults,
      });
    } catch (error) {
      console.error(error);
      alert("Error loading this conversation.");
    } finally {
      setIsLoadingHistory(false);
    }
  };

  const confirmDeleteChat = async (handleNewChat) => {
    if (!chatToDelete) return;
    try {
      await api.delete(`history/${chatToDelete}`);
      if (currentThreadId === chatToDelete) handleNewChat();
      fetchChatHistoryList(false);
    } catch (error) {
      alert("Error deleting the chat history.");
    } finally {
      setChatToDelete(null);
    }
  };

  const handleRenameSubmit = async () => {
    if (!chatToRename || !newChatName.trim()) return;
    try {
      await api.put(`history/${chatToRename.thread_id}`, {
        title: newChatName,
      });
      fetchChatHistoryList(false);
    } catch (e) {
      alert("Error renaming chat.");
    } finally {
      setChatToRename(null);
      setNewChatName("");
    }
  };

  const handlePinChat = async (threadId, isPinned) => {
    try {
      await api.put(`history/${threadId}/pin`, { is_pinned: isPinned });
      fetchChatHistoryList(false);
    } catch (e) {
      alert("Error pin status.");
    }
  };

  const handleExportChat = async (chat) => {
    try {
      const response = await api.get(`history/${chat.thread_id}/export`);
      const exportPayload = { ...response.data, title: chat.title };
      const blob = new Blob([JSON.stringify(exportPayload, null, 2)], {
        type: "application/json",
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `denodo_chat_${chat.title.replace(/[^a-z0-9]/gi, "_").toLowerCase()}.json`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("Error exporting chat.");
    }
  };

  const handleImportChat = async (file, forceOverwrite = false) => {
    if (!file) return;

    setIsLoadingHistory(true);

    const formData = new FormData();
    formData.append("file", file);
    if (forceOverwrite) formData.append("force_overwrite", "true");

    try {
      const response = await api.post("history/import", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      if (response.data.success) {
        await fetchChatHistoryList(false);

        await handleLoadOldChat({
          thread_id: response.data.thread_id,
          agent_id: response.data.agent_id,
          title: response.data.title
        });
      }
    } catch (error) {
      if (
        error.response &&
        error.response.status === 409 &&
        error.response.data.error === "limit_reached"
      ) {
        if (handleLimitReached) {
          handleLimitReached(error.response.data, {
            type: "import",
            file: file,
          });
        }
      } else {
        alert("Error importing chat. Make sure it's a valid JSON export file.");
      }
    } finally {
      setIsLoadingHistory(false);
    }
  };

  const resetHistoryState = () => {
    setChatHistoryList([]);
    setChatOffset(0);
    setSearchQuery("");
    setHasMoreChats(true);
  };

  return {
    currentThreadId,
    setCurrentThreadId,
    chatHistoryList,
    isLoadingHistory,
    chatToDelete,
    setChatToDelete,
    chatToRename,
    setChatToRename,
    newChatName,
    setNewChatName,
    hasMoreChats,
    isLoadingList,
    searchQuery,
    setSearchQuery,
    fetchChatHistoryList,
    handleLoadOldChat,
    confirmDeleteChat,
    handleRenameSubmit,
    handlePinChat,
    handleExportChat,
    handleImportChat,
    handleRequestCompletion,
    resetHistoryState,
  };
};

import { useState } from "react";
import { actionTypes } from "../reducers/chatReducer";

export const useChatLimits = (dispatch) => {
  const [limitModal, setLimitModal] = useState({
    show: false,
    type: null,
    pendingData: null,
    limit: 0,
    current: 0,
    targetsToDelete: [],
  });
  const [autoOverwriteAccepted, setAutoOverwriteAccepted] = useState(false);

  const handleLimitReached = (errorData, pendingRequestData) => {
    setLimitModal({
      show: true,
      type: errorData.type,
      limit: errorData.limit,
      current: errorData.current,
      targetsToDelete: errorData.targets_to_delete || [],
      pendingData: pendingRequestData,
    });
  };

  const closeLimitModal = () => {
    if (
      limitModal.pendingData &&
      limitModal.pendingData.resultIndex !== undefined
    ) {
      dispatch({
        type: actionTypes.DELETE_CHAT_ITEM,
        payload: { resultIndex: limitModal.pendingData.resultIndex },
      });
    }
    setLimitModal({
      show: false,
      type: null,
      pendingData: null,
      limit: 0,
      current: 0,
      targetsToDelete: [],
    });
  };

  return {
    limitModal,
    setLimitModal,
    autoOverwriteAccepted,
    setAutoOverwriteAccepted,
    handleLimitReached,
    closeLimitModal,
  };
};

import { useState, useRef, useEffect } from "react";
import { useConfig } from "../contexts/ConfigContext";
import { actionTypes } from "../reducers/chatReducer";
import useToolSelector from "./useToolSelector";

const useQuestionForm = (currentQuestion, setCurrentQuestion, results, dispatch, sdk, isAuthenticated, selectedChatbot) => {
  const { config } = useConfig();
  const { isLoading, processQuestion, cancelDeepQuery, runningDeepQueries } = sdk;

  const [lastRequestId, setLastRequestId] = useState(null);
  const [showFilterModal, setShowFilterModal] = useState(false);
  const [searchFilters, setSearchFilters] = useState({
    databases: [],
    tags: [],
  });
  const [allowExternalAssociations, setAllowExternalAssociations] = useState(true);
  const [lastToolRequest, setLastToolRequest] = useState(null);

  const textInputRef = useRef(null);

  useEffect(() => {
    setSearchFilters({
      databases: [],
      tags: [],
    });
    setAllowExternalAssociations(true);
  }, [selectedChatbot]);

  const isDeepQueryRunning =
    config.enable_deep_query && lastRequestId !== null && runningDeepQueries.includes(lastRequestId);
  const isAnyQueryRunning = isLoading || results.some((r) => r.isLoading);
  const filterCount = searchFilters.databases.length + searchFilters.tags.length;

  const {
    prepareSubmission,
  } = useToolSelector(config);

  const handleQuestionChange = (event) => {
    setCurrentQuestion(event.target.value);
  };

  const handleFilterSave = ({ databases, tags, allowExternalAssociations }) => {
    setSearchFilters({ databases, tags });
    setAllowExternalAssociations(allowExternalAssociations);
  };

  const submitQuestion = async (questionText, forceType = null) => {
    if (!isAuthenticated || !questionText.trim() || isAnyQueryRunning) return;

    const { finalQuestion, toolName, toolPrettyName } = prepareSubmission(questionText, forceType);
    if (!finalQuestion) return;

    if (toolName) {
      setLastToolRequest({
        name: toolName,
        prettyName: toolPrettyName || toolName,
      });
    }

    const resultIndex = results.length;

    dispatch({
      type: actionTypes.ADD_CHAT_ITEM,
      payload: { 
        question: finalQuestion, 
        isLoading: true, 
        result: "", 
        toolCalls: [],
        blocks: [],
        combinedTablesUsed: []
      }
    });

    const options = {
      databases: searchFilters.databases.join(','),
      tags: searchFilters.tags.join(','),
      allow_external_associations: allowExternalAssociations
    };

    const requestId = await processQuestion(finalQuestion, toolName, resultIndex, options);

    if (requestId) {
      setLastRequestId(requestId);
    }

    setCurrentQuestion("");
  };

  const handleSubmit = (event, forceType = null) => {
    if (event && event.preventDefault) event.preventDefault();
    submitQuestion(currentQuestion, forceType);
  };

  const handleKeyDown = (event, forceType = null) => {
    if (event.key === "Enter" && !event.shiftKey) {
      if (!isAnyQueryRunning) {
        event.preventDefault();
        handleSubmit(event, forceType);
      }
    }
  };

  const handleSendClick = (event, forceType = null) => {
    if (!isAuthenticated || isAnyQueryRunning) return;

    if (!currentQuestion.trim()) {
      textInputRef.current?.focus();
      return;
    }

    handleSubmit(event, forceType);
  };

  const handleCancelDeepQuery = () => {
    if (lastRequestId && runningDeepQueries.includes(lastRequestId)) {
      cancelDeepQuery(lastRequestId);
    }
  };

  return {
    currentQuestion,
    setCurrentQuestion,
    showFilterModal,
    setShowFilterModal,
    searchFilters,
    allowExternalAssociations,
    isDeepQueryRunning,
    isAnyQueryRunning,
    filterCount,
    textInputRef,
    handleQuestionChange,
    handleFilterSave,
    handleSubmit,
    handleKeyDown,
    handleSendClick,
    handleCancelDeepQuery,
    lastToolRequest,
    config
  };
};

export default useQuestionForm;

import { useState, useRef } from "react";
import { actionTypes } from "../reducers/chatReducer";
import { buildApiUrl } from "../api/client";

const useSDK = (dispatch, onRequestComplete, currentThreadId, onThreadIdUpdate, onLimitReached, autoOverwriteAccepted) => {
  const [isLoading, setLoading] = useState(false);
  const [runningDeepQueries, setRunningDeepQueries] = useState(new Set());
  const activeControllers = useRef(new Map()); // Map of requestId -> { controller, resultIndex }
  const requestIdCounter = useRef(0);

  const handleStream = async (url, body, resultIndex, requestId, onMessage, options) => {
    const controller = new AbortController();
    const signal = controller.signal;

    activeControllers.current.set(requestId, { controller, resultIndex });

    try {

      const isQuestion = url.includes('question');
      const fetchUrl = isQuestion ? buildApiUrl("question") : buildApiUrl(url);
      const method = isQuestion ? 'POST' : 'GET';

      const fetchOptions = {
        method,
        headers: isQuestion ? { 'Content-Type': 'application/json' } : undefined,
        body: isQuestion ? JSON.stringify(body) : undefined,
        signal
      };

      const response = await fetch(fetchUrl, fetchOptions);

      if (response.status === 409 && isQuestion) {
        const errorData = await response.json();

        if (onLimitReached) {
          onLimitReached(errorData, {
            query: body.query,
            toolName: body.tool,
            resultIndex,
            options
          });
        }

        return; 
      }

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const returnedThreadId = response.headers.get('X-Thread-ID');
      if (returnedThreadId && onThreadIdUpdate) {
        onThreadIdUpdate(returnedThreadId);
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        // Process complete lines (SSE format usually ends with \n\n)
        const lines = buffer.split('\n\n');
        buffer = lines.pop(); // Keep the incomplete part

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6);
            if (data.trim() === '[DONE]') continue; // OpenAI style, just in case

            // Check for special markers from backend if any (e.g. <STREAMOFF>)
            if (data.includes('<STREAMOFF>')) continue;

            try {
               // Check if it is a JSON object
               if (data.startsWith('{')) {
                   const payload = JSON.parse(data);
                   onMessage(payload);
               } else {

                   onMessage({ type: 'message', content: data });
               }
            } catch (e) {
               // Fallback for plain text
               onMessage({ type: 'message', content: data });
            }
          }
        }
      }

    } catch (error) {
      if (error.name === 'AbortError') {
        return;
      }
      console.error("Stream error:", error);
      const backendMessage = error.message || 'Unknown error';
      dispatch({
        type: actionTypes.ERROR_CHAT_ITEM,
        payload: {
          resultIndex,
          message: `Fatal error when connecting to chatbot backend: ${backendMessage}`,
          errorDetails: backendMessage
        }
      });
    } finally {
      activeControllers.current.delete(requestId);
      if (url.includes('deep_query')) { // Logic for deep query tracking might need adjustment based on tool usage
         // This cleanup is handled in onMessage for 'done' or explicit cancel usually
      }
      onRequestComplete(requestId);
      setLoading(false);
    }
  };

  const processQuestion = async (question, _type, resultIndex, options = {}) => {
    setLoading(true);
    const requestId = `agent_${Date.now()}_${++requestIdCounter.current}`;

    const body = {
      query: question,
      tool: _type,
      databases: options.databases,
      tags: options.tags,
      allow_external_associations: options.allow_external_associations,
      thread_id: currentThreadId,
      force_overwrite: options.force_overwrite !== undefined ? options.force_overwrite : autoOverwriteAccepted
    };

    handleStream('question', body, resultIndex, requestId, (payload) => {
      const type = payload.type;

      if (type === 'message') {
        const text = (payload.content || '').replace(/<NEWLINE>/g, '\n');
        dispatch({
          type: actionTypes.UPDATE_CHAT_ITEM_TEXT,
          payload: { resultIndex, text }
        });
      } else if (type === 'tool_start') {
        const { tool_name, tool_call_id, args } = payload;
        if (tool_name === 'deep_query') {
          setRunningDeepQueries(prev => new Set([...prev, requestId]));
        }
        dispatch({
          type: actionTypes.TOOL_CALL_START,
          payload: {
             resultIndex,
             toolCall: { toolName: tool_name, toolCallId: tool_call_id, args: args || {}, status: 'running' }
          }
        });
      } else if (type === 'tool_end') {
        const { tool_name, tool_call_id, content, artifact } = payload;
        dispatch({
            type: actionTypes.TOOL_CALL_END,
            payload: { resultIndex, toolName: tool_name, toolCallId: tool_call_id, content, artifact }
        });
        if (tool_name === 'deep_query') {
            setRunningDeepQueries(prev => {
              const next = new Set(prev);
              next.delete(requestId);
              return next;
            });
        }
      } else if (type === 'done') {
        dispatch({
            type: actionTypes.COMPLETE_CHAT_ITEM,
            payload: { resultIndex, payload }
        });
      } else if (type === 'error') {
        const rawMessage = payload.message || 'Error';
        const message = `Fatal error when connecting to chatbot backend: ${rawMessage}`;
        dispatch({
          type: actionTypes.ERROR_CHAT_ITEM,
          payload: {
            resultIndex,
            message,
            errorDetails: payload.traceback || rawMessage
          }
        });
      }
    }, options);

    return requestId;
  };

  const cancelDeepQuery = (requestId) => {
    const connection = activeControllers.current.get(requestId);
    if (connection) {
      const { controller, resultIndex } = connection;
      controller.abort();
      activeControllers.current.delete(requestId);

      dispatch({
        type: actionTypes.DELETE_CHAT_ITEM,
        payload: { resultIndex }
      });

      setRunningDeepQueries(prev => {
        const newSet = new Set(prev);
        newSet.delete(requestId);
        return newSet;
      });
      onRequestComplete(requestId);
      setLoading(false);
    }
  };

  return {
    isLoading,
    processQuestion,
    cancelDeepQuery,
    runningDeepQueries: Array.from(runningDeepQueries)
  };
};

export default useSDK;

import { useMemo, useCallback } from "react";

const normalizeString = (value) =>
  String(value || "")
    .toLowerCase()
    .replace(/\s+/g, "")
    .replace(/_/g, "")
    .replace(/@/g, "");

const useToolSelector = (config) => {
  const availableTools = useMemo(() => {
    const tools = Array.isArray(config?.chatbot_tools) ? config.chatbot_tools : [];

    return tools.filter(tool => {
      if (tool.name === 'deep_query' && !config?.enable_deep_query) return false;
      if (tool.name === 'knowledge_query' && !config?.unstructured_mode) return false;
      return true;
    });
  }, [config]);

  const resolveToolFromToken = useCallback(
    (rawToken) => {
      if (!rawToken) return null;
      const token = normalizeString(
        rawToken.startsWith("@") ? rawToken.slice(1) : rawToken
      );

      for (const tool of availableTools) {
        if (tool.name && normalizeString(tool.name) === token) return tool;
        if (Array.isArray(tool.aliases)) {
          if (
            tool.aliases.some(
              (alias) => normalizeString(alias) === token
            )
          ) {
            return tool;
          }
        }
      }
      return null;
    },
    [availableTools]
  );

  const prepareSubmission = useCallback(
    (questionText, forcedTool) => {
      const trimmedStart = questionText.replace(/^\s*/, "");
      let toolName = forcedTool || null;
      let toolPrettyName = null;
      let finalQuestion = questionText.trim();

      if (trimmedStart.startsWith("@")) {
        const match = trimmedStart.match(/^@(\S*)/);
        const token = match ? match[1] : "";
        const resolvedTool = token ? resolveToolFromToken(token) : null;

        if (resolvedTool) {
          toolName = resolvedTool.name;
          toolPrettyName = resolvedTool.pretty_name || resolvedTool.name;
          finalQuestion = questionText.replace(/^@\S+\s*/, "").trim();
        }
      }

      if (toolName && !toolPrettyName) {
        const matched = availableTools.find((tool) => tool.name === toolName);
        if (matched) {
          toolPrettyName = matched.pretty_name || matched.name;
        } else {
          toolPrettyName = toolName;
        }
      }

      return { finalQuestion, toolName, toolPrettyName };
    },
    [resolveToolFromToken, availableTools]
  );

  return {
    prepareSubmission,
  };
};

export default useToolSelector;

