"""
Contains the User class for Flask-Login integration and user state management.
"""

from flask_login import UserMixin

from utils.uniformLLM import UniformLLM
from sample_chatbot.engine.chatbot import ChatbotEngine
from sample_chatbot.engine.skills import active_skills_for_user
from sample_chatbot.services.agent_kb_bootstrap import ensure_agent_knowledge_bases
from sample_chatbot.extensions import get_unstructured_vector_store
from sample_chatbot.services.kb_registry import get_registry_for

def _normalize_instruction_entry(val):
    if isinstance(val, str):
        return {'ai_sdk': val.strip(), 'chatbot': ''}
    if isinstance(val, dict):
        return {
            'ai_sdk': (val.get('ai_sdk') or '').strip(),
            'chatbot': (val.get('chatbot') or '').strip(),
        }
    return {'ai_sdk': '', 'chatbot': ''}


def _normalize_instruction_map(payload):
    if payload is None:
        return {}
    if isinstance(payload, str):
        return {'global': _normalize_instruction_entry(payload)}
    if not isinstance(payload, dict):
        return {}
    keys = set(payload.keys())
    if keys <= {'ai_sdk', 'chatbot'}:
        return {'global': _normalize_instruction_entry(payload)}
    out = {}
    for agent_id, val in payload.items():
        out[agent_id] = _normalize_instruction_entry(val)
    return out

class User(UserMixin):
    """User model for Flask-Login integration."""

    def __init__(self, username, password, config):
        self.id = username
        self.password = password
        self._config = config

        # Security and access
        self.roles = []
        self.is_admin = False
        self.legacy_permissions_endpoint = False

        # Chatbot
        self.agent_id = config.id
        self.chatbot = None
        self.custom_instructions_map = {}
        self.user_details = ""
        self.thread_id = None

        # Synced resources
        self.synced_resources = {}
        self.partial_resources = {}
        self.user_sync_permissions = True

        # LLM preferences for different components
        self.chatbot_llm_preferences = {}
        self.ai_sdk_base_llm_preferences = {}
        self.ai_sdk_thinking_llm_preferences = {}
        self.use_base_llm_for_execution = config.use_base_llm_for_execution

        # General AI SDK preferences
        self.check_ambiguity = config.check_ambiguity

        # Cached AI SDK configuration (populated at login from /getAISDKInfo)
        self.ai_sdk_info = None

    # ---------- KB accessors (registry-backed) ----------

    def _registry(self):
        return get_registry_for(self._config)

    @property
    def chatbot_vector_store(self):
        """The single shared chatbot vector store."""
        return get_unstructured_vector_store(self._config)

    # Legacy alias used by some downstream code paths.
    @property
    def unstructured_vector_store(self):
        return self.chatbot_vector_store

    @property
    def active_csv_sources(self):
        """Collections this user has switched on for the *current* agent.

        Collections declared in the agent's YAML (knowledge_bases) are always
        active for every user of the agent, without per-user subscriptions.
        """
        registry = self._registry()
        actives = list(registry.active_for_user(self.id, self._config.id))
        for kb in self._config.knowledge_bases:
            if kb['name'] not in actives and registry.has_collection(kb['name']):
                actives.append(kb['name'])
        return actives

    @property
    def unstructured_vector_store_description(self):
        registry = self._registry()
        lines = []
        for name in self.active_csv_sources:
            meta = registry.get_collection(name) or {}
            lines.append(f"   - {name} => {meta.get('description', '')}")
        return "\n".join(lines) + ("\n" if lines else "")

    @property
    def kb_collections_map(self):
        """{collection_name: description} for the collections this user has active."""
        registry = self._registry()
        out = {}
        for name in self.active_csv_sources:
            meta = registry.get_collection(name) or {}
            out[name] = meta.get("description", "")
        return out

    def set_active_csvs(self, active_csvs):
        """Replace this (user, current-agent)'s full active-collection set.

        The cached chatbot is intentionally left in place so the user's current
        conversation (history, system prompt, kb snapshot) keeps working.
        The updated collection set will be picked up the next time the chatbot
        is rebuilt (e.g. when the user starts a new chat via set_agent_config).
        """
        if active_csvs is None:
            return
        self._registry().set_active_set(self.id, self._config.id, active_csvs)

    # ---------- the rest of the user model ----------

    def _effective_ai_sdk_instructions(self):
        if self.agent_id in self.custom_instructions_map:
            return (
                (self.custom_instructions_map[self.agent_id].get("ai_sdk") or "").strip()
            )
        return (getattr(self._config, "custom_instructions_ai_sdk", None) or "").strip()

    def _effective_chatbot_instructions(self):
        if self.agent_id in self.custom_instructions_map:
            return (
                (self.custom_instructions_map[self.agent_id].get("chatbot") or "").strip()
            )
        return (getattr(self._config, "custom_instructions_chatbot", None) or "").strip()

    def set_custom_instructions(self, user_details='', custom_instructions=None):
        """Update user profile details and optional per-agent custom instruction map."""
        self.user_details = user_details
        if custom_instructions is not None:
            self.custom_instructions_map = _normalize_instruction_map(custom_instructions)
        self.chatbot = None

    def merge_custom_instructions_for_agent(self, agent_id, patch):
        """Merge a single agent's ai_sdk / chatbot overlay (used when switching agents)."""
        if patch is None:
            return
        entry = _normalize_instruction_entry(patch)
        merged = dict(self.custom_instructions_map)
        merged[agent_id] = entry
        self.custom_instructions_map = merged
        self.chatbot = None

    def update_llm_preferences(self, llm_settings):
        """Updates LLM preferences from a dictionary containing the configurations."""
        def validate_temperature(temp):
            if temp is not None and temp != '':
                temp_float = float(temp)
                if not (0.0 <= temp_float <= 2.0):
                    raise ValueError("Temperature must be between 0.0 and 2.0")
                return temp_float
            return None

        def validate_max_tokens(tokens):
            if tokens is not None and tokens != '':
                tokens_int = int(tokens)
                if not (1024 <= tokens_int <= 20000):
                    raise ValueError("Max tokens must be between 1024 and 20000")
                return tokens_int
            return None

        def parse_and_validate(llm_data):
            if not llm_data or not any(llm_data.values()):
                return None
            prefs = {
                'provider': llm_data.get('provider') or None,
                'model': llm_data.get('model') or None,
                'temperature': validate_temperature(llm_data.get('temperature')),
                'max_tokens': validate_max_tokens(llm_data.get('max_tokens'))
            }
            return {k: v for k, v in prefs.items() if v is not None}

        chatbot_prefs = parse_and_validate(llm_settings.get('chatbot_llm'))
        if chatbot_prefs is not None:
            self.chatbot_llm_preferences = chatbot_prefs

        base_prefs = parse_and_validate(llm_settings.get('ai_sdk_base_llm'))
        if base_prefs is not None:
            self.ai_sdk_base_llm_preferences = base_prefs

        thinking_prefs = parse_and_validate(llm_settings.get('ai_sdk_thinking_llm'))
        if thinking_prefs is not None:
            self.ai_sdk_thinking_llm_preferences = thinking_prefs

        check_ambiguity = llm_settings.get('check_ambiguity')
        if check_ambiguity is not None:
           self.check_ambiguity = bool(check_ambiguity)

        use_base_llm_for_execution = llm_settings.get('use_base_llm_for_execution')
        if use_base_llm_for_execution is not None:
            self.use_base_llm_for_execution = bool(use_base_llm_for_execution)


    def get_or_create_chatbot(self):
        if not self.chatbot:
            chatbot_llm = self.get_chatbot_llm()

            base_prefs = self.ai_sdk_base_llm_preferences or {}
            base_provider = base_prefs.get('provider') or getattr(self._config, 'ai_sdk_base_llm_provider', None)
            base_model = base_prefs.get('model') or getattr(self._config, 'ai_sdk_base_llm_model', None)
            base_temp = base_prefs.get('temperature') if base_prefs.get('temperature') is not None else getattr(
                self._config, 'ai_sdk_base_llm_temperature', None)
            base_tokens = base_prefs.get('max_tokens') or getattr(self._config, 'ai_sdk_base_llm_max_tokens', None)

            ai_sdk_llm_params = {}
            if base_provider:
                ai_sdk_llm_params['llm_provider'] = base_provider
            if base_model:
                ai_sdk_llm_params['llm_model'] = base_model
            if base_temp is not None:
                ai_sdk_llm_params['llm_temperature'] = base_temp
            if base_tokens:
                ai_sdk_llm_params['llm_max_tokens'] = base_tokens

            thinking_prefs = self.ai_sdk_thinking_llm_preferences or {}
            thinking_provider = thinking_prefs.get('provider') or getattr(self._config, 'ai_sdk_thinking_llm_provider', None)
            thinking_model = thinking_prefs.get('model') or getattr(self._config, 'ai_sdk_thinking_llm_model', None)
            thinking_temp = thinking_prefs.get('temperature') if thinking_prefs.get(
                'temperature') is not None else getattr(self._config, 'ai_sdk_thinking_llm_temperature', None)
            thinking_tokens = thinking_prefs.get('max_tokens') or getattr(self._config, 'ai_sdk_thinking_llm_max_tokens', None)

            thinking_llm_params = {}
            if thinking_provider:
                thinking_llm_params['thinking_llm_provider'] = thinking_provider
            if thinking_model:
                thinking_llm_params['thinking_llm_model'] = thinking_model
            if thinking_temp is not None:
                thinking_llm_params['thinking_llm_temperature'] = thinking_temp
            if thinking_tokens:
                thinking_llm_params['thinking_llm_max_tokens'] = thinking_tokens

            ai_sdk_params = {
                **ai_sdk_llm_params,
                **thinking_llm_params,
                'check_ambiguity': self.check_ambiguity,
                'execution_model': 'base' if self._config.use_base_llm_for_execution else 'thinking'
            }

            data_agent_limit_max = self.ai_sdk_info['vql_execute_rows_limit'] if self.ai_sdk_info else 10000
            ai_sdk_params['vql_execute_rows_limit'] = data_agent_limit_max
            deep_query_allowed = self.ai_sdk_info.get("can_use_deepquery", True) if self.ai_sdk_info else True
            deepquery_enabled = self._config.deepquery_enabled and deep_query_allowed

            unstructured_mode_allowed = self._config.is_unstructured_mode_allowed_for_user(
                username=self.id,
                roles=self.roles,
                is_admin=self.is_admin,
                legacy_permissions_endpoint=self.legacy_permissions_endpoint
            )

            # Make sure the agent's declared knowledge bases exist in the
            # vector store (auto-vectorizing them on first use if enabled).
            if unstructured_mode_allowed:
                ensure_agent_knowledge_bases(self._config)

            can_manage_skills = self._config.is_skill_management_allowed_for_user(
                username=self.id,
                roles=self.roles,
                is_admin=self.is_admin,
                legacy_permissions_endpoint=self.legacy_permissions_endpoint
            )

            self.chatbot = ChatbotEngine(
                llm=chatbot_llm,
                system_prompt=self._config.system_prompt,
                api_host=self._config.ai_sdk_host,
                username=self.id,
                password=self.password,
                vector_store_provider=self._config.vector_store_provider if unstructured_mode_allowed else None,
                vector_store=self.chatbot_vector_store if unstructured_mode_allowed else None,
                user_details=self.user_details,
                enable_deepquery=deepquery_enabled,
                skills=active_skills_for_user(self.id, self._config.agent_skills),
                can_manage_skills=can_manage_skills,
                ai_sdk_custom_instructions=self._effective_ai_sdk_instructions(),
                chatbot_custom_instructions=self._effective_chatbot_instructions(),
                thread_id=self.thread_id,
                verify_ssl=self._config.ai_sdk_verify_ssl,
                ai_sdk_params=ai_sdk_params,
                data_agent_limit_max=data_agent_limit_max,
                auto_graph=self._config.auto_graph,
                kb_description=self.unstructured_vector_store_description if unstructured_mode_allowed else "",
                active_csv_sources=self.active_csv_sources if unstructured_mode_allowed else None,
                kb_collections=self.kb_collections_map if unstructured_mode_allowed else None,
                timeout=self._config.chatbot_timeout,
            )
        return self.chatbot

    def get_chatbot_llm(self):
        """Get LLM instance for chatbot based on user preferences or global defaults."""
        if self.chatbot_llm_preferences:
            provider = self.chatbot_llm_preferences.get('provider', self._config.llm_provider)
            model = self.chatbot_llm_preferences.get('model', self._config.llm_model)
            temperature = self.chatbot_llm_preferences.get('temperature', self._config.llm_temperature)
            max_tokens = self.chatbot_llm_preferences.get('max_tokens', self._config.llm_max_tokens)

            return UniformLLM(
                provider,
                model,
                temperature=temperature,
                max_tokens=max_tokens
            )
        else:
            return self._config.llm

    def set_agent_config(self, config):
        self._config = config

        self.agent_id = config.id
        self.chatbot = None
        self.user_details = ""
        self.thread_id = None

        self.chatbot_llm_preferences = {}
        self.ai_sdk_base_llm_preferences = {}
        self.ai_sdk_thinking_llm_preferences = {}

        self.check_ambiguity = config.check_ambiguity
        self.use_base_llm_for_execution = config.use_base_llm_for_execution

import os
import csv
import json
import logging

from datetime import datetime

# Upper bound for a single CSV field when reading reports (avoids multi‑GB allocations if a file is corrupt or hostile).
# Kept separate from the per-chatbot report file size so a mis-set config cannot request unbounded memory.
CSV_FIELD_HARD_CAP_BYTES = 100 * 1024 * 1024

def _csv_field_limit_bytes_for_read(report_max_size_mb):
    mb = max(1, int(report_max_size_mb or 1))
    file_budget = mb * 1024 * 1024
    return min(CSV_FIELD_HARD_CAP_BYTES, file_budget)

def _apply_csv_field_limit(limit_bytes):
    limit = int(limit_bytes)
    while limit > 0:
        try:
            csv.field_size_limit(limit)
            return
        except OverflowError:
            limit //= 10
    for fallback in (2**31 - 1, 10**9, 50 * 1024 * 1024, 10 * 1024 * 1024, 1024 * 1024):
        try:
            csv.field_size_limit(fallback)
            return
        except (OverflowError, ValueError):
            continue
    logging.warning("Could not set csv.field_size_limit; feedback CSV reads may fail on moderately large cells.")

def get_report_filename(report_max_size_mb, report_max_files, report_folder="reports", base_filename="user_report"):
    base_path = os.path.join(report_folder, base_filename)
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    report_max_size_bytes = report_max_size_mb * 1024 * 1024

    try:
        existing_files = [
            f
            for f in os.listdir(report_folder)
            if f.startswith(base_filename) and f.endswith(".csv")
        ]
    except FileNotFoundError:
        existing_files = []

    if not existing_files:
        return f"{base_path}_{timestamp}.csv"

    full_file_paths = [os.path.join(report_folder, f) for f in existing_files]

    latest_file = max(
        full_file_paths,
        key=lambda f: os.path.getmtime(f) if os.path.exists(f) else 0,
    )

    try:
        if os.path.exists(latest_file) and os.path.getsize(latest_file) >= report_max_size_bytes:
            if report_max_files > 0:
                num_to_delete = len(existing_files) - (report_max_files - 1)

                if num_to_delete > 0:
                    sorted_files = sorted(
                        full_file_paths,
                        key=lambda f: os.path.getmtime(f) if os.path.exists(f) else 0,
                    )

                    files_to_delete = sorted_files[:num_to_delete]

                    logging.info(f"Report limit ({report_max_files}) reached. Deleting {len(files_to_delete)} oldest report(s).")

                    for f_path in files_to_delete:
                        try:
                            os.remove(f_path)
                        except OSError as e:
                            logging.error(f"Error deleting old report file {f_path}: {e}")

            return f"{base_path}_{timestamp}.csv"
    except FileNotFoundError:
        return f"{base_path}_{timestamp}.csv"

    return latest_file


def write_to_report(
    report_lock,
    report_max_size_mb,
    report_max_files,
    question,
    answer,
    username,
    report_folder="reports",
    base_filename="user_report",
):
    event_type = answer.get("type")
    if event_type not in ("done", "tool_end"):
        return

    with report_lock:
        filename = get_report_filename(
            report_max_size_mb,
            report_max_files,
            report_folder,
            base_filename,
        )
        file_exists = os.path.exists(filename)

        try:
            with open(filename, "a", newline="", encoding="utf-8") as file:
                writer = csv.writer(file, delimiter=";")

                if not file_exists:
                    writer.writerow(
                        [
                            "uuid",
                            "timestamp",
                            "type",
                            "question",
                            "answer",
                            "chatbot_llm",
                            "tool_name",
                            "tool_call_id",
                            "tool_content",
                            "tool_artifact",
                            "user",
                            "feedback",
                            "feedback_details",
                        ]
                    )

                timestamp = datetime.now().isoformat()
                uuid = answer.get("uuid", "")

                if event_type == "done":
                    final_answer = answer.get("answer", "")
                    if isinstance(final_answer, str):
                        final_answer = final_answer.split("<related_question>")[0].strip()
                    else:
                        final_answer = str(final_answer)

                    chatbot_llm = answer.get("chatbot_llm", "")
                    row = [
                        uuid,
                        timestamp,
                        event_type,
                        question,
                        final_answer,
                        chatbot_llm,
                        "",
                        "",
                        "",
                        "",
                        username,
                        "not_received",
                        "",
                    ]
                else:
                    tool_name = answer.get("tool_name", "")
                    tool_call_id = answer.get("tool_call_id", "")
                    content = answer.get("content", "")
                    artifact = answer.get("artifact", "")

                    if not isinstance(content, str):
                        try:
                            content = json.dumps(content, ensure_ascii=False)
                        except (TypeError, ValueError):
                            content = str(content)

                    if not isinstance(artifact, str):
                        try:
                            artifact = json.dumps(artifact, ensure_ascii=False)
                        except (TypeError, ValueError):
                            artifact = str(artifact)

                    row = [
                        uuid,
                        timestamp,
                        event_type,
                        question,
                        "",
                        "",
                        tool_name,
                        tool_call_id,
                        content,
                        artifact,
                        username,
                        "not_received",
                        "",
                    ]

                writer.writerow(row)
        except OSError as e:
            logging.error(f"Error writing to report file {filename}: {e}")

def update_feedback_in_report(
    report_lock,
    report_max_size_mb,
    uuid,
    feedback_value,
    feedback_details,
    report_folder="reports",
    base_filename="user_report",
):
    with report_lock:
        _apply_csv_field_limit(_csv_field_limit_bytes_for_read(report_max_size_mb))
        try:
            report_files = [
                f
                for f in os.listdir(report_folder)
                if f.startswith(base_filename) and f.endswith(".csv")
            ]
        except FileNotFoundError:
            logging.error(
                f"Report directory '{report_folder}' not found during feedback update."
            )
            return {
                "success": False,
                "error": "report_directory_missing",
                "message": "Feedback could not be saved because the report directory is missing on the server.",
            }

        report_files.sort(
            key=lambda f: os.path.getmtime(os.path.join(report_folder, f))
            if os.path.exists(os.path.join(report_folder, f))
            else 0,
            reverse=True,
        )

        updated = False

        for report_file in report_files:
            filepath = os.path.join(report_folder, report_file)
            rows = []
            found_in_this_file = False

            try:
                with open(filepath, newline="", encoding="utf-8") as file:
                    reader = csv.reader(file, delimiter=";")
                    try:
                        header = next(reader)
                        rows.append(header)
                    except StopIteration:
                        continue

                    for row in reader:
                        if len(row) > 0 and row[0] == uuid:
                            while len(row) < 13:
                                row.append("")
                            row[11] = feedback_value
                            row[12] = feedback_details
                            found_in_this_file = True
                            updated = True
                        rows.append(row)

                if found_in_this_file:
                    with open(filepath, "w", newline="", encoding="utf-8") as file:
                        writer = csv.writer(file, delimiter=";")
                        writer.writerows(rows)

                    break

            except FileNotFoundError:
                logging.warning(f"Report file {filepath} disappeared during feedback update.")
                continue
            except csv.Error as e:
                basename = os.path.basename(filepath)
                err_str = str(e)
                if "field larger than field limit" in err_str:
                    logging.error(
                        f"""
Failed to update feedback for question id {uuid} because the report row reached the system's memory limit (CSV field size cap).
The user's feedback for question id {uuid} was: value={feedback_value!r}, details={feedback_details!r}.
Please update it manually in the report file {filepath}
"""
                    )
                    err_code = "report_csv_field_limit"
                else:
                    logging.error(
                        f"""
Failed to update feedback for question id {uuid} because reading the report CSV failed ({e}).
The user's feedback for question id {uuid} was: value={feedback_value!r}, details={feedback_details!r}.
Please update it manually in the report file {filepath}
"""
                    )
                    err_code = "report_csv_parse_error"
                msg = f"""
Feedback could not be saved while reading the report ({basename}): {err_str}.
Your feedback was: value={feedback_value!r}, details={feedback_details!r}.
Please update the feedback columns manually in that CSV on the server.
"""
                return {
                    "success": False,
                    "error": err_code,
                    "message": msg,
                }
            except MemoryError:
                basename = os.path.basename(filepath)
                logging.error(
                    f"""
Failed to update feedback for question id {uuid} because the report row exceeded the system's memory limit while loading the CSV.
The user's feedback for question id {uuid} was: value={feedback_value!r}, details={feedback_details!r}.
Please update it manually in the report file {filepath}
"""
                )
                msg = f"""
Feedback could not be saved because the report row is too large to process in memory ({basename}).
Your feedback was: value={feedback_value!r}, details={feedback_details!r}.
Please update the feedback columns manually in that CSV on the server.
"""
                return {
                    "success": False,
                    "error": "report_memory_limit",
                    "message": msg,
                }
            except OSError as e:
                logging.error(f"Error reading/writing report file {filepath} during feedback update: {e}")
                continue

        if not updated:
            return {
                "success": False,
                "error": "uuid_not_found",
                "message": "Failed to save feedback. No matching conversation was found in the report files.",
            }
        return {"success": True}

"""
Handles question processing and chat history endpoints.
"""

import os
import re
import uuid
import json
import logging
import threading
from flask import Blueprint, request, jsonify, Response, copy_current_request_context
from flask_login import login_required, current_user
from langchain_core.messages import HumanMessage, AIMessage, RemoveMessage, ToolMessage
from sample_chatbot.config import get_config
from sample_chatbot.services.chat_service import ChatService
from utils.database_utils import UniformCheckpointer, HistoryMetadata
from sample_chatbot.utils.helpers import generate_chat_title

chat_bp = Blueprint('chat', __name__)

HistoryMetadata.init_db()

MAX_CHATS_PER_USER = int(os.getenv("MAX_CHATS_PER_USER", 100))
MAX_MESSAGES_PER_CHAT = int(os.getenv("MAX_MESSAGES_PER_CHAT", 100))

def update_title_in_background(thread_id, user_query, uniform_llm):
    """Calls the helper and updates the DB in the background."""
    new_title = generate_chat_title(uniform_llm, user_query, session_id=thread_id)
    HistoryMetadata.rename_chat(thread_id, new_title)
    logging.info(f"Chat {thread_id} title updated to: {new_title}")

@chat_bp.route('/api/question', methods=['POST'])
@login_required
def question():
    """Process a user question and stream the response."""
    data = request.get_json()
    query = data.get('query')
    tool_name = data.get('tool')
    databases_str = data.get('databases', '')
    tags_str = data.get('tags', '')
    allow_external_associations = data.get('allow_external_associations', True)
    force_overwrite = data.get('force_overwrite', False)

    # Capture the actual user object, not the proxy
    user_obj = current_user._get_current_object()

    if not query:
        return jsonify({"error": "Missing query parameter"}), 400

    thread_id = data.get('thread_id')
    is_new_thread = not bool(thread_id)
    agent_id = user_obj.agent_id if user_obj.agent_id else 'global'

    if is_new_thread:
        chats = HistoryMetadata.get_user_chats(user_obj.id, limit=5000)
        current_chats = len(chats)

        if current_chats >= MAX_CHATS_PER_USER:
            excess = current_chats - MAX_CHATS_PER_USER + 1
            unpinned_chats = sorted([c for c in chats if not c['is_pinned']], key=lambda x: x['updated_at'])
            pinned_chats = sorted([c for c in chats if c['is_pinned']], key=lambda x: x['updated_at'])
            ordered_chats = unpinned_chats + pinned_chats

            chats_to_delete = ordered_chats[:excess]

            if not force_overwrite:
                targets = [c['title'] for c in chats_to_delete]
                return jsonify({
                    "error": "limit_reached",
                    "type": "chats",
                    "limit": MAX_CHATS_PER_USER,
                    "current": current_chats,
                    "targets_to_delete": targets
                }), 409
            else:
                for c in chats_to_delete:
                    HistoryMetadata.delete_chat(c['thread_id'])

        thread_id = str(uuid.uuid4())

        temp_title = (query[:30] + '...') if len(query) > 30 else query
        HistoryMetadata.save_new_chat(thread_id, user_obj.id, agent_id, temp_title)

        config_obj = get_config(agent_id)
        uniform_llm = config_obj.llm

        @copy_current_request_context
        def background_task():
            try:
                update_title_in_background(thread_id, query, uniform_llm)
            except Exception as e:
                logging.error(f"Error in background title generation: {e}")

        threading.Thread(target=background_task).start()

    else:
        if not HistoryMetadata.verify_ownership(thread_id, user_obj.id):
            return jsonify({"error": "Access denied to this chat"}), 403

        checkpointer = UniformCheckpointer.get_saver()
        config = {"configurable": {"thread_id": thread_id}}
        checkpoint_tuple = checkpointer.get_tuple(config)

        if checkpoint_tuple:
            state = checkpoint_tuple.checkpoint.get("channel_values", {})
            messages = state.get("messages", [])
            human_indices = [i for i, m in enumerate(messages) if isinstance(m, HumanMessage)]
            current_messages = len(human_indices)

            if current_messages >= MAX_MESSAGES_PER_CHAT:
                excess = current_messages - MAX_MESSAGES_PER_CHAT + 1

                if not force_overwrite:
                    targets = []
                    for i in range(excess):
                        raw_content = str(messages[human_indices[i]].content)

                        match = re.search(r'<user_query>([\s\S]*?)</user_query>', raw_content)
                        if match:
                            clean_content = match.group(1).strip()
                        else:
                            clean_content = raw_content

                        targets.append((clean_content[:80] + '...') if len(clean_content) > 80 else clean_content)

                    return jsonify({
                        "error": "limit_reached",
                        "type": "messages",
                        "limit": MAX_MESSAGES_PER_CHAT,
                        "current": current_messages,
                        "targets_to_delete": targets
                    }), 409
                else:
                    if len(human_indices) >= excess + 1:
                        block_to_delete = messages[0:human_indices[excess]]
                        delete_commands = [RemoveMessage(id=m.id) for m in block_to_delete]
                        chatbot = user_obj.get_or_create_chatbot()
                        chatbot.agent.update_state(config, {"messages": delete_commands})

        HistoryMetadata.save_new_chat(thread_id, user_obj.id, agent_id, query)

    config_obj = get_config(agent_id)
    chat_service = ChatService(config_obj)

    return Response(
        chat_service.process_query_stream(
            user=user_obj,
            query=query,
            tool_name=tool_name,
            vdp_databases=databases_str,
            vdp_tags=tags_str,
            allow_external_associations=allow_external_associations,
            thread_id=thread_id,
            is_new_thread=is_new_thread
        ),
        mimetype='text/event-stream',
        headers={'X-Thread-ID': thread_id}
    )

@chat_bp.route('/api/history', methods=['GET'])
@login_required
def list_history():
    user_obj = current_user._get_current_object()
    limit = request.args.get('limit', 20, type=int)
    offset = request.args.get('offset', 0, type=int)
    search_query = request.args.get('q', '', type=str)

    chats = HistoryMetadata.get_user_chats(user_obj.id, limit=limit, offset=offset, search_query=search_query)
    return jsonify({"chats": chats})

@chat_bp.route('/api/history/<thread_id>', methods=['PUT'])
@login_required
def rename_history(thread_id):
    if not HistoryMetadata.verify_ownership(thread_id, current_user.id):
        return jsonify({"error": "Access denied"}), 403

    data = request.get_json()
    new_title = data.get('title')
    if new_title:
        HistoryMetadata.rename_chat(thread_id, new_title)
    return jsonify({"success": True})

@chat_bp.route('/api/history/<thread_id>/pin', methods=['PUT'])
@login_required
def pin_history(thread_id):
    if not HistoryMetadata.verify_ownership(thread_id, current_user.id):
        return jsonify({"error": "Access denied"}), 403

    data = request.get_json()
    is_pinned = data.get('is_pinned', False)
    HistoryMetadata.pin_chat(thread_id, is_pinned)
    return jsonify({"success": True})

@chat_bp.route('/api/history/<thread_id>', methods=['DELETE'])
@login_required
def delete_history(thread_id):
    if not HistoryMetadata.verify_ownership(thread_id, current_user.id):
        return jsonify({"error": "Access denied"}), 403

    HistoryMetadata.delete_chat(thread_id)
    return jsonify({"success": True})

@chat_bp.route('/api/history/<thread_id>/export', methods=['GET'])
@login_required
def export_history(thread_id):
    if not HistoryMetadata.verify_ownership(thread_id, current_user.id):
        return jsonify({"error": "Access denied"}), 403

    checkpointer = UniformCheckpointer.get_saver()
    config = {"configurable": {"thread_id": thread_id}}
    checkpoint_tuple = checkpointer.get_tuple(config)

    if not checkpoint_tuple:
        return jsonify({"error": "History not found for this thread"}), 404

    state = checkpoint_tuple.checkpoint.get("channel_values", {})
    messages = state.get("messages", [])

    export_data = []
    current_turn_uuid = None

    for msg in messages:
        if msg.type in ['human', 'user']:
            current_turn_uuid = getattr(msg, 'id', None)

        content = msg.content
        if isinstance(content, list):
            text_parts = [c.get("text", "") for c in content if c.get("type") == "text"]
            content_str = "".join(text_parts)
        else:
            content_str = str(content)

        if msg.type == 'ai' and (content_str.strip().startswith('[{') or 'tool_calls' in content_str):
            content_str = ""

        tool_calls = getattr(msg, 'tool_calls', [])
        tool_call_id = getattr(msg, 'tool_call_id', None)
        tool_name = getattr(msg, 'name', None)
        artifact = getattr(msg, 'artifact', None)

        chatbot_llm = None
        is_imported = False

        if msg.type == 'ai' and hasattr(msg, 'response_metadata'):
            metadata = msg.response_metadata
            chatbot_llm = metadata.get('model_name') or metadata.get('model') or metadata.get('model_id')
            is_imported = metadata.get('imported', False)

        export_data.append({
            "uuid": current_turn_uuid,
            "role": msg.type,
            "content": content_str,
            "tool_calls": tool_calls,
            "tool_call_id": tool_call_id,
            "tool_name": tool_name,
            "artifact": artifact,
            "chatbot_llm": chatbot_llm,
            "is_imported": is_imported
        })

    chats = HistoryMetadata.get_user_chats(current_user.id, limit=100)
    current_title = next((c['title'] for c in chats if c['thread_id'] == thread_id), "Chat Export")

    return jsonify({
        "title": current_title,
        "thread_id": thread_id,
        "total_messages": len(export_data),
        "messages": export_data
    })

@chat_bp.route('/api/history/import', methods=['POST'])
@login_required
def import_history():
    if 'file' not in request.files:
        return jsonify({"error": "No file uploaded"}), 400

    file = request.files['file']
    force_overwrite = request.form.get('force_overwrite') == 'true'

    try:
        user_obj = current_user._get_current_object()
        agent_id = user_obj.agent_id if user_obj.agent_id else 'global'
        chats = HistoryMetadata.get_user_chats(user_obj.id, limit=5000)
        current_chats = len(chats)

        if current_chats >= MAX_CHATS_PER_USER:
            excess = current_chats - MAX_CHATS_PER_USER + 1
            unpinned_chats = sorted([c for c in chats if not c['is_pinned']], key=lambda x: x['updated_at'])
            pinned_chats = sorted([c for c in chats if c['is_pinned']], key=lambda x: x['updated_at'])
            ordered_chats = unpinned_chats + pinned_chats

            chats_to_delete = ordered_chats[:excess]

            if not force_overwrite:
                targets = [c['title'] for c in chats_to_delete]
                return jsonify({
                    "error": "limit_reached",
                    "type": "chats",
                    "limit": MAX_CHATS_PER_USER,
                    "current": current_chats,
                    "targets_to_delete": targets
                }), 409
            else:
                for c in chats_to_delete:
                    HistoryMetadata.delete_chat(c['thread_id'])

        data = json.load(file)
        thread_id = str(uuid.uuid4())

        chatbot = user_obj.get_or_create_chatbot()
        messages = []

        for msg in data.get('messages', []):
            role = msg.get('role')
            content = msg.get('content', '')
            if role in ['human', 'user']:
                messages.append(HumanMessage(content=content))
            elif role in ['ai', 'assistant']:
                kwargs = {'content': content}
                kwargs['response_metadata'] = {'imported': True}
                chatbot_llm = msg.get('chatbot_llm')
                if chatbot_llm:
                    kwargs['response_metadata']['model_name'] = chatbot_llm

                tool_calls = msg.get('tool_calls')
                if tool_calls:
                    kwargs['tool_calls'] = tool_calls

                messages.append(AIMessage(**kwargs))

            elif role == 'tool':
                kwargs = {
                    'content': content,
                    'tool_call_id': msg.get('tool_call_id', ''),
                    'name': msg.get('tool_name', 'tool')
                }
                artifact = msg.get('artifact')
                if artifact:
                    kwargs['artifact'] = artifact

                messages.append(ToolMessage(**kwargs))

        if messages:
            chatbot.agent.update_state({"configurable": {"thread_id": thread_id}}, {"messages": messages})

        title = data.get('title')
        if not title:
            first_q = next((m.get('content', '') for m in data.get('messages', []) if m.get('role') in ['human', 'user']), "Imported Chat")
            title = (first_q[:30] + '...') if len(first_q) > 30 else first_q
        HistoryMetadata.save_new_chat(thread_id, user_obj.id, agent_id, title)

        return jsonify({
            "success": True,
            "thread_id": thread_id,
            "agent_id": agent_id,
            "title": title
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@chat_bp.route('/api/clear_history', methods=['POST'])
@login_required
def clear_history():
    """Clear the chat history for the current user."""
    current_user.chatbot = None
    return jsonify({"message": f"Chat history cleared for user {current_user.id}"})

"""
Knowledge-base / CSV management endpoints.

The KB is one shared vector store per chatbot (agent). All registered
collections live in that store; per-user activation is tracked in a special
config doc via KBRegistry. Users see every collection in the chatbot — they
subscribe (activate) the ones they want included in their knowledge_query.
"""

import io
import os
import re
import json
import logging

from flask import Blueprint, request, jsonify, current_app, send_file
from flask_login import login_required, current_user

from utils.utils import delete_documents_by_database_name
from sample_chatbot.services.csv_service import CSVService
from sample_chatbot.services.kb_registry import get_registry_for
from sample_chatbot.extensions import get_unstructured_vector_store
from sample_chatbot.utils.csv_utils import (
    collection_to_csv_bytes,
    csv_to_documents,
    detect_csv_delimiter,
    generate_csv_description,
    validate_csv_path,
)

logger = logging.getLogger(__name__)

csv_bp = Blueprint('csv', __name__)

@csv_bp.before_request
def check_csv_permissions():
    """
    Intercepts ALL calls to /api/csv/* and blocks them
    if the user lacks the required roles or permissions for unstructured mode.
    """
    if request.method == 'OPTIONS':
        return

    if not current_user.is_authenticated:
        return

    user = current_user._get_current_object()
    config = user._config

    # Evaluate if the user is allowed to use the CSV
    if not config.is_unstructured_mode_allowed_for_user(
        username=user.id,
        roles=getattr(user, 'roles', []),
        is_admin=getattr(user, 'is_admin', False),
        legacy_permissions_endpoint=getattr(user, 'legacy_permissions_endpoint', False)
    ):
        logger.warning(f"[Security] User '{user.id}' attempted to access '{request.path}' without CSV permissions.")
        return jsonify({"success": False, "error": "You do not have permission to use the CSV Knowledge Base."}), 403

def get_csv_service():
    return CSVService(current_app.config.get('UPLOAD_FOLDER', 'uploads'))

def _user():
    """Resolve the underlying user (not the LocalProxy)."""
    return current_user._get_current_object()

def _present_source(meta, user, agent_id):
    """Shape a registry entry for the API."""
    csv_path = meta.get("csv_path") or ""
    path_valid, _ = validate_csv_path(csv_path) if csv_path else (False, None)
    active_by_user = meta.get("active_by_user") or {}
    user_agents = active_by_user.get(user.id) or []
    can_subscribe = _can_subscribe(meta, user)
    return {
        "source_name": meta["name"],
        "description": meta.get("description", ""),
        "delimiter": meta.get("delimiter", ";"),
        "document_count": meta.get("num_rows", 0),
        "last_vectorized": meta.get("last_vectorized"),
        # `active` is whether this collection is on for THIS user on THIS agent.
        # If the user cannot subscribe (e.g. admin viewing someone else's
        # private collection) it's never active regardless of registry state.
        "active": can_subscribe and (agent_id in user_agents),
        "owner": meta.get("owner"),
        "is_owner": meta.get("owner") == user.id,
        "vectorized_columns": meta.get("vectorized_columns", []),
        "private": bool(meta.get("private", False)),
        "path_valid": path_valid,
        # Per-row capability flags so the UI can render the right controls.
        "can_subscribe": can_subscribe,
        "can_delete": _can_delete(meta, user),
        "can_edit": _can_edit(meta, user),
        "can_make_public": _can_make_public(meta, user),
        "can_make_private": _can_make_private(meta, user),
    }


def _is_admin(user):
    return bool(getattr(user, "is_admin", False))


def _is_visible_to(meta, user):
    """Public collections are visible to everyone; private ones to their owner
    AND to admins (admins see them so they can clean them up)."""
    if not meta.get("private"):
        return True
    if meta.get("owner") == user.id:
        return True
    return _is_admin(user)


def _can_subscribe(meta, user):
    """May this user activate/deactivate or download this collection?"""
    if not meta.get("private"):
        return True
    return meta.get("owner") == user.id


def _can_delete(meta, user):
    """Owner or any admin may delete a collection."""
    if meta.get("owner") == user.id:
        return True
    return _is_admin(user)


def _can_edit(meta, user):
    """Description edits — owner only (same intent as before)."""
    return meta.get("owner") == user.id


def _can_make_public(meta, user):
    """Toggling a collection to public requires admin + ownership."""
    return _is_admin(user) and meta.get("owner") == user.id


def _can_make_private(meta, user):
    """Owner may always make their own collection private."""
    return meta.get("owner") == user.id


# Collection names are used as identifiers in the vector store, in metadata
# filters, in URLs (e.g. /api/csv/download/<name>) and in the system prompt;
# we want them safe across all of those layers.
_SOURCE_NAME_RE = re.compile(r"^[A-Za-z0-9_.\-]{1,80}$")


def _validate_source_name(name):
    """Return (ok_name, error_message)."""
    if not name or not isinstance(name, str):
        return None, "source_name is required"
    if not _SOURCE_NAME_RE.match(name):
        return None, (
            "source_name must be 1-80 characters and may only contain letters, "
            "digits, underscore, hyphen, or dot."
        )
    if ".." in name or name in {".", ".."}:
        return None, "source_name cannot contain '..'"
    return name, None

@csv_bp.route('/api/csv/list', methods=['GET'])
@login_required
def list_csv_sources():
    user = _user()
    agent_id = user._config.id
    registry = get_registry_for(user._config)
    collections = registry.list_collections()
    sources = [
        _present_source(meta, user, agent_id)
        for meta in collections.values()
        if _is_visible_to(meta, user)
    ]
    sources.sort(key=lambda s: s["source_name"])
    active_sources = [s["source_name"] for s in sources if s["active"]]
    logger.info(f"[CSV] '{user.id}' on agent '{agent_id}': {len(sources)} collections, {len(active_sources)} active")
    return jsonify({
        "success": True,
        "sources": sources,
        "active_sources": active_sources,
        "agent_id": agent_id,
        "current_user_is_admin": _is_admin(user),
    }), 200


@csv_bp.route('/api/csv/scan', methods=['GET'])
@login_required
def scan_csv_folder():
    """Files in sample_data/unstructured/ that aren't registered yet."""
    user = _user()
    registry = get_registry_for(user._config)
    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    scan_folder = os.path.join(base_dir, 'sample_data', 'unstructured')

    if not os.path.exists(scan_folder):
        return jsonify({"success": True, "files": [], "message": "Scan folder does not exist"}), 200

    existing = set(registry.list_collections().keys())
    scanned = []
    try:
        for filename in os.listdir(scan_folder):
            if not filename.lower().endswith('.csv'):
                continue
            source_name = os.path.splitext(filename)[0]
            if source_name in existing:
                continue
            scanned.append({
                "source_name": source_name,
                "path": os.path.join(scan_folder, filename),
                "filename": filename,
            })
    except Exception as e:
        logger.exception(f"[CSV] Error scanning folder {scan_folder}: {e}")
        return jsonify({"success": False, "error": f"Error scanning folder: {str(e)}"}), 500

    return jsonify({"success": True, "files": scanned, "scan_folder": scan_folder}), 200

@csv_bp.route('/api/csv/preview', methods=['POST'])
@login_required
def preview_csv():
    """Return columns + sample rows so the UI can offer the multi-select."""
    csv_service = get_csv_service()
    if 'file' in request.files:
        file = request.files['file']
        if file.filename == '':
            return jsonify({"success": False, "error": "No file selected"}), 400
        file_path, is_temp = csv_service.save_temp_file(file)
    else:
        data = request.json or {}
        file_path = data.get('path')
        is_temp = False
        if not file_path:
            return jsonify({"success": False, "error": "Either 'file' or 'path' is required"}), 400

    try:
        result = csv_service.get_preview(file_path, num_rows=5, allow_temp=is_temp)
        return jsonify(result), 200 if result.get("success") else 400
    finally:
        if is_temp:
            csv_service.cleanup_temp_file(file_path)

@csv_bp.route('/api/csv/generate_description', methods=['POST'])
@login_required
def generate_csv_description_endpoint():
    user = _user()
    llm = user.get_chatbot_llm()
    csv_service = get_csv_service()

    vectorized_columns = None
    if 'file' in request.files:
        file = request.files['file']
        if file.filename == '':
            return jsonify({"success": False, "error": "No file selected"}), 400
        file_path, is_temp = csv_service.save_temp_file(file)
        delimiter = request.form.get('delimiter')
        vectorized_columns = _parse_columns(request.form.get('vectorized_columns'))
    else:
        data = request.json or {}
        file_path = data.get('path')
        delimiter = data.get('delimiter')
        is_temp = False
        if not file_path:
            return jsonify({"success": False, "error": "Either 'file' or 'path' is required"}), 400
        vectorized_columns = _parse_columns(data.get('vectorized_columns'))

    try:
        result = csv_service.generate_description(
            llm, file_path, delimiter, allow_temp=is_temp,
            vectorized_columns=vectorized_columns,
        )
        return jsonify(result), 200 if result.get("success") else 400
    finally:
        if is_temp:
            csv_service.cleanup_temp_file(file_path)

def _parse_columns(value):
    if value is None:
        return None
    if isinstance(value, list):
        return [str(c) for c in value if c]
    if isinstance(value, str):
        try:
            decoded = json.loads(value)
            if isinstance(decoded, list):
                return [str(c) for c in decoded if c]
        except ValueError:
            return [c.strip() for c in value.split(",") if c.strip()]
    return None


@csv_bp.route('/api/csv/add', methods=['POST'])
@login_required
def add_csv_source():
    """
    Register a new collection in the chatbot's KB. If a collection with the
    same name already exists the request is rejected (collision detection).
    """
    user = _user()
    config = user._config
    registry = get_registry_for(config)
    store = get_unstructured_vector_store(config)
    csv_service = get_csv_service()

    def _truthy(val, default=False):
        if isinstance(val, bool):
            return val
        if val is None:
            return default
        return str(val).lower() in ("1", "true", "yes", "on")

    try:
        if 'file' in request.files:
            file = request.files['file']
            if file.filename == '':
                return jsonify({"success": False, "error": "No file selected"}), 400
            file_path = csv_service.save_uploaded_file(file)
            raw_source_name = request.form.get('source_name') or os.path.splitext(file.filename)[0]
            auto_detect = request.form.get('auto_detect_delimiter', 'true').lower() == 'true'
            auto_describe = request.form.get('auto_generate_description', 'false').lower() == 'true'
            delimiter_arg = request.form.get('delimiter', ';')
            description_arg = request.form.get('description', '')
            vectorized_columns = _parse_columns(request.form.get('vectorized_columns'))
            private = _truthy(request.form.get('private'), default=False)
        else:
            data = request.json or {}
            file_path = data.get('path')
            if not file_path:
                return jsonify({"success": False, "error": "Either 'file' or 'path' is required"}), 400
            raw_source_name = data.get('source_name') or os.path.splitext(os.path.basename(file_path))[0]
            auto_detect = data.get('auto_detect_delimiter', True)
            auto_describe = data.get('auto_generate_description', False)
            delimiter_arg = data.get('delimiter', ';')
            description_arg = data.get('description', '')
            vectorized_columns = _parse_columns(data.get('vectorized_columns'))
            private = _truthy(data.get('private'), default=False)

        # The path must always be inside an allowed root (uploads/ or
        # sample_data/unstructured/) regardless of which branch we came from.
        path_ok, path_err = validate_csv_path(file_path)
        if not path_ok:
            return jsonify({"success": False, "error": path_err}), 400

        # Stop early on names that would break URL routing, metadata filters
        # or the system prompt.
        source_name, name_err = _validate_source_name(raw_source_name)
        if name_err:
            return jsonify({"success": False, "error": name_err}), 400

        delimiter = detect_csv_delimiter(file_path) if auto_detect else delimiter_arg
        description = (generate_csv_description(user.get_chatbot_llm(), file_path, delimiter,
                                                vectorized_columns=vectorized_columns)
                       if auto_describe else description_arg)

        if not description:
            return jsonify({"success": False, "error": "Description is required"}), 400

        if registry.has_collection(source_name):
            return jsonify({
                "success": False,
                "error": f"A collection named '{source_name}' already exists in this chatbot. "
                         f"Rename your CSV or activate the existing one.",
            }), 409

        # Non-admin users can only create private collections.
        if not _is_admin(user) and not private:
            logger.info(f"[CSV] forcing private=True for non-admin user '{user.id}'")
            private = True

        docs = csv_to_documents(
            file_path,
            delimiter=delimiter,
            source_name=source_name,
            vectorized_columns=vectorized_columns,
            embeddings=store.embeddings,
        )
        if not docs:
            return jsonify({"success": False, "error": "Failed to create documents from CSV"}), 400

        logger.info(f"[CSV] User '{user.id}' adding collection '{source_name}' ({len(docs)} rows)")
        store.add_views(docs, parallel=True)

        # Re-derive the actually vectorized columns from the first doc (in case
        # the request list referenced columns that don't exist in the CSV).
        actual_columns = json.loads(docs[0].metadata.get("vectorized_columns") or "[]")

        meta = registry.register_collection(
            name=source_name,
            csv_path=file_path,
            description=description,
            delimiter=delimiter,
            vectorized_columns=actual_columns,
            owner=user.id,
            num_rows=len(docs),
            auto_activate_for=user.id,
            auto_activate_agent=user._config.id,
            private=private,
        )

        user.chatbot = None

        return jsonify({
            "success": True,
            "source_name": source_name,
            "metadata": _present_source(meta, user, user._config.id),
        }), 200
    except Exception as e:  # noqa: BLE001
        logger.exception("[CSV] add_csv_source failed")
        return jsonify({"success": False, "error": f"Could not add CSV: {e}"}), 400


# --------------------------------------------------------------------------- delete

@csv_bp.route('/api/csv/delete/<source_name>', methods=['DELETE'])
@login_required
def delete_csv_source(source_name):
    """Only the owner may delete the underlying collection."""
    user = _user()
    config = user._config
    registry = get_registry_for(config)
    store = get_unstructured_vector_store(config)
    data = request.json or {}
    delete_file = data.get('delete_file', False)

    meta = registry.get_collection(source_name)
    if meta is None:
        return jsonify({"success": False, "error": f"Source '{source_name}' not found"}), 404
    if not _can_delete(meta, user):
        return jsonify({
            "success": False,
            "error": f"Only the owner ('{meta.get('owner')}') or an admin can delete this collection. "
                     f"Deactivate it instead.",
        }), 403

    deleted = delete_documents_by_database_name(store, [source_name])
    logger.info(f"[CSV] Deleted {deleted} docs for collection '{source_name}'")
    registry.delete_collection(source_name)

    if delete_file:
        path = meta.get("csv_path")
        if path:
            try:
                if os.path.exists(path):
                    os.remove(path)
            except Exception as e:
                logger.warning(f"Could not delete CSV file: {e}")

    user.chatbot = None

    return jsonify({"success": True}), 200


# --------------------------------------------------------------------------- activate

@csv_bp.route('/api/csv/activate', methods=['POST'])
@login_required
def activate_csv_sources():
    user = _user()
    registry = get_registry_for(user._config)
    data = request.json or {}
    source_name = data.get('source_name')
    active = bool(data.get('active', True))
    if not source_name:
        return jsonify({"success": False, "error": "source_name is required"}), 400

    existing = registry.get_collection(source_name)
    if existing is None or not _is_visible_to(existing, user):
        return jsonify({"success": False, "error": f"Source '{source_name}' not found"}), 404
    if not _can_subscribe(existing, user):
        return jsonify({
            "success": False,
            "error": "You can't activate this collection. It belongs to another user and is private.",
        }), 403

    agent_id = user._config.id
    meta = registry.set_active(source_name, user.id, agent_id, active)
    if meta is None:
        return jsonify({"success": False, "error": f"Source '{source_name}' not found"}), 404

    user.chatbot = None

    return jsonify({
        "success": True,
        "source_name": source_name,
        "active": active,
        "agent_id": agent_id,
        "active_sources": registry.active_for_user(user.id, agent_id),
    }), 200


# --------------------------------------------------------------------------- description

@csv_bp.route('/api/csv/update_description', methods=['POST'])
@login_required
def update_csv_description():
    """Only the owner can rewrite the description."""
    user = _user()
    registry = get_registry_for(user._config)
    data = request.json or {}
    source_name = data.get('source_name')
    description = (data.get('description') or '').strip()
    if not source_name:
        return jsonify({"success": False, "error": "source_name is required"}), 400
    if not description:
        return jsonify({"success": False, "error": "description is required"}), 400

    meta = registry.get_collection(source_name)
    if meta is None:
        return jsonify({"success": False, "error": f"Source '{source_name}' not found"}), 404
    if meta.get("owner") and meta["owner"] != user.id:
        return jsonify({"success": False, "error": "Only the owner can edit the description."}), 403

    registry.update_description(source_name, description)
    return jsonify({"success": True, "description": description}), 200


# --------------------------------------------------------------------------- access

@csv_bp.route('/api/csv/set_private', methods=['POST'])
@login_required
def set_csv_private():
    """Owner-only: toggle the private flag of a collection."""
    user = _user()
    registry = get_registry_for(user._config)
    data = request.json or {}
    source_name = data.get('source_name')
    private = bool(data.get('private'))
    if not source_name:
        return jsonify({"success": False, "error": "source_name is required"}), 400

    meta = registry.get_collection(source_name)
    if meta is None:
        return jsonify({"success": False, "error": f"Source '{source_name}' not found"}), 404
    if meta.get("owner") != user.id:
        return jsonify({"success": False, "error": "Only the owner can change visibility."}), 403
    # Making a collection public is an admin-only action.
    if not private and not _is_admin(user):
        return jsonify({
            "success": False,
            "error": "Only an admin can publish a collection. You can keep it private.",
        }), 403

    updated = registry.set_private(source_name, private)
    return jsonify({"success": True, "metadata": _present_source(updated, user, user._config.id)}), 200

# --------------------------------------------------------------------------- download

@csv_bp.route('/api/csv/download/<source_name>', methods=['GET'])
@login_required
def download_csv(source_name):
    """Return the CSV with an extra `embedding` column reconstructed from the vector store."""
    user = _user()
    config = user._config
    registry = get_registry_for(config)
    store = get_unstructured_vector_store(config)

    meta = registry.get_collection(source_name)
    if meta is None or not _is_visible_to(meta, user):
        return jsonify({"success": False, "error": f"Source '{source_name}' not found"}), 404
    # Admins can see other people's private collections so they can delete
    # them, but they can't download the contents.
    if not _can_subscribe(meta, user):
        return jsonify({
            "success": False,
            "error": "You don't have access to download this private collection.",
        }), 403

    num_rows = int(meta.get("num_rows") or 0)
    if num_rows == 0:
        return jsonify({"success": False, "error": "Collection has no rows"}), 400

    csv_bytes = collection_to_csv_bytes(store, source_name, num_rows)
    if not csv_bytes:
        return jsonify({"success": False, "error": "No rows could be reconstructed"}), 500

    return send_file(
        io.BytesIO(csv_bytes),
        mimetype="text/csv",
        as_attachment=True,
        download_name=f"{source_name}_with_embeddings.csv",
    )

"""
Handles DeepQuery report generation endpoints.
"""

import logging
import requests

from flask import Blueprint, request, jsonify
from flask_login import login_required, current_user

from sample_chatbot.config import get_config

deepquery_bp = Blueprint('deepquery', __name__)

@deepquery_bp.route('/api/generate_report', methods=['POST'])
@login_required
def generate_report():
    """Generate an HTML report from DeepQuery metadata by calling the generateDeepQueryReport endpoint."""

    # Capture the actual user object, not the proxy
    user_obj = current_user._get_current_object()
    config = get_config(user_obj.agent_id)

    try:
        data = request.json
        deepquery_metadata = data.get('deepquery_metadata')
        color_palette = data.get('color_palette', 'red')

        if not deepquery_metadata:
            return jsonify({"error": "Missing deepquery_metadata"}), 400

        # Make request to the generateDeepQueryReport endpoint
        auth = (config.ai_sdk_username, config.ai_sdk_password)
        response = requests.post(
            f"{config.ai_sdk_host}/generateDeepQueryReport",
            json={
                "deepquery_metadata": deepquery_metadata,
                "color_palette": color_palette
            },
            auth=auth,
            verify=config.ai_sdk_verify_ssl,
            timeout=600
        )

        if response.status_code == 200:
            return jsonify(response.json()), 200
        else:
            return jsonify({
                "error": f"Report generation failed with status {response.status_code}"
            }), response.status_code

    except requests.exceptions.Timeout:
        return jsonify({"error": "Report generation timeout"}), 504
    except requests.exceptions.RequestException as e:
        return jsonify({"error": f"Request failed: {str(e)}"}), 500
    except Exception as e:
        logging.error(f"Error in generate_report: {str(e)}")
        return jsonify({"error": f"Internal server error: {str(e)}"}), 500

"""
Handles static file serving for the React frontend.
"""

import os

from flask import Blueprint, send_from_directory, current_app

frontend_bp = Blueprint('frontend', __name__)

@frontend_bp.route('/', defaults={'path': ''})
@frontend_bp.route('/<path:path>')
def serve_frontend(path):
    """Serve the React frontend application."""
    static_folder = current_app.static_folder

    if path != "" and os.path.exists(os.path.join(static_folder, path)):
        return send_from_directory(static_folder, path)
    else:
        return send_from_directory(static_folder, 'index.html')

"""
Contains request/response middleware for blueprints.
"""

from flask import request
from flask_login import current_user
from utils.utils import generate_transaction_id
from utils.logging_utils import transaction_id_var, username_var

def register_middleware(blueprint):
    """
    Register middleware on a blueprint.

    Args:
        blueprint: Flask Blueprint instance
    """

    @blueprint.before_request
    def set_logging_context():
        """Set transaction ID and username for the request context."""
        transaction_id_var.set(generate_transaction_id())
        username = "anonymous"

        if current_user and current_user.is_authenticated:
            username = current_user.id

        elif request.path.endswith('/login') and request.is_json:
            data = request.json or {}
            if data.get('username'):
                username = data.get('username')

        username_var.set(username)

    @blueprint.after_request
    def add_transaction_id_after_request(response):
        """Add the transaction ID to the response headers."""
        response.headers['X-Transaction-ID'] = transaction_id_var.get()
        return response

"""
Handles user settings, custom instructions, and LLM configuration endpoints.
"""

from flask import Blueprint, request, jsonify
