@settings_bp.route('/api/reset_llm_settings', methods=['POST'])
@login_required
def reset_llm_settings():
    """Reset all user LLM preferences back to server defaults."""
    agent_id = 'global' if not current_user.is_authenticated else current_user.agent_id

    config = get_config(agent_id)

    if not config.user_edit_llm:
        return jsonify({"error": "LLM editing is not enabled"}), 403

    # Determine which component to reset based on the request body
    data = request.json or {}
    component = data.get('component', 'all')

    if component in ('chatbot', 'all'):
        current_user.chatbot_llm_preferences = {}

    if component in ('ai_sdk', 'all'):
        current_user.ai_sdk_base_llm_preferences = {}
        if getattr(config, 'ai_sdk_base_llm_model', None):
            current_user.ai_sdk_base_llm_preferences = {
                'provider': config.ai_sdk_base_llm_provider,
                'model': config.ai_sdk_base_llm_model,
                'temperature': config.ai_sdk_base_llm_temperature,
                'max_tokens': config.ai_sdk_base_llm_max_tokens
            }

        current_user.ai_sdk_thinking_llm_preferences = {}
        if getattr(config, 'ai_sdk_thinking_llm_model', None):
            current_user.ai_sdk_thinking_llm_preferences = {
                'provider': config.ai_sdk_thinking_llm_provider,
                'model': config.ai_sdk_thinking_llm_model,
                'temperature': config.ai_sdk_thinking_llm_temperature,
                'max_tokens': config.ai_sdk_thinking_llm_max_tokens
            }

        current_user.check_ambiguity = config.check_ambiguity

    # Reset chatbot to force recreation with default settings
    current_user.chatbot = None

    return jsonify({"message": "LLM settings reset to defaults"}), 200


@settings_bp.route('/api/update_llm_settings', methods=['POST'])
@login_required
def update_llm_settings():
    """Update user's LLM preferences."""
    agent_id = 'global' if not current_user.is_authenticated else current_user.agent_id

    config = get_config(agent_id)

    if not config.user_edit_llm:
        return jsonify({"error": "LLM editing is not enabled"}), 403

    try:
        data = request.json

        current_user.update_llm_preferences(data)

        # Reset chatbot to force recreation with new LLM settings
        current_user.chatbot = None

        return jsonify({"message": "LLM settings updated successfully"}), 200

    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    except Exception as e:
        return jsonify({"error": f"Invalid input: {str(e)}"}), 400

"""
Skills management endpoints.

System skills live on disk under the AI SDK skills/ directory and are shared
by every user; personal skills are created/uploaded per user and stored in the
same database as the conversation history. Every logged-in user can list and
read the skills that apply to them, activate/deactivate them individually, and
manage their own personal skills. System skill files themselves are managed on
disk (or via the chat tools by authorized users), not through these endpoints.
"""

import logging

from flask import Blueprint, request, jsonify
from flask_login import login_required, current_user

from utils.database_utils import UserSkills
from sample_chatbot.engine import skills as skills_engine
from sample_chatbot.engine.skills import SkillError

logger = logging.getLogger(__name__)

skills_bp = Blueprint('skills', __name__)

UserSkills.init_db()


def _user():
    """Resolve the underlying user (not the LocalProxy)."""
    return current_user._get_current_object()


def _invalidate_chatbot(user):
    """Force the engine to rebuild so the system prompt picks up skill changes."""
    user.chatbot = None


@skills_bp.route('/api/skills/list', methods=['GET'])
@login_required
def list_skills():
    """List the skills that apply to the current user (system + personal)."""
    user = _user()
    merged = skills_engine.discover_skills_for_user(user.id, user._config.agent_skills)
    skills_list = [
        {
            "skill_name": name,
            "description": meta["description"],
            "references": meta["references"],
            "scope": meta["scope"],
            "active": meta["active"],
        }
        for name, meta in merged.items()
    ]
    return jsonify({
        "success": True,
        "skills": skills_list,
        "can_manage_skills": user._config.is_skill_management_allowed_for_user(
            username=user.id,
            roles=getattr(user, 'roles', []),
            is_admin=getattr(user, 'is_admin', False),
            legacy_permissions_endpoint=getattr(user, 'legacy_permissions_endpoint', False),
        ),
    })


@skills_bp.route('/api/skills/read/<skill_name>', methods=['GET'])
@login_required
def read_skill(skill_name):
    """Return the full content of one of the user's skills (personal or system)."""
    user = _user()
    try:
        # Only expose skills that actually apply to this user/agent.
        merged = skills_engine.discover_skills_for_user(user.id, user._config.agent_skills)
        if skill_name not in merged:
            return jsonify({"success": False, "error": f"Skill '{skill_name}' was not found."}), 404
        content = skills_engine.read_skill_for_user(user.id, skill_name)
        return jsonify({
            "success": True,
            "skill_name": skill_name,
            "scope": merged[skill_name]["scope"],
            "content": content,
        })
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400


@skills_bp.route('/api/skills/create', methods=['POST'])
@login_required
def create_skill():
    """Create (or upload) a personal skill for the current user."""
    user = _user()
    data = request.get_json() or {}
    skill_name = (data.get('skill_name') or '').strip()
    content = data.get('content') or ''
    try:
        skills_engine.create_personal_skill(user.id, skill_name, content)
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    _invalidate_chatbot(user)
    logger.info(f"User '{user.id}' created personal skill '{skill_name}'.")
    return jsonify({"success": True, "skill_name": skill_name, "scope": "personal"})


@skills_bp.route('/api/skills/update/<skill_name>', methods=['PUT'])
@login_required
def update_skill(skill_name):
    """Replace the content of one of the current user's personal skills."""
    user = _user()
    data = request.get_json() or {}
    content = data.get('content') or ''
    try:
        skills_engine.update_personal_skill(user.id, skill_name, content)
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    _invalidate_chatbot(user)
    return jsonify({"success": True, "skill_name": skill_name, "scope": "personal"})


@skills_bp.route('/api/skills/delete/<skill_name>', methods=['DELETE'])
@login_required
def delete_skill(skill_name):
    """Delete one of the current user's personal skills."""
    user = _user()
    try:
        skills_engine.delete_personal_skill(user.id, skill_name)
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    _invalidate_chatbot(user)
    logger.info(f"User '{user.id}' deleted personal skill '{skill_name}'.")
    return jsonify({"success": True, "skill_name": skill_name})


@skills_bp.route('/api/skills/activate', methods=['POST'])
@login_required
def activate_skill():
    """Activate/deactivate a skill for the current user."""
    user = _user()
    data = request.get_json() or {}
    skill_name = (data.get('skill_name') or '').strip()
    active = bool(data.get('active', True))
    try:
        # Only skills that apply to this user/agent can be toggled.
        merged = skills_engine.discover_skills_for_user(user.id, user._config.agent_skills)
        if skill_name not in merged:
            return jsonify({"success": False, "error": f"Skill '{skill_name}' was not found."}), 404
        skills_engine.set_skill_active(user.id, skill_name, active)
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    _invalidate_chatbot(user)
    return jsonify({"success": True, "skill_name": skill_name, "active": active})

