def get_execution_result_rows(execution_result):
    if not isinstance(execution_result, dict) or not execution_result:
        return {}

    return {
        row_id: row_values
        for row_id, row_values in execution_result.items()
        if isinstance(row_id, str) and row_id.startswith("Row ")
    }

def get_full_execution_result_rows(execution_result):
    if not isinstance(execution_result, dict):
        return {}

    return execution_result.get("full", {})

def limit_execution_result_rows(execution_result, rows_limit):
    rows = get_execution_result_rows(execution_result)
    if not rows or rows_limit is None:
        return rows

    limited_rows = {}
    for index, (row_id, row_values) in enumerate(rows.items(), start=1):
        if index > rows_limit:
            break
        limited_rows[row_id] = row_values
    return limited_rows

def extract_execution_result_row(row_id, row_values):
    row = {'row_id': row_id}
    if not isinstance(row_values, list):
        return row

    for column in row_values:
        if not isinstance(column, dict):
            continue

        column_name = column.get('columnName')
        if not column_name:
            continue

        row[column_name] = column.get('value')

    return row

"""
High-level schema catalog entry point.

`SchemaCatalog` is the canonical in-memory representation of the working data model schema
metadata AFTER it has been normalized from the Data Marketplace JSON payload.

Three different schema representations are supported:

- `embedding`
  - Purpose: semantic retrieval text stored in the vector DB
  - Used by: similarity search / relevant view retrieval
  - Characteristics: compact plain text focused on view meaning and column
    semantics; does not include association lines

- `selector`
  - Purpose: compact schema text for table selection
  - Used by: selector/category detection before query generation
  - Characteristics: plain text with the same table/column grammar as
    `embedding`, but can include association lines for views present in context;

- `vql`
  - Purpose: rich schema context for query generation, query review, and query
    fixing prompts
  - Used by: VQL generation, reviewer, and fixer flows
  - Characteristics: markdown-oriented output with PK / NOT NULL flags, sample
    values, and join lines
"""

from .helpers import build_table_name
from .view import SchemaTable

class SchemaCatalog:
    def __init__(self, views=None):
        self.views = views or []

    @classmethod
    def from_marketplace_json(
        cls,
        json_response,
        use_associations=True,
        use_table_descriptions=True,
        use_column_descriptions=True,
        filter_tables=None,
        view_prefix_filter='',
        view_suffix_filter=''
    ):
        filter_tables = filter_tables or []
        if 'viewsDetails' in json_response:
            json_response = json_response['viewsDetails']

        if not json_response:
            return cls([])

        views = []
        for table in json_response:
            table_database = table.get('databaseName', '')
            raw_table_name = table.get('name', '')
            table_name = build_table_name(table_database, raw_table_name)

            if table_name in filter_tables:
                continue
            if view_prefix_filter and not raw_table_name.startswith(view_prefix_filter):
                continue
            if view_suffix_filter and not raw_table_name.endswith(view_suffix_filter):
                continue

            views.append(
                SchemaTable.from_marketplace_table(
                    table=table,
                    use_associations=use_associations,
                    use_table_descriptions=use_table_descriptions,
                    use_column_descriptions=use_column_descriptions
                )
            )

        return cls(views)

    @classmethod
    def from_storage_json(cls, schema_json):
        if not schema_json or 'views' not in schema_json:
            return cls([])

        return cls([SchemaTable.from_dict(view) for view in schema_json.get('views', [])])

    @classmethod
    def from_vector_search_tables(cls, vector_search_tables):
        views = []
        for table in vector_search_tables:
            if 'view_json' in table:
                views.append(SchemaTable.from_dict(table['view_json']))
            else:
                views.append(SchemaTable.from_dict(table))
        return cls(views)

    def to_storage_json(self):
        if not self.views:
            return None

        return {'views': [view.to_dict() for view in self.views]}

    def to_view_jsons(self):
        return [view.to_dict() for view in self.views]

    def render_selector_schema(self, column_description_char_limit=None, table_description_char_limit=None):
        present_tables = [view.get_name() for view in self.views]
        return "".join(
            view.render_selector_text(column_description_char_limit, table_description_char_limit, present_tables)
            for view in self.views
        )

    def render_vql_schema(self, filtered_tables=None, sample_data=None, examples_per_table=3):
        filtered_tables = filtered_tables or []
        table_lookup = {view.get_name(): view for view in self.views}
        present_tables = [view.get_name() for view in self.views]

        if not filtered_tables:
            return "\n\n".join(
                view.render_vql_text(sample_data, present_tables, examples_per_table)
                for view in self.views
            )

        formatted_tables = []
        for filtered_table in filtered_tables:
            if filtered_table not in table_lookup:
                continue
            formatted_tables.append(
                table_lookup[filtered_table].render_vql_text(sample_data, filtered_tables, examples_per_table)
            )

        if formatted_tables:
            return "\n\n".join(formatted_tables)

        return "\n\n".join(
            view.render_vql_text(sample_data, present_tables, examples_per_table)
            for view in self.views
        )

    def render_metadata_prompt_payload(self):
        return self.to_view_jsons()

    def render_related_tables_payload(self, sample_data=None, examples_per_table=3):
        present_tables = [view.get_name() for view in self.views]
        return [
            {
                "view_name": view.get_name(),
                "view_json": view.to_dict(),
                "vql_representation": view.render_vql_text(
                    sample_data=sample_data,
                    present_tables=present_tables,
                    examples_per_table=examples_per_table
                )
            }
            for view in self.views
        ]

    def selected_tables_have_vector_column(self, selected_table_names):
        if not selected_table_names:
            views = self.views
        else:
            table_lookup = {view.get_name(): view for view in self.views}
            views = [table_lookup[name] for name in selected_table_names if name in table_lookup]
        return any(view.has_vector_column() for view in views)

    def selected_tables_include_metric_view(self, selected_table_names):
        if not selected_table_names:
            views = self.views
        else:
            table_lookup = {view.get_name(): view for view in self.views}
            views = [table_lookup[name] for name in selected_table_names if name in table_lookup]
        return any(view.is_metric_view() for view in views)

    def to_embedding_documents(self, embeddings_token_limit=0):
        documents = []
        for view in self.views:
            documents.append(view.to_embedding_documents(embeddings_token_limit))
        return documents

import tiktoken

def remove_none_values(data):
    if not isinstance(data, dict):
        return data

    cleaned = {}
    for key, value in data.items():
        if value is None:
            continue
        cleaned[key] = value
    return cleaned

def calculate_tokens(string, encoding='cl100k_base'):
    return len(tiktoken.get_encoding(encoding).encode(string))

def split_table_name(table_name):
    if '.' not in table_name:
        return '', table_name

    return table_name.split('.', 1)

def build_table_name(table_database, table_name):
    return f"{table_database}.{table_name}".replace('"', '')

def attach_sample_data(json_table):
    if 'viewFieldDataList' not in json_table:
        return

    sample_data_dict = {}
    for example in json_table['viewFieldDataList']:
        sample_data_dict[example['fieldName'].strip('"')] = example['fieldValues']

    for field in json_table.get('schema', []):
        field_name = field['name'].strip('"')
        field['sample_data'] = sample_data_dict.get(field_name, [])

def normalize_schema_columns(schema, use_column_descriptions):
    normalized_schema = []
    for item in schema:
        normalized_item = {'columnName': item['name']} | {
            key: value for key, value in item.items() if key != 'name'
        }
        if not use_column_descriptions:
            normalized_item.pop('logicalName', None)
            normalized_item.pop('description', None)
        extra = normalized_item.get('extraProperties')
        if extra is not None and not isinstance(extra, dict):
            normalized_item.pop('extraProperties', None)
        normalized_schema.append(normalized_item)

    return normalized_schema

def normalize_associations(association_data, table_database, use_associations):
    if association_data is None:
        return None
    if use_associations is False:
        return []

    associations = []
    for association in association_data:
        other_table = association['viewDetailsOfTheOtherView']['name']
        other_table_db = association['viewDetailsOfTheOtherView']['databaseName']
        mapping = association['mapping'].replace('"', '').split("=")

        for index in range(len(mapping)):
            mapping_table_name = mapping[index].split(".")[0]
            if mapping_table_name != other_table:
                mapping[index] = f"{table_database}.{mapping[index]}"
            else:
                mapping[index] = f"{other_table_db}.{mapping[index]}"

        associations.append({
            'table_name': build_table_name(other_table_db, other_table),
            'table_id': association['viewDetailsOfTheOtherView']['id'],
            'where': " = ".join(mapping),
            'description': association.get('description', "")
        })

    return associations

import json
from time import time

from langchain_core.documents.base import Document

from .helpers import (
    attach_sample_data,
    build_table_name,
    calculate_tokens,
    normalize_associations,
    normalize_schema_columns,
    remove_none_values,
    split_table_name,
)

class SchemaColumn:
    def __init__(self, column_data):
        self._column_data = dict(column_data)

    def to_dict(self):
        return dict(self._column_data)

    def _normalized_logical_name(self):
        logical_name = self._column_data.get('logicalName')
        if logical_name == '':
            return None
        return logical_name

    def _normalized_description(self):
        description = self._column_data.get('description')
        if description:
            description = description.replace("\n", " ").strip()
        else:
            description = None

        if not description:
            return None

        return description

    def _catalog_type_display(self, force_type=None):
        """Denodo type display.

        Uses the VQL data type and falls back to sourceType when type is missing.
        Compound data types (whose sourceType is STRUCT or ARRAY) are rendered with
        the source type as a prefix tag, i.e. [STRUCT] <register_alias> or
        [ARRAY] <array_alias>.
        """
        if force_type:
            return str(self._column_data.get(force_type)).strip()

        type_text = self._column_data.get('type')
        type_text = str(type_text).strip() if type_text is not None else ''

        source_type = self._column_data.get('sourceType')
        source_type = str(source_type).strip() if source_type is not None else ''

        if source_type.upper() in ('STRUCT', 'ARRAY') and type_text:
            return f"[{source_type.upper()}] {type_text}"

        if type_text:
            return type_text
        if source_type:
            return source_type
        return 'unknown'

    def _vql_extra_property_brackets(self):
        raw = self._column_data.get('extraProperties')
        if raw is None or not isinstance(raw, dict) or not raw:
            return []
        brackets = []
        for key in sorted(raw.keys(), key=str):
            name = str(key).strip()
            if not name:
                continue
            value = raw[key]
            if value is None or value == '':
                continue
            value_text = str(value).replace('\n', ' ').strip()
            if not value_text:
                continue
            brackets.append(f"[{name}: {value_text}]")
        return brackets

    def render_plain_line(self, include_descriptions=True, description_limit=None):
        column_name = self._column_data.get('columnName', '').replace('"', '').replace("'", "")
        column_type = self._catalog_type_display()
        logical_name = self._normalized_logical_name()
        description = self._normalized_description()
        column_organization = self._column_data.get('columnOrganization')
        obligatory = self._column_data.get('obligatory', False)

        if not include_descriptions:
            description = None

        if description_limit and description and len(description) > description_limit:
            description = f"{description[:description_limit]}... (truncated)"

        parts = [f"- {column_name} ({column_type})"]

        flags = []
        if column_organization == "metric":
            flags.append("METRIC")
        if obligatory:
            flags.append("OBLIGATORY")

        if flags:
            parts.extend([f"[{flag}]" for flag in flags])

        if logical_name is not None and description is not None:
            parts.append(f"→ {logical_name}: {description}")
        elif logical_name is None and description is not None:
            parts.append(f"→ {description}")
        elif logical_name is not None and description is None:
            parts.append(f"→ {logical_name}")

        return " ".join(parts)

    def render_vql_line(self, sample_values=None, examples_per_table=3):
        name = self._column_data.get('columnName', 'unnamed')
        column_type = self._catalog_type_display()
        logical_name = self._normalized_logical_name()
        description = self._normalized_description()
        primary_key = self._column_data.get('primaryKey', False)
        nullable = self._column_data.get('nullable', True)
        obligatory = self._column_data.get('obligatory', False)
        column_organization = self._column_data.get('columnOrganization')
        examples = sample_values if sample_values is not None else self._column_data.get('sample_data', [])

        flags = []
        if column_organization == "dimension":
            flags.append("DIMENSION")
        elif column_organization == "metric":
            flags.append("METRIC")
        if primary_key:
            flags.append("PK")
        if not nullable:
            flags.append("NOT NULL")
        if obligatory:
            flags.append("OBLIGATORY")

        parts = [f"- {name} ({column_type})"]
        if flags:
            parts.extend([f"[{flag}]" for flag in flags])
        parts.extend(self._vql_extra_property_brackets())
        if logical_name is not None and description is not None:
            parts.append(f"→ {logical_name}: {description if description.endswith('.') else description + '.'}")
        elif logical_name is None and description is not None:
            parts.append(f"→ {description if description.endswith('.') else description + '.'}")
        elif logical_name is not None and description is None:
            parts.append(f"→ {logical_name}.")
        if examples:
            filtered_examples = [example for example in examples if example]
            if filtered_examples:
                parts.append(f"sample values: {', '.join(filtered_examples[:examples_per_table])}")

        return " ".join(parts)

class SchemaAssociation:
    def __init__(self, association_data):
        self._association_data = dict(association_data)

    def to_dict(self):
        return dict(self._association_data)

    def render_line(self):
        association_line = f"→ {self._association_data.get('where')}"
        if self._association_data.get('description'):
            association_line += f". Description: {self._association_data.get('description')}"
        return association_line

class SchemaTable:
    def __init__(self, view_data):
        self._view_data = dict(view_data)

    @classmethod
    def from_dict(cls, view_data):
        return cls(view_data)

    @classmethod
    def from_marketplace_table(
        cls,
        table,
        use_associations=True,
        use_table_descriptions=True,
        use_column_descriptions=True
    ):
        json_table = remove_none_values(table)
        table_database = json_table.get('databaseName', '')
        table_name = build_table_name(table_database, json_table.get('name', ''))

        output_table = {
            'tableName': table_name,
            'description': json_table.get('description', ""),
        }

        attach_sample_data(json_table)

        keys_to_remove = ['name', 'description', 'databaseName', 'viewFieldDataList']
        for key in keys_to_remove:
            json_table.pop(key, None)

        json_table = output_table | json_table
        json_table['schema'] = normalize_schema_columns(
            json_table.get('schema', []),
            use_column_descriptions
        )

        associations = normalize_associations(
            json_table.pop('associationData', None),
            table_database,
            use_associations
        )
        if associations is not None and use_associations is not False:
            json_table['associations'] = associations

        if "description" in json_table and use_table_descriptions is False:
            json_table.pop('description')

        return cls(json_table)

    def to_dict(self):
        return dict(self._view_data)

    def get_id(self):
        return str(self._view_data['id'])

    def get_name(self):
        return self._view_data['tableName']

    def get_database_name(self):
        database_name, _ = split_table_name(self.get_name())
        return database_name

    def is_metric_view(self):
        return self._view_data.get('subtype') == 'metric'

    def has_vector_column(self):
        for column in self._view_data.get('schema', []):
            if 'vector' in SchemaColumn(column)._catalog_type_display(force_type='type').lower():
                return True
        return False

    def get_association_ids(self):
        association_ids = []
        for association in self._view_data.get('associations', []):
            association_ids.append(str(association['table_id']))
        return association_ids

    def _render_plain_text(
        self,
        include_associations=False,
        include_descriptions=True,
        column_description_limit=None,
        table_description_limit=None,
        present_tables=None,
        include_table_type=False
    ):
        present_tables = present_tables or []
        lines = [f"Table: {self.get_name()}"]
        if include_table_type and self.is_metric_view():
            lines.append("Type: METRIC")

        table_description = self._view_data.get('description', '')
        if include_descriptions and table_description and table_description.strip():
            table_description = table_description.replace("\n", " ").strip()
            if table_description_limit and len(table_description) > table_description_limit:
                table_description = f"{table_description[:table_description_limit]}... (truncated)"
            lines.append(f"Description: {table_description}")

        lines.append("Columns:")
        for column in self._view_data.get('schema', []):
            lines.append(
                SchemaColumn(column).render_plain_line(
                    include_descriptions=include_descriptions,
                    description_limit=column_description_limit
                )
            )

        if include_associations:
            association_lines = []
            for association in self._view_data.get('associations', []):
                where_clause = association.get('where')
                if where_clause and sum(table in where_clause for table in present_tables) == 2:
                    association_lines.append(SchemaAssociation(association).render_line())

            if association_lines:
                lines.append("Associations:")
                lines.extend(association_lines)

        return "\n".join(lines) + "\n\n"

    def render_embedding_text(self):
        # Embedding grammar:
        # Table: <database>.<view>
        # Description: <description>
        # Columns:
        # - <column_name> (<type>)
        # - <column_name> (<type>) [METRIC]
        # - <column_name> (<type>) → <description>
        # - <column_name> (<type>) → <logical_name>
        # - <column_name> (<type>) → <logical_name>: <description>
        return self._render_plain_text(
            include_associations=False,
            include_descriptions=True,
            include_table_type=False
        )

    def render_selector_text(self, column_description_char_limit=None, table_description_char_limit=None, present_tables=None):
        # Selector grammar:
        # Table: <database>.<view>
        # Type: METRIC
        # Description: <description>
        # Columns:
        # - <column_name> (<type>)
        # - <column_name> (<type>) [METRIC] [OBLIGATORY]
        # - <column_name> (<type>) → <description> ... (truncated)
        # - <column_name> (<type>) → <logical_name>
        # - <column_name> (<type>) → <logical_name>: <description> ... (truncated)
        # Associations:
        # → <join_clause>. Description: <association_description>
        # → <join_clause>
        return self._render_plain_text(
            include_associations=True,
            include_descriptions=column_description_char_limit is not None and column_description_char_limit > 0,
            column_description_limit=column_description_char_limit,
            table_description_limit=table_description_char_limit,
            present_tables=present_tables,
            include_table_type=True
        )

    def render_vql_text(self, sample_data=None, present_tables=None, examples_per_table=3):
        # VQL grammar:
        # # Table: "<database>"."<view>"
        # ## Type: Metric
        # ## Description: <description>
        # ## Columns:
        # - <column_name> (<type>) [DIMENSION]
        # - <column_name> (<type>) [METRIC]
        # - <column_name> (<type>) [PK] [NOT NULL] [OBLIGATORY] [<extra_key>: <extra_val>] ...
        # - <column_name> (<type>) → <logical_name>
        # - <column_name> (<type>) → <logical_name>: <description>.
        # - <column_name> (<type>) → <logical_name>. sample values: a, b, c
        # - <column_name> (<type>) sample values: a, b, c
        # ## JOINs:
        # → <join_clause>. Description: <association_description>
        # → <join_clause>
        present_tables = present_tables or []
        lines = []
        table_name = self.get_name()
        table_description = self._view_data.get('description', '')
        database_name, view_name = split_table_name(table_name)
        quoted_table_name = f'"{database_name}"."{view_name}"' if database_name else f'"{view_name}"'

        lines.append(f"# Table: {quoted_table_name}")
        if self.is_metric_view():
            lines.append("## Type: Metric")
        if table_description:
            lines.append(f"## Description: {table_description}")
        lines.append("## Columns:")

        table_id = self.get_id()
        table_sample_data = sample_data.get(table_id, {}) if sample_data and table_id in sample_data else {}
        for column in self._view_data.get('schema', []):
            column_name = column.get('columnName')
            column_sample_data = table_sample_data.get(column_name, [])
            lines.append(
                SchemaColumn(column).render_vql_line(
                    sample_values=column_sample_data,
                    examples_per_table=examples_per_table
                )
            )

        association_lines = []
        for association in self._view_data.get('associations', []):
            where_clause = association.get('where')
            if where_clause and sum(table in where_clause for table in present_tables) == 2:
                association_lines.append(SchemaAssociation(association).render_line())

        if association_lines:
            lines.append("## JOINs:")
            lines.extend(association_lines)

        return "\n".join(lines)

    def to_embedding_documents(self, embeddings_token_limit=0):
        table_summary = self.render_embedding_text()
        table_summary_tokens = calculate_tokens(table_summary)
        if embeddings_token_limit and table_summary_tokens > embeddings_token_limit:
            return self._create_chunk_documents(embeddings_token_limit)

        metadata = {
            "view_name": self.get_name(),
            "view_json": json.dumps(self.to_dict()),
            "view_id": self.get_id(),
            "document_id": self.get_id(),
            "database_name": self.get_database_name(),
            "last_update": int(time() * 1000)
        }

        for tag in self._view_data.get('tagDetails', []):
            metadata[f"tag_{tag['name']}"] = "1"

        return Document(
            id=self.get_id(),
            page_content=table_summary,
            metadata=metadata
        )

    def _create_chunk_documents(self, embeddings_token_limit):
        summary = self.render_embedding_text()
        parts = summary.split("Columns:\n", 1)
        header = parts[0] + "Columns:\n"
        content = parts[1] if len(parts) > 1 else ""

        lines = content.split("\n")
        column_lines = []
        association_lines = []
        for line in lines:
            if line.startswith("This table is also associated"):
                association_lines.append(line)
            elif line.strip():
                column_lines.append(line)

        association_footer = "\n" + "\n".join(association_lines) if association_lines else ""
        base_tokens = calculate_tokens(header + association_footer)
        available_tokens = (embeddings_token_limit - 500) - base_tokens

        column_content = "\n".join(column_lines)
        total_tokens = calculate_tokens(column_content)
        target_chunks = (total_tokens // available_tokens) + 1
        chunk_size = max(1, len(column_lines) // target_chunks)

        chunks = []
        for index in range(0, len(column_lines), chunk_size):
            current_lines = column_lines[index:index + chunk_size]
            chunk_content = header + "\n".join(current_lines) + association_footer + "\n"
            document_id = f"{self.get_id()}_{len(chunks)}"
            metadata = {
                "view_name": self.get_name(),
                "view_json": json.dumps(self.to_dict()),
                "view_id": self.get_id(),
                "document_id": document_id,
                "database_name": self.get_database_name()
            }

            for tag in self._view_data.get('tagDetails', []):
                metadata[f"tag_{tag['name']}"] = "1"

            chunks.append(Document(
                id=document_id,
                page_content=chunk_content,
                metadata=metadata
            ))

        return chunks

import os
import json
import time
import logging
import concurrent.futures
from utils.utils import log_params, prepare_last_update_vector, timed

class UniformVectorStore:
    def __init__(self, provider, embeddings, index_name = "ai_sdk_vector_store", rate_limit_rpm = None, chunk_factor = 5):
        self.provider = provider.lower()
        self.embeddings = embeddings
        self.index_name = index_name
        self.rate_limit_rpm = rate_limit_rpm
        self.client = None
        self.search_vector = self.embeddings.embed_query("tables")
        self.dimensions = len(self.search_vector)
        self.chunk_factor = chunk_factor
        self._connect()

    def _connect(self):
        if self.provider == "chroma":
            import platform
            if platform.system() == "Linux":
                __import__('pysqlite3')
                import sys
                sys.modules['sqlite3'] = sys.modules.pop('pysqlite3')
            from chromadb.config import Settings
            from langchain_chroma import Chroma
            data_dir = os.getenv("AI_SDK_DATA_DIR", ".")
            persist_dir = os.path.join(data_dir, self.index_name)

            self.client = Chroma(
                collection_name=self.index_name,
                embedding_function=self.embeddings,
                persist_directory=persist_dir,
                collection_metadata={
                    "hnsw:space": "cosine",
                    "hnsw:construction_ef": 512,
                    "hnsw:search_ef": 256,
                    "hnsw:M": 256
                },
                client_settings = Settings(
                    anonymized_telemetry=False,
                    is_persistent=True
                )
            )
        elif self.provider == "pgvector":
            from langchain_postgres import PGVector
            from sqlalchemy import create_engine

            PGVECTOR_CONNECTION_STRING = os.getenv("PGVECTOR_CONNECTION_STRING")

            if not PGVECTOR_CONNECTION_STRING:
                raise ValueError("PGVECTOR_CONNECTION_STRING environment variable not set.")

            engine = create_engine(
                PGVECTOR_CONNECTION_STRING,
                pool_pre_ping=True, # Test connection before use to handle dropped connections
                pool_recycle=1800, # Recycle connections after 1800 seconds
            )

            self.client = PGVector(
                embeddings=self.embeddings,
                connection=engine,
                collection_name=self.index_name,
                use_jsonb=True,
            )
        elif self.provider == "opensearch":
            from langchain_community.vectorstores import OpenSearchVectorSearch

            OPENSEARCH_URL = os.getenv("OPENSEARCH_URL", "http://localhost:9200")
            OPENSEARCH_USERNAME = os.getenv("OPENSEARCH_USERNAME", "admin")
            OPENSEARCH_PASSWORD = os.getenv("OPENSEARCH_PASSWORD", "admin")

            if not OPENSEARCH_URL:
                raise ValueError("OPENSEARCH_URL environment variable not set.")
            if not OPENSEARCH_USERNAME:
                raise ValueError("OPENSEARCH_USERNAME environment variable not set.")
            if not OPENSEARCH_PASSWORD:
                raise ValueError("OPENSEARCH_PASSWORD environment variable not set.")

            self.client = OpenSearchVectorSearch(
                opensearch_url = OPENSEARCH_URL,
                http_auth = (OPENSEARCH_USERNAME, OPENSEARCH_PASSWORD),
                embedding_function = self.embeddings,
                index_name = self.index_name,
                engine="faiss",
                use_ssl = True,
                verify_certs = False,
                ssl_assert_hostname = False,
                ssl_show_warn = False,
            )

            if not self.client.client.indices.exists(index=self.index_name):
                self.client.create_index(
                    dimension=self.dimensions,
                    index_name=self.index_name,
                    engine="faiss"
                )
        elif self.provider == "oracle":
            import oracledb
            from langchain_oracledb.vectorstores import OracleVS
            from langchain_oracledb.vectorstores.oraclevs import DistanceStrategy

            ORACLE_USERNAME = os.getenv("ORACLE_USERNAME")
            ORACLE_PASSWORD = os.getenv("ORACLE_PASSWORD")
            ORACLE_DSN = os.getenv("ORACLE_DSN")

            if not all([ORACLE_USERNAME, ORACLE_PASSWORD, ORACLE_DSN]):
                raise ValueError("ORACLE_USERNAME, ORACLE_PASSWORD, and ORACLE_DSN environment variables must be set.")

            try:
                connection = oracledb.connect(
                    user=ORACLE_USERNAME,
                    password=ORACLE_PASSWORD,
                    dsn=ORACLE_DSN
                )
            except Exception as e:
                raise ConnectionError(f"Failed to connect to Oracle Database: {e}")

            self.client = OracleVS(
                client=connection,
                embedding_function=self.embeddings,
                table_name=self.index_name,
                distance_strategy=DistanceStrategy.COSINE,
            )
        else:
            raise ValueError(f"Unsupported vector store provider: {self.provider}")

    def get_last_update_dict(self):
        search_vector = self.search_by_vector(self.search_vector, k = 1, view_ids = ["last_update"])
        if search_vector and 'last_update_dict' in search_vector[0].metadata:
            return json.loads(search_vector[0].metadata['last_update_dict'])
        else:
            return None

    def get_partial_resources_dict(self):
        search_vector = self.search_by_vector(self.search_vector, k=1, view_ids=["last_update"])
        if search_vector and 'partial_resources_dict' in search_vector[0].metadata:
            return json.loads(search_vector[0].metadata['partial_resources_dict'])
        else:
            return None

    @timed
    def get_sync_metadata(self):
        search_vector = self.search_by_vector(self.search_vector, k=1, view_ids=["last_update"])

        last_update_dict = None
        partial_resources_dict = None

        if search_vector:
            metadata = search_vector[0].metadata

            if 'last_update_dict' in metadata:
                last_update_dict = json.loads(metadata['last_update_dict'])

            if 'partial_resources_dict' in metadata:
                partial_resources_dict = json.loads(metadata['partial_resources_dict'])

        return last_update_dict, partial_resources_dict

    @timed
    def get_last_update(self, source_type, source_name):
        last_update_dict = self.get_last_update_dict()
        if last_update_dict and source_type in last_update_dict and source_name in last_update_dict[source_type]:
            return int(last_update_dict[source_type][source_name])
        else:
            return None

    @timed
    def update_last_update(self, last_update_dict, partial_resources_dict):
        self.client.delete(ids=["last_update"])
        self.client.add_documents(
            prepare_last_update_vector(last_update_dict, partial_resources_dict),
            ids=["last_update"]
        )

    @timed
    def remove_from_last_update(self, database_names=None, tag_names=None):
        last_update_dict, partial_resources_dict = self.get_sync_metadata()
        modified = False

        if last_update_dict:
            if database_names and "DATABASE" in last_update_dict:
                for db_name in database_names:
                    if db_name in last_update_dict["DATABASE"]:
                        del last_update_dict["DATABASE"][db_name]
                        modified = True
                if not last_update_dict["DATABASE"]:
                    del last_update_dict["DATABASE"]
                    modified = True

            if tag_names and "TAG" in last_update_dict:
                for tag_name in tag_names:
                    if tag_name in last_update_dict["TAG"]:
                        del last_update_dict["TAG"][tag_name]
                        modified = True
                if not last_update_dict["TAG"]:
                    del last_update_dict["TAG"]
                    modified = True

        if partial_resources_dict:
            if database_names and "partial_tags_by_db" in partial_resources_dict:
                partial_tags_by_db = partial_resources_dict["partial_tags_by_db"]
                for db_name in database_names:
                    if db_name in partial_tags_by_db:
                        del partial_tags_by_db[db_name]
                        modified = True

            if tag_names:
                if "partial_dbs_by_tag" in partial_resources_dict:
                    partial_dbs_by_tag = partial_resources_dict["partial_dbs_by_tag"]
                    for tag_name in tag_names:
                        if tag_name in partial_dbs_by_tag:
                            del partial_dbs_by_tag[tag_name]
                            modified = True

                if "partial_tags_by_tag" in partial_resources_dict:
                    partial_tags_by_tag = partial_resources_dict["partial_tags_by_tag"]
                    for tag_name in tag_names:
                        if tag_name in partial_tags_by_tag:
                            del partial_tags_by_tag[tag_name]
                            modified = True

        if modified:
            self.update_last_update(last_update_dict, partial_resources_dict)

    @log_params
    @timed
    def search(self, query, k=3, view_ids=None, database_names=None, tag_names=None, view_names=None, scores=False):
        # If view_ids is provided and it's empty, return empty list
        if view_ids is not None and len(view_ids) == 0:
            return []
        # Build search filter if view_ids has values
        elif view_ids is not None:
            search_filter = self._build_search_filter(view_ids, database_names, tag_names, view_names)
        elif not view_names and ((database_names and len(database_names) > 0) or (tag_names and len(tag_names) > 0)):
            search_filter = self._build_metadata_search_filter(database_names, tag_names)
        elif view_names:
            search_filter = self._build_get_view_ids_search_filter(view_names)
        else:
            search_filter = None

        if scores:
            if self.provider == "opensearch":
                return self.client.similarity_search_with_score(query, k=k, search_type="script_scoring", pre_filter=search_filter)
            elif self.provider in ["chroma", "pgvector", "oracle"]:
                return self.client.similarity_search_with_score(query, k=k, filter=search_filter)
        else:
            if self.provider == "opensearch":
                return self.client.similarity_search(query, k=k, search_type="script_scoring", pre_filter=search_filter)
            elif self.provider in ["chroma", "pgvector", "oracle"]:
                return self.client.similarity_search(query, k=k, filter=search_filter)

    @log_params
    @timed
    def search_by_vector(self, vector, k=3, view_ids=None, database_names=None, tag_names=None, view_names=None, scores=False):
        # If view_ids is provided and it's empty, return empty list
        if view_ids is not None and len(view_ids) == 0:
            return []
        # Build search filter if view_ids has values
        elif view_ids is not None:
            search_filter = self._build_search_filter(view_ids, database_names, tag_names, view_names)
        elif not view_names and ((database_names and len(database_names) > 0) or (tag_names and len(tag_names) > 0)):
            search_filter = self._build_metadata_search_filter(database_names, tag_names)
        else:
            search_filter = self._build_get_view_ids_search_filter(view_names)

        if scores:
            if self.provider == "opensearch":
                return self.client.similarity_search_with_score_by_vector(vector, k=k, search_type="script_scoring", pre_filter=search_filter)
            elif self.provider in ["pgvector", "oracle"]:
                return self.client.similarity_search_with_score_by_vector(vector, k=k, filter=search_filter)
            elif self.provider == "chroma":
                return self.client.similarity_search_by_vector_with_relevance_scores(vector, k=k, filter=search_filter)
        else:
            if self.provider == "opensearch":
                return self.client.similarity_search_by_vector(vector, k=k, search_type="script_scoring", pre_filter=search_filter)
            elif self.provider in ["chroma", "pgvector", "oracle"]:
                return self.client.similarity_search_by_vector(vector, k=k, filter=search_filter)

    @log_params
    def _build_metadata_search_filter(self, database_names=None, tag_names=None):
        """
        Builds a search filter for metadata-only queries (database_names, tag_names)
        using OR logic across the provided lists.
        """
        or_conditions = []

        if database_names:
            for db_name in database_names:
                if self.provider == "opensearch":
                    or_conditions.append({"match": {"metadata.database_name": db_name}})
                elif self.provider in ["chroma", "pgvector", "oracle"]:
                    or_conditions.append({"database_name": {"$eq": db_name}})

        if tag_names:
            for tag_name in tag_names:
                if self.provider == "opensearch":
                    or_conditions.append({"match": {f"metadata.tag_{tag_name}": "1"}})
                elif self.provider in ["chroma", "pgvector", "oracle"]:
                    or_conditions.append({f"tag_{tag_name}": {"$eq": "1"}})

        if not or_conditions:
            return None # No filter to apply if no conditions were added

        if self.provider == "opensearch":
            if len(or_conditions) == 1:
                return or_conditions[0] # If only one OR condition, return it directly
            return {"bool": {"should": or_conditions, "minimum_should_match": 1}}
        elif self.provider in ["chroma", "pgvector", "oracle"]:
            if len(or_conditions) == 1:
                return or_conditions[0] # If only one OR condition, return it directly
            return {"$or": or_conditions}
        else:
            return None

    @log_params
    def _build_get_view_ids_search_filter(self, view_names):
        if self.provider == "opensearch":
            #return {"metadata.view_name": {"$in": view_names}}
            return {"terms": {
                "metadata.view_name.keyword": view_names
            }}
        elif self.provider in ["chroma", "pgvector", "oracle"]:
            return {"view_name": {"$in": view_names}}
        else:
            return None

    @log_params
    def _build_search_filter(self, view_ids, database_names=None, tag_names=None, view_names=None):
        # Check if any additional filters are provided
        has_additional_filters = database_names or tag_names or view_names

        if self.provider == "opensearch":
            # If no additional filters, return a simple terms filter for view_ids
            if not has_additional_filters:
                return {
                    "terms": {
                        "metadata.view_id": view_ids
                    }
                }

            # Otherwise, create the more complex filter with boolean logic
            filter_query = {
                "bool": {
                    "must": [
                        {
                            "terms": {
                                "metadata.view_id": view_ids
                            }
                        }
                    ]
                }
            }

            # Add additional filters if provided
            or_conditions = []

            # Add database name conditions
            if database_names:
                for db_name in database_names:
                    or_conditions.append({
                        "match": {
                            "metadata.database_name": db_name
                        }
                    })

            # Add tag conditions
            if tag_names:
                for tag_name in tag_names:
                    or_conditions.append({
                        "match": {
                            f"metadata.tag_{tag_name}": "1"
                        }
                    })

            # Add view name conditions
            if view_names:
                for view_name in view_names:
                    or_conditions.append({
                        "match": {
                            "metadata.view_name": view_name
                        }
                    })

            # Add the conditions to the filter
            if len(or_conditions) == 1:
                # If only one condition, add it directly to must
                filter_query["bool"]["must"].append(or_conditions[0])
            elif len(or_conditions) > 1:
                # If multiple conditions, use should with minimum_should_match
                filter_query["bool"]["must"].append({
                    "bool": {
                        "should": or_conditions,
                        "minimum_should_match": 1
                    }
                })

            return filter_query

        elif self.provider in ['chroma', 'pgvector', 'oracle']:
            # If no additional filters, return a simple filter for view_ids
            if not has_additional_filters:
                return {"view_id": {"$in": view_ids}}

            # Otherwise, create the more complex filter with $and
            filter_query = {
                "$and": [
                    {"view_id": {"$in": view_ids}}
                ]
            }

            # Add additional filters if provided
            or_conditions = []

            # Add database name conditions
            if database_names:
                for db_name in database_names:
                    or_conditions.append({"database_name": {"$eq": db_name}})

            # Add tag conditions
            if tag_names:
                for tag_name in tag_names:
                    or_conditions.append({f"tag_{tag_name}": {"$eq": "1"}})

            # Add view name conditions
            if view_names:
                for view_name in view_names:
                    or_conditions.append({"view_name": {"$eq": view_name}})

            # Add the conditions to the filter
            if len(or_conditions) == 1:
                # If only one condition, add it directly to $and
                filter_query["$and"].append(or_conditions[0])
            elif len(or_conditions) > 1:
                # If multiple conditions, use $or
                filter_query["$and"].append({"$or": or_conditions})

            return filter_query
        else:
            return None

    def delete(self, ids, batch_size = 1000):
        for i in range(0, len(ids), batch_size):
            batch_ids = ids[i:i+batch_size]
            self.client.delete(ids=batch_ids)

    def add_views(self, views, parallel = True, source_type = "OTHER", source_name = "default", sample_data = False, tags_by_db=None, dbs_by_tag=None, tags_by_tag=None):
        views = list({view.id: view for view in views}.values())

        if source_type in ["DATABASE", "TAG"]:
            view_ids = []
            ids_to_delete_set = set()

            for view in views:
                view_ids.append(view.id)
                if 'view_id' in view.metadata:
                    ids_to_delete_set.add(view.metadata.get('view_id'))
                else:
                    ids_to_delete_set.add(view.id)

            ids_to_delete = list(ids_to_delete_set)

            if ids_to_delete:
                self.delete_by_view_id(view_ids = ids_to_delete)
        else:
            view_ids = [view.id for view in views]
            if view_ids:
                self.delete(ids = view_ids)

        # If rate limiting is enabled, process views in batches
        if self.rate_limit_rpm and len(view_ids) > self.rate_limit_rpm:
            logging.info(f"Rate limiting enabled: {self.rate_limit_rpm} views per minute. Total views: {len(view_ids)}")

            # Process views in batches based on rate limit
            for i in range(0, len(view_ids), self.rate_limit_rpm):
                batch_end = min(i + self.rate_limit_rpm, len(view_ids))
                batch_views = views[i:batch_end]
                batch_ids = view_ids[i:batch_end]

                logging.info(f"Processing batch {i//self.rate_limit_rpm + 1}: {len(batch_views)} views")

                # Process this batch using existing methods
                if parallel:
                    try:
                        self._add_views_parallel(batch_views, batch_ids)
                    except Exception as e:
                        logging.warning(f"Parallel processing failed: {str(e)}. Falling back to sequential processing.")
                        self.client.add_documents(batch_views, ids=batch_ids)
                else:
                    self.client.add_documents(batch_views, ids=batch_ids)

                # If there are more batches to process, wait for the next minute
                if batch_end < len(views):
                    wait_time = 60  # Wait 1 minute
                    logging.info(f"Waiting {wait_time} seconds before processing next batch...")
                    time.sleep(wait_time)
        else:
            # Process all views at once (original behavior)
            if parallel:
                try:
                    self._add_views_parallel(views, view_ids)
                except Exception as e:
                    logging.warning(f"Parallel processing failed: {str(e)}. Falling back to sequential processing.")
                    self.client.add_documents(views, ids=view_ids)
            else:
                self.client.add_documents(views, ids=view_ids)

        if source_type in ["DATABASE", "TAG"] and not sample_data:
            last_update_timestamp = int(time.time() * 1000)

            current_last_update_dict, current_partial_resources_dict = self.get_sync_metadata()

            if current_last_update_dict or current_partial_resources_dict:
                self.client.delete(ids=["last_update"])

            new_partial_resources = {
                "partial_tags_by_db": {k: list(v) for k, v in (tags_by_db or {}).items()},
                "partial_dbs_by_tag": {k: list(v) for k, v in (dbs_by_tag or {}).items()},
                "partial_tags_by_tag": {k: list(v) for k, v in (tags_by_tag or {}).items()}
            }

            docs_to_save = prepare_last_update_vector(
                last_update_dict=current_last_update_dict,
                partial_resources_dict=current_partial_resources_dict,
                new_partial_resources=new_partial_resources,
                last_update=last_update_timestamp,
                source_type=source_type,
                source_name=source_name
            )

            self.client.add_documents(docs_to_save, ids=["last_update"])

    def _add_views_parallel(self, views, ids, batch_size=5, max_retries=3):
        """Add views in parallel with batching and error handling."""

        def process_batch(batch_views, batch_ids, attempt=1):
            try:
                self.client.add_documents(batch_views, ids=batch_ids)
                return True, None
            except Exception as e:
                if attempt < max_retries:
                    logging.warning(f"Attempt {attempt} failed: {str(e)}. Retrying...", exc_info=True)
                    time.sleep(5**attempt)
                    return process_batch(batch_views, batch_ids, attempt + 1)
                return False, (batch_views, batch_ids, str(e))

        # Create batches
        batches = [
            (views[i:i + batch_size], ids[i:i + batch_size])
            for i in range(0, len(views), batch_size)
        ]

        failed_batches = []

        # Process batches in parallel
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = [
                executor.submit(process_batch, batch_views, batch_ids)
                for batch_views, batch_ids in batches
            ]

            # Collect results and handle failures
            for future in concurrent.futures.as_completed(futures):
                success, result = future.result()
                if not success:
                    failed_batch_views, failed_batch_ids, error = result
                    failed_batches.append((failed_batch_views, failed_batch_ids))
                    logging.error(f"Batch processing failed: {error}")

        # Handle any failed batches sequentially
        if failed_batches:
            logging.warning(f"Processing {len(failed_batches)} failed batches sequentially")
            for failed_views, failed_ids in failed_batches:
                try:
                    self.client.add_documents(failed_views, ids=failed_ids)
                except Exception as e:
                    logging.error(f"Fatal error processing batch: {str(e)}")
                    raise RuntimeError(f"Failed to process views after all retries: {str(e)}")

    @log_params
    def get_view_ids(self, view_names):
        view_ids = self.search_by_vector(self.search_vector, k = len(view_names) * self.chunk_factor, view_names = view_names)
        return [view.metadata['view_id'] for view in view_ids]

    @log_params
    def get_views(self, view_ids):
        if len(view_ids) == 0:
            return []

        views = self.search_by_vector(self.search_vector, k=len(view_ids) * self.chunk_factor, view_ids=view_ids)

        # Create a dictionary to keep only unique views based on view_name
        # Necessary because now there might be chunks of the same view
        unique_views = {}
        for view in views:
            view_name = view.metadata['view_name']
            if view_name not in unique_views:
                unique_views[view_name] = view

        return list(unique_views.values())

    @log_params
    def delete_views(self, view_names):
        # Create tasks for each view name
        results = [self.get_view_ids([view_name]) for view_name in view_names]

        # Flatten the results and convert to strings
        view_ids = [str(id) for sublist in results for id in sublist]

        if view_ids:
            self.delete(view_ids)

    @log_params
    def delete_by_view_id(self, view_ids=None):
        """
        Iteratively deletes all documents matching the given view ids.
        Continues fetching and deleting in batches until none are left.
        """
        K_BATCH_SIZE = 1000
        more_results_left = True

        while more_results_left:
            results = self.search_batched(
                vector=self.search_vector,
                k=K_BATCH_SIZE,
                view_ids=view_ids
            )

            if not results:
                break

            ids_to_delete = list(set(
                doc.metadata.get('document_id')
                for doc in results
                if 'document_id' in doc.metadata
            ))

            self.delete(ids=ids_to_delete)

            more_results_left = len(results) == K_BATCH_SIZE

    def check_existence(self, view_ids, database_names=None, tag_names=None):
        """
        Checks if ANY document exists for the given view_ids/filters, handling batching.
        Returns True immediately if found.
        """
        BATCH_SIZE = 30000
        total_ids = len(view_ids) if view_ids else 0

        if view_ids is not None and total_ids == 0:
            return False

        if not view_ids or total_ids <= BATCH_SIZE:
            results = self.search_by_vector(
                vector=self.search_vector,
                k=1, # We only need to know if at least 1 exists
                view_ids=view_ids,
                database_names=database_names,
                tag_names=tag_names
            )
            return bool(results)

        for i in range(0, total_ids, BATCH_SIZE):
            batch_ids = view_ids[i : i + BATCH_SIZE]

            if self.search_by_vector(
                vector=self.search_vector,
                k=1, # We only need to know if at least 1 exists
                view_ids=batch_ids,
                database_names=database_names,
                tag_names=tag_names
            ):
                return True

        return False

    def search_batched(self, k, view_ids=None, query=None, vector=None, scores=False, **kwargs):
        """
        Performs a search (text or vector) handling large lists of view_ids by batching.
        Safe to use with >65k view_ids on Postgres.
        """

        BATCH_SIZE = 30000
        total_ids = len(view_ids) if view_ids else 0

        if view_ids is not None and total_ids == 0:
            return []

        if vector is not None:
            search_method = self.search_by_vector
            search_arg = vector
        else:
            search_method = self.search
            search_arg = query

        if not view_ids or total_ids <= BATCH_SIZE:
            return search_method(search_arg, k=k, view_ids=view_ids, scores=scores, **kwargs)

        all_candidates = []
        for i in range(0, total_ids, BATCH_SIZE):
            batch_ids = view_ids[i : i + BATCH_SIZE]
            batch_results = search_method(search_arg, k=k, view_ids=batch_ids, scores=True, **kwargs)
            all_candidates.extend(batch_results)

        # Sort by score (distance ascending for most VectorStores)
        # Check if results are tuples (doc, score)
        if all_candidates and isinstance(all_candidates[0], tuple):
            all_candidates.sort(key=lambda x: x[1])

        top_k = all_candidates[:k]

        if not scores:
            return [item[0] if isinstance(item, tuple) else item for item in top_k]

        return top_k

